def run(command, **options):
    result = subprocess.run(command, capture_output=True, text=True, **options)
    if result.returncode:
        raise AssertionError(
            f"Command failed: {shlex.join(map(str, command))}\n"
            f"{result.stdout}{result.stderr}"
        )
    return result.stdout


def link_freebasic_standalone_interfaces(source_directory, destination):
    destination.mkdir(parents=True, exist_ok=True)
    for interface in source_directory.glob("*.bi"):
        # Implementation fragments are compiled through their owning .bas unit.
        if interface.stem.endswith("_body"):
            continue
        # FTS5's generated catalogs repeat core SQLite ABI records and belong
        # in source-specific contexts, not the combined core test catalog.
        if interface.name.startswith("sqlite3_fts5_") and \
           interface.name.endswith("_types.bi"):
            continue
        (destination / interface.name).symlink_to(interface)


def copy_freebasic_interface_closure(source_directory, destination, interfaces):
    pending = list(interfaces)
    copied = set()
    while pending:
        interface_name = pending.pop()
        if interface_name in copied:
            continue
        source = source_directory / interface_name
        if not source.is_file():
            continue
        copied.add(interface_name)
        target = destination / interface_name
        if target.exists():
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)
        pending.extend(re.findall(
            r'^\s*#include(?:\s+once)?\s+"([^"]+)"',
            source.read_text(encoding="utf-8"), re.M))


def procedure_names(text):
    return set(re.findall(r"^(?:Private )?(?:Function|Sub) (c2fb\w+)", text, re.M))


def check_api_routines_regeneration(converter, work):
    # The owner includes the checked-in table, while profile generation writes
    # to a separate directory. The checked-in declarations must not suppress
    # the forward declarations needed by the generated profile table.
    source = work / "api-routines-source.i"
    source.write_text(
        "struct sqlite3_api_routines {\n"
        "    void (*sqlite3_test_api)(void);\n"
        "    void *(*sqlite3_deserialize)(void);\n"
        "    void *(*sqlite3_serialize)(void);\n"
        "};\n"
        "static const sqlite3_api_routines sqlite3Apis = {\n"
        "    sqlite3_test_api, sqlite3_deserialize, sqlite3_serialize\n"
        "};\n"
    )
    ledger = work / "api-routines-functions.csv"
    with ledger.open("w", encoding="utf-8", newline="") as csv_file:
        writer = csv.writer(csv_file, lineterminator="\n")
        writer.writerow([
            "Upstream source", "Function", "Start line", "End line", "Lines",
            "Size class", "Port status", "Notes",
        ])
        writer.writerows([
            ["src/main.c", "sqlite3_test_api", 1, 1, 1, "small", "FB body present", ""],
            ["src/memdb.c", "sqlite3_deserialize", 1, 1, 1, "small", "FB body present", ""],
            ["src/memdb.c", "sqlite3_serialize", 1, 1, 1, "small", "FB body present", ""],
        ])
    source_table = work / "sqlite3_extension_api_table.bi"
    generated_directory = work / "generated-api-table"
    generated_directory.mkdir()
    output = generated_directory / "sqlite3_extension_api_table.bi"
    owner = work / "api-routines-owner.bas"
    generated_body = work / "api-routines-generated-body.bas"
    owner.write_text('#include once "sqlite3_extension_api_table.bi"\n')
    source_table.write_text(
        'Declare Function sqlite3_test_api CDecl Alias "sqlite3_test_api" '
        '() As Any Ptr\n'
    )
    generated_body.write_text(
        'Function sqlite3_test_api CDecl Alias "sqlite3_test_api" () As Any Ptr\n'
        '    Return 0\n'
        'End Function\n'
    )
    command = [
        converter, "api-routines", str(source), str(ledger), str(owner), str(output)
    ]
    for _ in range(2):
        run(command)
        generated = output.read_text()
        assert generated.count('Declare Function sqlite3_test_api ') == 1, generated
        assert "ProcPtr(sqlite3_test_api)" in generated, generated
        assert generated.count("#ifndef SQLITE_OMIT_DESERIALIZE") == 2, generated
        assert re.search(
            r"#ifndef SQLITE_OMIT_DESERIALIZE\s+"
            r"sqlite3Apis\(1\) = CPtr\(Any Ptr, ProcPtr\(sqlite3_deserialize\)\)\s+"
            r"#endif",
            generated,
        ), generated
        assert re.search(
            r"#ifndef SQLITE_OMIT_DESERIALIZE\s+"
            r"sqlite3Apis\(2\) = CPtr\(Any Ptr, ProcPtr\(sqlite3_serialize\)\)\s+"
            r"#endif",
            generated,
        ), generated


def check_body_candidate_growth(converter, body_catalog, work):
    source = work / "body-candidate-growth.c"
    source.write_text("".join(
        f"int c2fbCapacity{index}(int value) {{ return value; }}\n"
        for index in range(300)
    ))
    output = work / "body-candidate-growth.bas"
    run([converter, "translate-simple", str(source), str(output), str(body_catalog)])
    expected = {f"c2fbCapacity{index}" for index in range(300)}
    actual = procedure_names(output.read_text())
    assert actual == expected, (
        f"Candidate storage growth lost functions: {expected - actual}; "
        f"unexpected: {actual - expected}"
    )


def check_body_candidate_skip_summary(converter, work):
    # Bulk runs must distinguish unsupported bodies from duplicate definitions.
    source = work / "body-candidate-skip-summary.c"
    source.write_text(
        "int c2fbSummaryAccepted(int value) { return value; }\n"
        "int c2fbSummaryUnsupported(int value) {\n"
        '    __asm__("nop");\n'
        "    return value;\n"
        "}\n"
        "int c2fbSummaryDuplicate(int value) { return value; }\n"
        "int c2fbSummaryDuplicate(int value) { return value + 1; }\n"
    )
    candidate = work / "body-candidate-skip-summary.bas"
    command = [
        converter, "translate-simple-generic-c", str(source),
        str(candidate), "cc",
    ]
    summary = run(command)
    assert "translated 1 simple functions; skipped 2" in summary, summary
    assert (
        "c2fb candidate skips: unsupported=1, duplicates=1, dependencies=0, "
        "already-ported=0, other=0"
    ) in summary, summary
    generated = candidate.read_text()
    assert "Function c2fbSummaryAccepted" in generated, generated
    assert "c2fb skipped c2fbSummaryUnsupported:" in generated, generated
    assert "c2fb skipped c2fbSummaryDuplicate: multiple source definitions" \
        in generated, generated


def check_generic_body_long_boolean_chains(converter, fbc, work):
    # Long C boolean chains must stay shallow enough for the target compiler.
    source = work / "long-boolean-chains.c"
    or_terms = [f"value == {index}" for index in range(128)]
    and_terms = ["value >= 0", "value <= 127"] + [
        f"value != {1000 + index}" for index in range(126)
    ]
    source.write_text(
        "int c2fbLongOrChain(int value) {\n"
        "    return " + " || ".join(or_terms) + ";\n"
        "}\n"
        "int c2fbLongAndChain(int value) {\n"
        "    return " + " && ".join(and_terms) + ";\n"
        "}\n"
    )
    candidate = work / "long-boolean-chains.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), "cc",
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    logical_lines = [
        line for line in generated.splitlines()
        if "OrElse" in line or "AndAlso" in line
    ]
    assert logical_lines and max(map(len, logical_lines)) < 12000, generated

    wrapper = work / "check-long-boolean-chains.bas"
    wrapper.write_text(
        '#include once "long-boolean-chains.bas"\n'
        "If c2fbLongOrChain(0) <> 1 Then End 1\n"
        "If c2fbLongOrChain(127) <> 1 Then End 2\n"
        "If c2fbLongOrChain(128) <> 0 Then End 3\n"
        "If c2fbLongAndChain(64) <> 1 Then End 4\n"
        "If c2fbLongAndChain(1017) <> 0 Then End 5\n"
        "If c2fbLongAndChain(-1) <> 0 Then End 6\n"
    )
    executable = work / "check-long-boolean-chains"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)], cwd=work)
    run([str(executable)], cwd=work)


def check_generic_body_tree_catalog_field_growth(converter, work):
    # The project-wide layout catalog spans declaration-sized source batches.
    source_directory = work / "generic-body-tree-catalog-field-growth-source"
    source_directory.mkdir()
    output_directory = work / "generic-body-tree-catalog-field-growth-output"
    field_count = 6600
    units = tuple(f"unit{index}" for index in range(5))
    for unit in units:
        fields = "".join(
            f"    int field{index:04d};\n" for index in range(field_count)
        )
        (source_directory / f"{unit}.c").write_text(
            f"struct C2fbCatalogRecord_{unit} {{\n{fields}}};\n"
            f"int c2fbCatalogUnit_{unit}(void) {{ return 1; }}\n"
        )

    summary = run([
        converter, "translate-simple-generic-tree-c", str(source_directory),
        str(output_directory), "cc",
    ])
    assert "processed 5 preprocessed C source files" in summary, summary
    for unit in units:
        candidate = output_directory / f"{unit}_candidates.bas"
        assert candidate.is_file(), f"Missing tree candidate: {candidate}"
        assert f"Function c2fbCatalogUnit_{unit}" in candidate.read_text()


def check_generic_header_case_insensitive_record_fields(converter, fbc, work):
    header = work / "case-insensitive-record-fields.h"
    output = work / "case-insensitive-record-fields.bi"
    header.write_text(
        "struct c2fb_case_field_names {\n"
        "    int field;\n"
        "    int FIELD;\n"
        "    int field_;\n"
        "};\n"
    )
    run([converter, "generic-header", str(header), str(output), "cc"])
    generated = output.read_text()
    record_match = re.search(
        r"(?ms)^Type _c2fb_record_c2fb_c2fb_case_field_names\s*\n"
        r"(.*?)^End Type$", generated)
    assert record_match is not None, generated
    field_names = re.findall(r"^\s*(\w+)\s+As\s+", record_match.group(1), re.M)
    assert field_names == ["field", "FIELD_", "field__"], field_names

    wrapper = work / "check-case-insensitive-record-fields.bas"
    wrapper.write_text(
        f'#include once "{output.name}"\n'
        "Dim As c2fb_c2fb_case_field_names value\n"
        "value.field = 1\n"
        "value.FIELD_ = 2\n"
        "value.field__ = 3\n"
        "If value.field <> 1 OrElse value.FIELD_ <> 2 OrElse _\n"
        "   value.field__ <> 3 Then End 1\n"
    )
    executable = work / "check-case-insensitive-record-fields"
    run(fbc + ["-w", "all", "-i", str(work), str(wrapper), "-x", str(executable)],
        cwd=work)
    run([str(executable)], cwd=work)


def check_generic_header_large_record_field_names(converter, work):
    # A record larger than the initial hash capacity must retain every field.
    field_count = 6600
    header = work / "large-record-field-index.h"
    output = work / "large-record-field-index.bi"
    header.write_text(
        "struct C2fbLargeRecordFieldIndex {\n" + "".join(
            f"    int field{index:05d};\n" for index in range(field_count)
        ) + "};\n"
    )
    summary = run([converter, "generic-header", str(header), str(output), "cc"])
    assert "emitted 1 record layouts" in summary and "skipped 0" in summary, summary
    generated = output.read_text()
    assert "field00000 As Long" in generated, "first large-record field was lost"
    assert f"field{field_count - 1:05d} As Long" in generated, "last large-record field was lost"


def check_generic_header_declaration_limit(converter, fbc, work):
    # Large SDK headers use the declaration bound independently of body workspaces.
    source_directory = work / "generic-header-declaration-limit"
    source_directory.mkdir()
    header = source_directory / "declarations.h"
    for declaration_count in (32768, 32769):
        header.write_text("".join(
            f"extern int c2fbLimit{index:05d};\n"
            for index in range(declaration_count)
        ))
        output = source_directory / f"declarations-{declaration_count}.bi"
        result = subprocess.run(
            [converter, "generic-header", str(header), str(output), "cc"],
            capture_output=True, text=True,
        )
        diagnostics = result.stdout + result.stderr
        if declaration_count == 32768:
            assert result.returncode == 0, diagnostics
            assert f"converted 0 function declarations and {declaration_count} external objects" in diagnostics, diagnostics
            generated = output.read_text()
            assert 'Alias "c2fbLimit00000"' in generated, generated
            assert 'Alias "c2fbLimit32767"' in generated, generated
            wrapper = source_directory / "check-object-bindings.bas"
            wrapper.write_text(
                f'#include once "{output.resolve()}"\n'
                "Sub checkObjects()\n"
                "    Dim firstValue As Long = c2fb_c2fbLimit00000\n"
                "    Dim lastValue As Long = c2fb_c2fbLimit32767\n"
                "End Sub\n"
            )
            run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
                       str(source_directory / "check-object-bindings.o")],
                cwd=source_directory)
        else:
            assert result.returncode != 0, diagnostics
            assert "translation unit exceeds the configured declaration limit" in diagnostics, diagnostics

    typedef_count = 32768
    typedef_header = source_directory / "typedefs.h"
    typedef_header.write_text("".join(
        f"typedef int c2fbLimitType{index:05d};\n"
        for index in range(typedef_count)
    ))
    typedef_output = source_directory / "typedefs.bi"
    typedef_result = subprocess.run(
        [converter, "generic-header", str(typedef_header), str(typedef_output), "cc"],
        capture_output=True, text=True,
    )
    typedef_diagnostics = typedef_result.stdout + typedef_result.stderr
    assert typedef_result.returncode == 0, typedef_diagnostics
    generated_typedefs = typedef_output.read_text()
    assert "Type c2fb_c2fbLimitType00000 As Long" in generated_typedefs, generated_typedefs
    assert f"Type c2fb_c2fbLimitType{typedef_count - 1:05d} As Long" in generated_typedefs, generated_typedefs
    typedef_wrapper = source_directory / "check-typedef-bindings.bas"
    typedef_wrapper.write_text(
        f'#include once "{typedef_output.resolve()}"\n'
        "Sub checkTypes()\n"
        "    Dim firstValue As c2fb_c2fbLimitType00000\n"
        f"    Dim lastValue As c2fb_c2fbLimitType{typedef_count - 1:05d}\n"
        "End Sub\n"
    )
    run(fbc + ["-w", "all", "-c", str(typedef_wrapper), "-o",
               str(source_directory / "check-typedef-bindings.o")],
        cwd=source_directory)


def check_generic_header_jmp_buf_compatibility(converter, fbc, work):
    source_directory = work / "generic-header-jmp-buf"
    source_directory.mkdir()
    header = source_directory / "jmp-buf.h"
    header.write_text(
        "extern jmp_buf c2fbJmpBufObject;\n"
        "static const jmp_buf c2fbStaticConstJmpBuf;\n"
        "extern const jmp_buf c2fbExternalConstJmpBuf;\n"
        "typedef struct c2fbConstRecord { int value; } c2fbConstRecord;\n"
        "static const c2fbConstRecord c2fbStaticConstRecord = { 17 };\n"
        "void c2fbJmpBufValue(jmp_buf);\n"
        "void c2fbConstJmpBufValue(const jmp_buf);\n"
        "void c2fbJmpBufPointer(jmp_buf *);\n"
        "void c2fbConstJmpBufPointer(const jmp_buf *);\n"
    )
    binding = source_directory / "jmp-buf.bi"
    run([converter, "generic-header", str(header), str(binding), "cc",
         "--include-static-objects", "--private-static-objects"])
    generated = binding.read_text()
    assert '#include once "crt/setjmp.bi"' in generated, generated
    assert 'As jmp_buf Ptr' in generated, generated
    assert 'As Const jmp_buf Ptr' in generated, generated
    assert "Private Dim Shared c2fb_c2fbStaticConstJmpBuf_storage As jmp_buf" in generated, generated
    assert 'Extern c2fb_c2fbExternalConstJmpBuf_storage Alias "c2fbExternalConstJmpBuf" As jmp_buf' in generated, generated
    assert "Private Dim Shared c2fb_c2fbStaticConstRecord_storage As c2fb_c2fbConstRecord" in generated, generated
    assert "c2fbStaticConstRecord_storage As c2fb_c2fbConstRecord =" in generated, generated
    assert 'Cptr(Const jmp_buf Ptr, @c2fb_c2fbStaticConstJmpBuf_storage)' in generated, generated
    assert 'Cptr(Const c2fb_c2fbConstRecord Ptr, @c2fb_c2fbStaticConstRecord_storage)' in generated, generated
    wrapper = source_directory / "check-jmp-buf.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        "Sub checkConstStorage()\n"
        "    Dim staticJumpSize As Long = SizeOf(c2fb_c2fbStaticConstJmpBuf)\n"
        "    Dim externalJumpSize As Long = SizeOf(c2fb_c2fbExternalConstJmpBuf)\n"
        "    Dim staticRecordSize As Long = SizeOf(c2fb_c2fbStaticConstRecord)\n"
        "    Dim recordValue As Long = c2fb_c2fbStaticConstRecord.value\n"
        "End Sub\n"
    )
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "check-jmp-buf.o")],
        cwd=source_directory)
    write_wrapper = source_directory / "write-const-jmp-buf.bas"
    write_wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        "Sub writeConstStorage()\n"
        "    c2fb_c2fbStaticConstRecord.value = 0\n"
        "End Sub\n"
    )
    write_result = subprocess.run(
        fbc + ["-w", "all", "-c", str(write_wrapper), "-o",
               str(source_directory / "write-const-jmp-buf.o")],
        cwd=source_directory, capture_output=True, text=True)
    assert write_result.returncode != 0, (
        "Const aggregate storage became writable through its generated accessor"
    )

    array_header = source_directory / "array-jmp-buf.h"
    array_header.write_text(
        "typedef int jmp_buf[2];\n"
        "void c2fbArrayJmpBufValue(jmp_buf);\n"
    )
    array_binding = source_directory / "array-jmp-buf.bi"
    run([converter, "generic-header", str(array_header),
         str(array_binding), "cc"])
    array_generated = array_binding.read_text()
    assert '"crt/setjmp.bi"' not in array_generated, array_generated
    assert "As Long Ptr" in array_generated, array_generated
    array_wrapper = source_directory / "check-array-jmp-buf.bas"
    array_wrapper.write_text(f'#include once "{array_binding.resolve()}"\n')
    run(fbc + ["-w", "all", "-c", str(array_wrapper), "-o",
               str(source_directory / "check-array-jmp-buf.o")],
        cwd=source_directory)


def check_generic_header_macro_capacity(converter, fbc, work):
    # Expanded SDK headers can carry macro tables as large as the declaration bound.
    source_directory = work / "generic-header-macro-capacity"
    source_directory.mkdir()
    macro_count = 32768
    header = source_directory / "bulk-macros.h"
    header.write_text("".join(
        f"#define C2FB_BULK_{index:05d} {index}\n"
        for index in range(macro_count)
    ))
    binding = source_directory / "bulk-macros.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    emitted_names = re.findall(
        r"^Const (c2fb_C2FB_BULK_[A-Za-z0-9_]+) = ", generated, re.M)
    assert len(emitted_names) == macro_count, (
        f"Expected {macro_count} macro constants, found {len(emitted_names)}"
    )
    assert "c2fb_C2FB_BULK_00000" in emitted_names
    assert f"c2fb_C2FB_BULK_{macro_count - 1:05d}" in emitted_names

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        "If c2fb_C2FB_BULK_00000 <> 0 Then End 1\n"
        f"If c2fb_C2FB_BULK_{macro_count - 1:05d} <> "
        f"{macro_count - 1} Then End 2\n"
    )
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        executable = source_directory / f"check-{backend}"
        run(fbc + flags + ["-w", "all", str(wrapper), "-x", str(executable)],
            cwd=source_directory)
        run([str(executable)], cwd=source_directory)


def check_generic_header_fbfrog_verbosity(converter, work):
    # FBFrog verbosity reports conversion stages without changing the binding.
    source_directory = work / "generic-header-fbfrog-verbosity"
    source_directory.mkdir()
    header = source_directory / "verbose.h"
    header.write_text("extern int c2fbVerboseObject;\n")
    binding = source_directory / "verbose.bi"

    normal_output = run([
        converter, "generic-header", str(header), str(binding), "cc",
    ])
    generated = binding.read_text()
    assert "generic-header input:" not in normal_output, normal_output

    single_verbose_output = run([
        converter, "generic-header", str(header), str(binding), "-v", "cc",
    ])
    assert "c2fb: generic-header input: " in single_verbose_output
    assert "c2fb: generic-header output: " in single_verbose_output
    assert "c2fb: preprocessor: cc" in single_verbose_output
    assert "preprocessor options:" not in single_verbose_output
    assert binding.read_text() == generated

    double_verbose_output = run([
        converter, "generic-header", str(header), str(binding), "-v", "-v", "cc",
    ])
    assert "c2fb: preprocessor options: " in double_verbose_output
    assert "C declaration preprocessing completed" in double_verbose_output
    assert "C macro preprocessing completed" in double_verbose_output
    collection_count = re.search(
        r"collected 1 declaration slots and (\d+) macro definitions",
        double_verbose_output,
    )
    assert collection_count is not None, double_verbose_output
    assert int(collection_count.group(1)) > 0, double_verbose_output
    assert binding.read_text() == generated


def check_generic_header_float_and_string_macro_values(converter, fbc, cc, work):
    source_directory = work / "generic-header-noninteger-macro-values"
    source_directory.mkdir()
    header = source_directory / "values.h"
    header.write_text(
        "#define FLOAT_SINGLE 0.1f\n"
        "#define FLOAT_DOUBLE 0.1\n"
        "#define FLOAT_EXPONENT 1.25e-3\n"
        '#define STRING_PLAIN "freebasic"\n'
        '#define STRING_ESCAPED "a\\nb\\t\\xFF"\n'
        '#define STRING_CONCAT "c2fb-" "macro"\n'
    )
    binding = source_directory / "values.bi"
    run([converter, "generic-header", str(header), str(binding), "cc",
         "--prefix=c2fb_"])

    c_source = source_directory / "c-values.c"
    c_source.write_text(
        '#include "values.h"\n'
        "#include <stdint.h>\n"
        "#include <stdio.h>\n"
        "#include <string.h>\n"
        "static void printSingle(const char *name, float value) {\n"
        "    uint32_t bits;\n"
        "    memcpy(&bits, &value, sizeof(bits));\n"
        '    printf("%s %08X\\n", name, (unsigned int)bits);\n'
        "}\n"
        "static void printDouble(const char *name, double value) {\n"
        "    uint64_t bits;\n"
        "    memcpy(&bits, &value, sizeof(bits));\n"
        '    printf("%s %016llX\\n", name, (unsigned long long)bits);\n'
        "}\n"
        "static void printString(const char *name, const unsigned char *value) {\n"
        "    size_t length = strlen((const char *)value);\n"
        '    printf("%s %zu", name, length);\n'
        "    for (size_t index = 0; index <= length; ++index) {\n"
        '        printf(" %02X", (unsigned int)value[index]);\n'
        "    }\n"
        '    putchar(\'\\n\');\n'
        "}\n"
        "int main(void) {\n"
        '    printSingle("FLOAT_SINGLE", FLOAT_SINGLE);\n'
        '    printDouble("FLOAT_DOUBLE", FLOAT_DOUBLE);\n'
        '    printDouble("FLOAT_EXPONENT", FLOAT_EXPONENT);\n'
        '    printString("STRING_PLAIN", (const unsigned char *)STRING_PLAIN);\n'
        '    printString("STRING_ESCAPED", (const unsigned char *)STRING_ESCAPED);\n'
        '    printString("STRING_CONCAT", (const unsigned char *)STRING_CONCAT);\n'
        "    return 0;\n"
        "}\n"
    )
    c_executable = source_directory / "c-values"
    run(cc + ["-std=c99", str(c_source), "-I", str(source_directory),
              "-o", str(c_executable)], cwd=source_directory)
    expected = run([str(c_executable)], cwd=source_directory)

    fb_source = source_directory / "fb-values.bas"
    fb_lines = [
        f'#include once "{binding.resolve()}"',
        "Dim singleValue As Single = c2fb_FLOAT_SINGLE",
        "Dim singleBits As ULong = *CPtr(ULong Ptr, @singleValue)",
        'Print "FLOAT_SINGLE "; Hex(singleBits, 8)',
    ]
    for name in ("FLOAT_DOUBLE", "FLOAT_EXPONENT"):
        fb_lines.extend([
            f"Dim {name}Value As Double = c2fb_{name}",
            f"Dim {name}Bits As ULongInt = *CPtr(ULongInt Ptr, @{name}Value)",
            f'Print "{name} "; Hex({name}Bits, 16)',
        ])
    for name in ("STRING_PLAIN", "STRING_ESCAPED", "STRING_CONCAT"):
        fb_lines.extend([
            f"Dim {name}String As ZString Ptr = CPtr(ZString Ptr, c2fb_{name})",
            f"Dim {name}Bytes As UByte Ptr = CPtr(UByte Ptr, {name}String)",
            f"Dim {name}Length As Long = Len(*{name}String)",
            f'Print "{name} " & LTrim(Str({name}Length));',
            f"For byteIndex As Long = 0 To {name}Length",
            f'    Print " "; Hex({name}Bytes[byteIndex], 2);',
            "Next",
            "Print",
        ])
    fb_source.write_text("\n".join(fb_lines) + "\n")
    for backend, options in (("native", []), ("gcc", ["-gen", "gcc"])):
        fb_executable = source_directory / f"fb-values-{backend}"
        run(fbc + options + ["-w", "all", str(fb_source), "-x",
                             str(fb_executable)], cwd=source_directory)
        actual = run([str(fb_executable)], cwd=source_directory)
        assert actual == expected, (
            f"{backend} floating or string macros differ from C:\n"
            f"C:\n{expected}FreeBASIC:\n{actual}"
        )


def check_fbfrog_macro_value_audit(converter, fbc, work):
    source_directory = work / "fbfrog-literal-macro-value-audit"
    tests_directory = source_directory / "tests" / "values"
    tests_directory.mkdir(parents=True)
    header = tests_directory / "values.h"
    baseline = tests_directory / "values.bi"
    header.write_text(
        "// @fbfrog -clong32 -renamedefine C2FB_AUDIT_RENAMED C2FB_AUDIT_TARGET\n"
        "#define C2FB_AUDIT_DECIMAL 17\n"
        "#define C2FB_AUDIT_HEX (0x2a)\n"
        "#define C2FB_AUDIT_OCTAL 07u\n"
        "#define C2FB_AUDIT_NEGATIVE (-3)\n"
        "#define C2FB_AUDIT_RENAMED 9\n"
        "#define C2FB_AUDIT_ALIAS C2FB_AUDIT_DECIMAL\n"
        "#define C2FB_AUDIT_ADD(a, b) ((a) + (b))\n"
        "#define C2FB_AUDIT_SCALE(a) ((a) * 2)\n"
        "#define C2FB_AUDIT_FLOAT_SINGLE 0.1f\n"
        "#define C2FB_AUDIT_FLOAT_DOUBLE 1.25e-3\n"
        '#define C2FB_AUDIT_STRING "c2fb-" "macro"\n'
    )
    baseline.write_text(
        "const C2FB_AUDIT_DECIMAL = 17\n"
        "const C2FB_AUDIT_HEX = &h2a\n"
        "const C2FB_AUDIT_OCTAL = &o7u\n"
        "const C2FB_AUDIT_NEGATIVE = -3\n"
        "const C2FB_AUDIT_TARGET = 9\n"
        "const C2FB_AUDIT_ALIAS = C2FB_AUDIT_DECIMAL\n"
        "#define C2FB_AUDIT_ADD(a, b) ((a) + (b))\n"
        "#define C2FB_AUDIT_SCALE(a) ((a) * 2)\n"
        "const C2FB_AUDIT_FLOAT_SINGLE = 0.1\n"
        "const C2FB_AUDIT_FLOAT_DOUBLE = 1.25e-3\n"
        '#define C2FB_AUDIT_STRING "c2fb-macro"\n'
    )
    macro_include_directory = source_directory / "tests" / "cpp" / "include"
    macro_include_directory.mkdir(parents=True)
    (macro_include_directory / "filename-from-macro.h").write_text(
        '#define C2FB_AUDIT_HEADER_NAME "foo.h"\n'
        "#include C2FB_AUDIT_HEADER_NAME\n"
    )
    (macro_include_directory / "filename-from-macro.bi").write_text(
        '#include once "foo.bi"\n'
        '#define C2FB_AUDIT_HEADER_NAME "foo.h"\n'
    )
    (macro_include_directory / "foo.bi").write_text("' empty include fixture\n")
    target_directory = source_directory / "tests" / "targeted"
    target_directory.mkdir()
    (target_directory / "profile.h").write_text(
        "#if defined(_WIN32)\n"
        "#define C2FB_AUDIT_PROFILE_VALUE 21\n"
        "#elif defined(__LP64__)\n"
        "#define C2FB_AUDIT_PROFILE_VALUE 64\n"
        "#else\n"
        "#define C2FB_AUDIT_PROFILE_VALUE 11\n"
        "#endif\n"
    )
    (target_directory / "profile.bi").write_text(
        "#ifdef __FB_WIN32__\n"
        "const C2FB_AUDIT_PROFILE_VALUE = 21\n"
        "#else\n"
        "#ifdef __FB_64BIT__\n"
        "#ifdef __FB_UNIX__\n"
        "const C2FB_AUDIT_PROFILE_VALUE = 64\n"
        "#else\n"
        "const C2FB_AUDIT_PROFILE_VALUE = 11\n"
        "#endif\n"
        "#else\n"
        "const C2FB_AUDIT_PROFILE_VALUE = 11\n"
        "#endif\n"
        "#endif\n"
    )
    version_directory = source_directory / "tests" / "versioned"
    version_directory.mkdir()
    version_script = version_directory / "version.fbfrog"
    version_script.write_text(
        "-declareversions C2FB_AUDIT_VERSION 1 2\n"
        "-selectversion\n"
        "-case 1 -define C2FB_AUDIT_VERSION 1\n"
        "-case 2 -define C2FB_AUDIT_VERSION 2\n"
        "-endselect\n"
    )
    (version_directory / "version.h").write_text(
        f"// @fbfrog {version_script.resolve()}\n"
        "#if C2FB_AUDIT_VERSION == 1\n"
        "#define C2FB_AUDIT_VERSION_ONE\n"
        "#else\n"
        "#define C2FB_AUDIT_VERSION_TWO\n"
        "#endif\n"
        "#define C2FB_AUDIT_VERSION_SHARED\n"
    )
    version_baseline = version_directory / "version.bi"
    version_baseline.write_text(
        "#if C2FB_AUDIT_VERSION = 1\n"
        "#define C2FB_AUDIT_VERSION_ONE\n"
        "#else\n"
        "#define C2FB_AUDIT_VERSION_TWO\n"
        "#endif\n"
        "#define C2FB_AUDIT_VERSION_SHARED\n"
    )
    scripted_directory = source_directory / "tests" / "scripted"
    scripted_directory.mkdir()
    selector_script = scripted_directory / "unicode.fbfrog"
    selector_script.write_text(
        "-declarebool UNICODE\n"
        "-ifdef UNICODE\n"
        "    -define UNICODE 1\n"
        "-endif\n"
    )
    (scripted_directory / "unicode.h").write_text(
        f"// @fbfrog {selector_script.resolve()}\n"
        "#define C2FB_SCRIPT_VALUE_ONE 17\n"
        "#define C2FB_SCRIPT_VALUE_TWO 29\n"
        "#define C2FB_SCRIPT_VALUE_SHARED 31\n"
        "#ifdef UNICODE\n"
        "#define C2FB_SCRIPT_UNICODE_ON\n"
        "#else\n"
        "#define C2FB_SCRIPT_UNICODE_OFF\n"
        "#endif\n"
        "#define C2FB_SCRIPT_UNICODE_SHARED\n"
    )
    (scripted_directory / "unicode.bi").write_text(
        "const C2FB_SCRIPT_VALUE_ONE = 17\n"
        "const C2FB_SCRIPT_VALUE_TWO = 29\n"
        "const C2FB_SCRIPT_VALUE_SHARED = 31\n"
        "#ifdef UNICODE\n"
        "#define C2FB_SCRIPT_UNICODE_ON\n"
        "#else\n"
        "#define C2FB_SCRIPT_UNICODE_OFF\n"
        "#endif\n"
        "#define C2FB_SCRIPT_UNICODE_SHARED\n"
    )
    audit_script = Path(__file__).resolve().parents[1] / "audit_fbfrog.py"

    def run_value_audit():
        return subprocess.run([
            sys.executable, str(audit_script),
            "--converter", converter,
            "--fbfrog-tests", str(source_directory / "tests"),
            "--fbc", shlex.join(fbc),
            "--scope", "macros",
            "--compile-bindings",
            "--compare-macro-values",
            "--strict",
        ], capture_output=True, text=True)

    result = run_value_audit()
    assert result.returncode == 0, result.stdout + result.stderr
    macro_value_summary = re.search(
        r"matching evaluated integer macro values: (\d+) across "
        r"(\d+) fixture/profile probes", result.stdout)
    assert macro_value_summary is not None, result.stdout
    assert int(macro_value_summary.group(1)) >= 31, result.stdout
    assert int(macro_value_summary.group(2)) >= 10, result.stdout
    assert "matching evaluated noninteger macro values: 4 across 2 " \
        "fixture/profile probes" in result.stdout, result.stdout
    assert "noninteger macro value mismatches: 0" in result.stdout, result.stdout
    assert "C2FB/source noninteger macro value mismatches: 0" \
        in result.stdout, result.stdout
    assert "fbfrog/source noninteger macro value divergences: 0" \
        in result.stdout, result.stdout
    assert "C source noninteger macro values checked: 4 across 2 " \
        "fixture/profile probes" in result.stdout, result.stdout
    assert "C source noninteger macro probes skipped: 0" \
        in result.stdout, result.stdout
    assert "fbfrog script-matrix fixtures audited: 1" in result.stdout, result.stdout
    assert "macro value mismatches: 0" in result.stdout, result.stdout
    presence_summary = re.search(
        r"matching empty-macro presence cases: (\d+) across "
        r"(\d+) fixture/profile probes", result.stdout)
    assert presence_summary is not None, result.stdout
    assert int(presence_summary.group(1)) >= 4, result.stdout
    assert int(presence_summary.group(2)) >= 2, result.stdout

    baseline.write_text(baseline.read_text().replace(
        '#define C2FB_AUDIT_STRING "c2fb-macro"',
        '#define C2FB_AUDIT_STRING "fbfrog-only"',
    ))
    result = run_value_audit()
    assert result.returncode == 0, result.stdout + result.stderr
    assert "noninteger macro value mismatches: 1" in result.stdout, result.stdout
    assert "noninteger macro value mismatch values/values.h " \
        "(C2FB_AUDIT_STRING): fbfrog=string:11:666266726F672D6F6E6C7900, " \
        "C2FB=string:10:633266622D6D6163726F00" in result.stdout, result.stdout
    assert "C2FB/source noninteger macro value mismatches: 0" \
        in result.stdout, result.stdout
    assert "fbfrog/source noninteger macro value divergences: 1" \
        in result.stdout, result.stdout

    baseline.write_text(baseline.read_text().replace(
        '#define C2FB_AUDIT_STRING "fbfrog-only"',
        '#define C2FB_AUDIT_STRING "c2fb-macro"',
    ))

    baseline.write_text(baseline.read_text().replace(
        "const C2FB_AUDIT_DECIMAL = 17",
        "const C2FB_AUDIT_DECIMAL = 18",
    ))
    result = run_value_audit()
    assert result.returncode == 0, result.stdout + result.stderr
    assert "macro value mismatches: 2" in result.stdout, result.stdout
    assert "macro value mismatch values/values.h (C2FB_AUDIT_DECIMAL): " \
        "fbfrog=18, C2FB=17" in result.stdout, result.stdout
    assert "macro value mismatch values/values.h (C2FB_AUDIT_ALIAS): " \
        "fbfrog=18, C2FB=17" in result.stdout, result.stdout
    assert "C2FB/source macro value mismatches: 0" in result.stdout, result.stdout
    assert "fbfrog/source macro value divergences: 2" in result.stdout, result.stdout

    baseline.write_text(baseline.read_text().replace(
        "const C2FB_AUDIT_DECIMAL = 18",
        "const C2FB_AUDIT_DECIMAL = 17",
    ))
    version_baseline.write_text(
        "#if C2FB_AUDIT_VERSION = 1\n"
        "#define C2FB_AUDIT_VERSION_TWO\n"
        "#else\n"
        "#define C2FB_AUDIT_VERSION_ONE\n"
        "#endif\n"
        "#define C2FB_AUDIT_VERSION_SHARED\n"
    )
    result = run_value_audit()
    assert result.returncode == 1, result.stdout + result.stderr
    assert "macro presence mismatches: 2" in result.stdout, result.stdout
    assert "macro presence mismatch versioned/version.h " \
        "(C2FB_AUDIT_VERSION_ONE [version-1]): fbfrog=0, C2FB=1" \
        in result.stdout, result.stdout

    missing_baseline_directory = source_directory / "fbfrog-missing-value-baseline"
    missing_baseline_directory.mkdir()
    (missing_baseline_directory / "only.h").write_text(
        '#define C2FB_AUDIT_REFERENCE "text"\n'
        "#define C2FB_AUDIT_C2FB_ONLY 41\n"
    )
    (missing_baseline_directory / "only.bi").write_text(
        "#pragma once\n"
        '#define C2FB_AUDIT_REFERENCE "text"\n'
    )
    result = subprocess.run([
        sys.executable, str(audit_script),
        "--converter", converter,
        "--fbfrog-tests", str(missing_baseline_directory),
        "--fbc", shlex.join(fbc),
        "--scope", "macros",
        "--compile-bindings",
        "--compare-macro-values",
    ], capture_output=True, text=True)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "macro value probe fixtures skipped: 1" in result.stdout, result.stdout
    assert "macro value probe skipped only.h: " \
        "FBFrog baseline has no matching macro binding" in result.stdout, result.stdout


def check_fbfrog_macro_source_oracle(converter, fbc, cc, work):
    source_directory = work / "fbfrog-macro-source-oracle"
    tests_directory = source_directory / "tests" / "push-pop"
    tests_directory.mkdir(parents=True)
    header = tests_directory / "push-pop.h"
    baseline = tests_directory / "push-pop.bi"
    header.write_text(
        "#define C2FB_AUDIT_PUSH_POP 1\n"
        '_Pragma("push_macro(\\"C2FB_AUDIT_PUSH_POP\\")")\n'
        "#undef C2FB_AUDIT_PUSH_POP\n"
        "#define C2FB_AUDIT_PUSH_POP 2\n"
        '_Pragma("pop_macro(\\"C2FB_AUDIT_PUSH_POP\\")")\n'
    )
    audit_script = Path(__file__).resolve().parents[1] / "audit_fbfrog.py"

    def run_value_audit(strict):
        command = [
            sys.executable, str(audit_script),
            "--converter", converter,
            "--fbfrog-tests", str(source_directory / "tests"),
            "--fbc", shlex.join(fbc),
            "--cc", shlex.join(cc),
            "--scope", "macros",
            "--compile-bindings",
            "--compare-macro-values",
        ]
        if strict:
            command.append("--strict")
        return subprocess.run(command, capture_output=True, text=True)

    baseline.write_text("#define C2FB_AUDIT_PUSH_POP 2\n")
    result = run_value_audit(strict=False)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "macro value mismatch push-pop/push-pop.h " \
        "(C2FB_AUDIT_PUSH_POP): fbfrog=2, C2FB=1" in result.stdout, result.stdout
    assert "C2FB/source macro value mismatches: 0" in result.stdout, result.stdout
    assert "fbfrog/source macro value divergences: 1" in result.stdout, result.stdout

    baseline.write_text("#define C2FB_AUDIT_PUSH_POP 1\n")
    result = run_value_audit(strict=True)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "macro value mismatches: 0" in result.stdout, result.stdout
    assert "C2FB/source macro value mismatches: 0" in result.stdout, result.stdout


def check_fbfrog_record_layout_audit(converter, fbc, cc, work):
    # The audit must distinguish a C2FB ABI error from an incorrect fbfrog layout.
    source_directory = work / "fbfrog-record-layout-audit"
    tests_directory = source_directory / "tests"
    tests_directory.mkdir(parents=True)
    (tests_directory / "layout.h").write_text(
        "typedef struct LayoutProbe { char first; int value; } LayoutProbe;\n"
    )
    baseline = tests_directory / "layout.bi"
    baseline.write_text(
        "#pragma once\n"
        "type LayoutProbe field = 1\n"
        "    first as byte\n"
        "    value as long\n"
        "end type\n"
    )
    audit_script = Path(__file__).resolve().parents[1] / "audit_fbfrog.py"

    def run_layout_audit(strict, fixture_root=tests_directory):
        command = [
            sys.executable, str(audit_script),
            "--converter", converter,
            "--fbfrog-tests", str(fixture_root),
            "--cc", shlex.join(cc),
            "--fbc", shlex.join(fbc),
            "--scope", "declarations",
            "--compile-bindings",
            "--compare-record-layouts",
        ]
        if strict:
            command.append("--strict")
        return subprocess.run(command, capture_output=True, text=True)

    result = run_layout_audit(strict=False)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "C record layout values checked: 3 across 1 record/profile probes" \
        in result.stdout, result.stdout
    assert "C2FB/source record layout mismatches: 0" in result.stdout, result.stdout
    assert "fbfrog/source record layout divergences: 2" in result.stdout, result.stdout
    assert "fbfrog/source record layout divergence layout.h " \
        "(LayoutProbe.sizeof): fbfrog=5, C=8" in result.stdout, result.stdout

    baseline.write_text(
        "#pragma once\n"
        "type LayoutProbe\n"
        "    first as byte\n"
        "    value as long\n"
        "end type\n"
    )
    result = run_layout_audit(strict=True)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "C record layout values checked: 3 across 1 record/profile probes" \
        in result.stdout, result.stdout
    assert "C2FB/source record layout mismatches: 0" in result.stdout, result.stdout
    assert "fbfrog/source record layout divergences: 0" in result.stdout, result.stdout
    assert "record layout probes skipped: 0" in result.stdout, result.stdout

    local_scope_tests = source_directory / "local-scope-tests"
    local_scope_tests.mkdir()
    (local_scope_tests / "local-scope.h").write_text(
        "void localTypeOwner(void) {\n"
        "    struct LocalType { int value; };\n"
        "}\n"
    )
    (local_scope_tests / "local-scope.bi").write_text(
        "#pragma once\n"
        "private sub localTypeOwner()\n"
        "    type LocalType\n"
        "        value as long\n"
        "    end type\n"
        "end sub\n"
    )
    result = run_layout_audit(strict=True, fixture_root=local_scope_tests)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "C2FB layout probes skipped: 0" in result.stdout, result.stdout
    assert "record layout probes skipped: 0" in result.stdout, result.stdout

    conditional_tests = source_directory / "conditional-tests"
    conditional_tests.mkdir()
    (conditional_tests / "conditional.h").write_text(
        "#ifdef _WIN32\n"
        "struct WindowsOnlyProbe { int value; };\n"
        "#endif\n"
    )
    (conditional_tests / "conditional.bi").write_text(
        "#pragma once\n"
        "#ifdef __FB_WIN32__\n"
        "type WindowsOnlyProbe\n"
        "    value as long\n"
        "end type\n"
        "#endif\n"
    )
    result = run_layout_audit(strict=False, fixture_root=conditional_tests)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "C2FB layout probes skipped: 0" in result.stdout, result.stdout
    assert "FBFrog layout probes skipped: 2" in result.stdout, result.stdout
    assert "C2FB layout skips with FBC-compilable FBFrog baseline: 0" \
        in result.stdout, result.stdout
    assert "record layout probe skipped conditional.h " \
        "(WindowsOnlyProbe, conditional_h_" in result.stdout, result.stdout
    assert "FBFrog layout probe failed:" in result.stdout, result.stdout

    anonymous_tests = source_directory / "anonymous-use-tests"
    anonymous_tests.mkdir()
    (anonymous_tests / "anonymous.h").write_text(
        "struct { int value; } anonymousResult(void);\n"
    )
    (anonymous_tests / "anonymous.bi").write_text(
        "#pragma once\n"
        "type anonymousResult\n"
        "    value as long\n"
        "end type\n"
        "declare function anonymousResult() as anonymousResult\n"
    )
    result = run_layout_audit(strict=True, fixture_root=anonymous_tests)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "C record layout values checked: 2 across 1 record/profile probes" \
        in result.stdout, result.stdout
    assert "C2FB/source record layout mismatches: 0" in result.stdout, result.stdout
    assert "fbfrog/source record layout divergences: 0" in result.stdout, result.stdout
    assert "record layout probes skipped: 0" in result.stdout, result.stdout

    macro_alias_tests = source_directory / "macro-alias-tests"
    macro_alias_tests.mkdir()
    (macro_alias_tests / "macro-alias.h").write_text(
        "#define MacroAlias MacroTarget\n"
        "struct MacroTarget { int value; };\n"
    )
    (macro_alias_tests / "macro-alias.bi").write_text(
        "#pragma once\n"
        "type MacroAlias as MacroTarget\n"
        "type MacroTarget\n"
        "    value as long\n"
        "end type\n"
    )
    result = run_layout_audit(strict=True, fixture_root=macro_alias_tests)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "C record layout values checked: 4 across 2 record/profile probes" \
        in result.stdout, result.stdout
    assert "C2FB/source record layout mismatches: 0" in result.stdout, result.stdout
    assert "record layout probes skipped: 0" in result.stdout, result.stdout

    renamed_tests = source_directory / "renamed-tests"
    renamed_tests.mkdir()
    (renamed_tests / "renamed.h").write_text(
        "// @fbfrog -renametag Original Renamed\n"
        "struct Original { int value; };\n"
    )
    (renamed_tests / "renamed.bi").write_text(
        "#pragma once\n"
        "type Renamed\n"
        "    value as long\n"
        "end type\n"
    )
    result = run_layout_audit(strict=True, fixture_root=renamed_tests)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "C record layout values checked: 2 across 1 record/profile probes" \
        in result.stdout, result.stdout
    assert "C2FB/source record layout mismatches: 0" in result.stdout, result.stdout
    assert "record layout probes skipped: 0" in result.stdout, result.stdout

    nested_tests = source_directory / "nested-tests"
    nested_tests.mkdir()
    (nested_tests / "nested.h").write_text(
        "// @fbfrog -removeproc c2fbLayoutConflict\n"
        "union NestedProbe {\n"
        "    int first;\n"
        "    struct {\n"
        "        int nested;\n"
        "        union { int left; int right; };\n"
        "        int tail;\n"
        "    };\n"
        "    int last;\n"
        "    struct { union { struct { union { }; }; }; };\n"
        "};\n"
        "void c2fbLayoutConflict(int value);\n"
        "void c2fbLayoutConflict(char value);\n"
    )
    (nested_tests / "nested.bi").write_text(
        "#pragma once\n"
        "union NestedProbe\n"
        "    first as long\n"
        "    type\n"
        "        nested as long\n"
        "        union\n"
        "            left as long\n"
        "            right as long\n"
        "        end union\n"
        "        tail as long\n"
        "    end type\n"
        "    last as long\n"
        "    type\n"
        "        union\n"
        "            type\n"
        "                union\n"
        "                end union\n"
        "            end type\n"
        "        end union\n"
        "    end type\n"
        "end union\n"
    )
    result = run_layout_audit(strict=False, fixture_root=nested_tests)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "C record layout values checked: 3 across 1 record/profile probes" \
        in result.stdout, result.stdout
    assert "C2FB/source record layout mismatches: 0" in result.stdout, result.stdout
    assert "record layout probes skipped: 1" in result.stdout, result.stdout
    assert "FBFrog layout probes skipped: 1" in result.stdout, result.stdout
    assert "C2FB layout probes skipped: 0" in result.stdout, result.stdout
    assert "record layout probe skipped nested.h " \
        "(NestedProbe, nested_h_direct): " \
        "FBFrog layout probe failed:" in result.stdout, result.stdout

    unsupported_tests = source_directory / "unsupported-tests"
    unsupported_tests.mkdir()
    (unsupported_tests / "unsupported.h").write_text(
        "struct UnsupportedProbe { int value; } "
        "__attribute__((aligned(16)));\n"
    )
    (unsupported_tests / "unsupported.bi").write_text(
        "#pragma once\n"
        "type UnsupportedProbe\n"
        "    value as long\n"
        "end type\n"
    )
    result = run_layout_audit(strict=False, fixture_root=unsupported_tests)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "C2FB layout probes skipped: 1" in result.stdout, result.stdout
    assert "C2FB layout skips with FBC-compilable FBFrog baseline: 1" \
        in result.stdout, result.stdout
    assert "C2FB layout skips with FBFrog profile-probe failure: 0" \
        in result.stdout, result.stdout
    assert "C2FB layout skips with usable FBFrog profile baseline: 1" \
        in result.stdout, result.stdout
    assert "C2FB layout skips with non-compilable FBFrog baseline: 0" \
        in result.stdout, result.stdout
    assert "C2FB layout skip with compilable FBFrog baseline unsupported.h " \
        "(UnsupportedProbe, unsupported_h_direct): " \
        "C2FB output has no matching record type" in result.stdout, result.stdout
    assert "record layout skip category C2FB output has no usable record layout: 1" \
        in result.stdout, result.stdout
    assert "record layout probe skipped unsupported.h " \
        "(UnsupportedProbe, unsupported_h_direct): " \
        "C2FB output has no matching record type" in result.stdout, result.stdout

    packed_tests = source_directory / "packed-tests"
    packed_tests.mkdir()
    (packed_tests / "packed.h").write_text(
        "// @fbfrog -removeproc c2fbPackedLayoutConflict\n"
        "void c2fbPackedLayoutConflict(void);\n"
        "void c2fbPackedLayoutConflict(int value);\n"
        "struct PackedProbe { short a; int b; } __attribute__((packed));\n"
    )
    (packed_tests / "packed.bi").write_text(
        "#pragma once\n"
        "type PackedProbe field = 1\n"
        "    a as short\n"
        "    b as long\n"
        "end type\n"
    )
    result = run_layout_audit(strict=True, fixture_root=packed_tests)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "C record layout values checked: 3 across 1 record/profile probes" \
        in result.stdout, result.stdout
    assert "C2FB/source record layout mismatches: 0" in result.stdout, result.stdout
    assert "fbfrog/source record layout divergences: 0" in result.stdout, result.stdout
    assert "record layout probes skipped: 0" in result.stdout, result.stdout


def check_body_candidate_limit(converter, work):
    # Body workspace remains capped below the larger source declaration bound.
    source_directory = work / "body-candidate-limit"
    source_directory.mkdir()
    body_catalog = source_directory / "minimal-body-catalog"
    body_catalog.mkdir()
    for name in (
        "sqlite3_types.bi", "sqlite3_constants.bi", "sqlite3_db_types.bi",
        "sqlite3_api_declarations.bi", "sqlite3_internal_api_declarations.bi",
        "sqlite3_parser_types.bi", "sqlite3_expr_types.bi",
        "sqlite3_vdbe_mem_types.bi", "sqlite3_vdbe_core.bi",
        "sqlite3_hash_types.bi", "sqlite3_pager.bi", "sqlite3_btree.bi",
    ):
        (body_catalog / name).write_text("")
    source = source_directory / "functions.c"
    for function_count in (8192, 8193):
        source.write_text("".join(
            f"int c2fbBoundary{index:05d}(int value) {{ return value; }}\n"
            for index in range(function_count)
        ))
        output = source_directory / f"functions-{function_count}.bas"
        result = subprocess.run(
            [converter, "translate-simple", str(source), str(output),
             str(body_catalog)],
            capture_output=True, text=True,
        )
        diagnostics = result.stdout + result.stderr
        if function_count == 8192:
            assert result.returncode == 0, diagnostics
            actual = procedure_names(output.read_text())
            expected = {f"c2fbBoundary{index:05d}" for index in range(function_count)}
            assert actual == expected, (
                f"Candidate bound lost functions: {expected - actual}; "
                f"unexpected: {actual - expected}"
            )
        else:
            assert result.returncode != 0, diagnostics
            assert "source file exceeds the configured function limit" in diagnostics, diagnostics


def check_compile_commands_workflow(converter, fbc, cc, work):
    # Translation units keep their own compiler flags and publish as one batch.
    project = work / "compile database project"
    source_a = project / "src/a/value.c"
    source_b = project / "src/b/value.c"
    include_directory = project / "include"
    build_directory = project / "build"
    fb_source_directory = project / "existing FreeBASIC bindings"
    source_a.parent.mkdir(parents=True)
    source_b.parent.mkdir(parents=True)
    include_directory.mkdir(parents=True)
    build_directory.mkdir(parents=True)
    fb_source_directory.mkdir(parents=True)
    (include_directory / "config.h").write_text(
        "#ifndef UNIT_VALUE\n#define UNIT_VALUE 0\n#endif\n"
    )
    source_a.write_text(
        '#include "config.h"\n'
        "typedef struct UnitState { int value; } UnitState;\n"
        "static int private_bias = 10;\n"
        "int c2fbReadUnitA(UnitState *state) {\n"
        "    return state->value + private_bias + UNIT_VALUE;\n"
        "}\n"
    )
    source_b.write_text(
        '#include "config.h"\n'
        "typedef struct UnitState { int value; int adjustment; } UnitState;\n"
        "static int private_bias = 20;\n"
        "int c2fbReadUnitB(UnitState *state) {\n"
        "    return state->value + state->adjustment + private_bias + UNIT_VALUE;\n"
        "}\n"
    )
    ignored_cpp = project / "src/ignored.cpp"
    ignored_cpp.write_text("int ignoredCpp() { return 0; }\n")

    directory = str(project.resolve())
    command_a = [
        *cc, "-std=c99", "-I", "include", "-DUNIT_VALUE=11", "-c",
        "src/a/value.c", "-o", "build/a object.o",
    ]
    command_b = [
        *cc, "-std=c99", "-I", "include", "-DUNIT_VALUE=22", "-c",
        "src/b/value.c", "-o", "build/b object.o",
    ]
    database = build_directory / "compile_commands.json"
    database.write_text(json.dumps([
        {"directory": directory, "file": "src/a/value.c", "arguments": command_a},
        {"directory": directory, "file": "src/a/value.c", "arguments": command_a},
        {"directory": directory, "file": "src/b/value.c", "command": shlex.join(command_b)},
        {
            "directory": directory,
            "file": "src/ignored.cpp",
            "command": shlex.join(["c++", "-c", "src/ignored.cpp", "-o", "ignored.o"]),
        },
    ]))
    output_directory = project / "candidate output"
    tool = Path(__file__).resolve().parents[1] / "c2fb_compile_commands.py"
    converter_path = str(Path(converter).resolve())
    command = [
        sys.executable, str(tool), str(database), str(output_directory),
        "--converter", converter_path, "--source-unit-context",
        "--header-option=--remove-empty-reserved-defines",
        "--c2fb-option=--fb-source-directory=" + str(fb_source_directory),
    ]
    summary = run(command)
    assert "published 2 candidates" in summary, summary
    assert "skipped 1 non-C entries" in summary, summary

    map_path = output_directory / "compile-command-map.csv"
    with map_path.open(encoding="utf-8", newline="") as map_file:
        rows = list(csv.DictReader(map_file))
    assert len(rows) == 2, rows
    assert all(row["SourceUnitContext"] == "1" for row in rows), rows
    assert all(
        json.loads(row["HeaderOptions"]) == ["--remove-empty-reserved-defines"]
        for row in rows
    ), rows
    rows_by_source = {
        Path(row["SourceFile"]).relative_to(project).as_posix(): row
        for row in rows
    }
    candidate_by_source = {
        source_name: output_directory / row["CandidateFile"]
        for source_name, row in rows_by_source.items()
    }
    candidate_a = candidate_by_source["src/a/value.c"]
    candidate_b = candidate_by_source["src/b/value.c"]
    type_context_a = output_directory / rows_by_source["src/a/value.c"]["TypeContextFile"]
    type_context_b = output_directory / rows_by_source["src/b/value.c"]["TypeContextFile"]
    assert type_context_a.is_file() and type_context_b.is_file()
    assert type_context_a != type_context_b
    assert "c2fbReadUnitA" in candidate_a.read_text()
    assert "c2fbReadUnitB" in candidate_b.read_text()
    assert "Type c2fb_UnitState" in type_context_a.read_text()
    assert "Type c2fb_UnitState" in type_context_b.read_text()
    assert "adjustment As Long" not in type_context_a.read_text()
    assert "adjustment As Long" in type_context_b.read_text()

    parallel_output_directory = project / "parallel candidate output"
    parallel_command = [
        sys.executable, str(tool), str(database),
        str(parallel_output_directory), "--converter", converter_path,
        "--source-unit-context", "--jobs=2",
        "--header-option=--remove-empty-reserved-defines",
        "--c2fb-option=--fb-source-directory=" + str(fb_source_directory),
    ]
    parallel_summary = run(parallel_command)
    assert "published 2 candidates" in parallel_summary, parallel_summary
    assert "jobs 2" in parallel_summary, parallel_summary
    for serial_path in output_directory.iterdir():
        if serial_path.is_file():
            parallel_path = parallel_output_directory / serial_path.name
            assert parallel_path.read_bytes() == serial_path.read_bytes(), (
                serial_path.name,
                serial_path.read_text(errors="replace"),
                parallel_path.read_text(errors="replace"),
            )

    for label, candidate, value, adjustment, expected in (
        ("a", candidate_a, 5, None, 26),
        ("b", candidate_b, 2, 3, 47),
    ):
        wrapper = output_directory / f"check_{label}.bas"
        setup = f"state.value = {value}\n"
        if adjustment is not None:
            setup += f"state.adjustment = {adjustment}\n"
        wrapper.write_text(
            f'#include once "{candidate.name}"\n'
            "Dim state As c2fb_UnitState\n"
            f"{setup}"
            f"If c2fbReadUnit{label.upper()}(@state) <> {expected} Then End 1\n"
        )
        executable = output_directory / f"check_{label}"
        run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
            cwd=output_directory)
        run([str(executable)], cwd=output_directory)

    published_files = {
        path.name: path.read_bytes() for path in output_directory.iterdir()
        if path.is_file()
    }
    parallel_published_files = {
        path.name: path.read_bytes() for path in parallel_output_directory.iterdir()
        if path.is_file()
    }
    failure = subprocess.run(
        parallel_command + ["--c2fb-option=--c2fb-unsupported-test-option"],
        capture_output=True, text=True,
    )
    assert failure.returncode != 0, "invalid C2FB option unexpectedly succeeded"
    assert {
        path.name: path.read_bytes() for path in output_directory.iterdir()
        if path.is_file()
    } == published_files, "failed conversion changed already published outputs"
    assert {
        path.name: path.read_bytes() for path in parallel_output_directory.iterdir()
        if path.is_file()
    } == parallel_published_files, (
        "failed parallel conversion changed already published outputs"
    )
    assert not any(path.name.startswith(".c2fb-compile-commands-")
                   for path in output_directory.iterdir())
    invalid_jobs = subprocess.run(
        parallel_command + ["--jobs=33"],
        capture_output=True, text=True,
    )
    assert invalid_jobs.returncode != 0
    assert "--jobs must be between 1 and 32" in invalid_jobs.stderr
    assert not any(path.name.startswith(".c2fb-compile-commands-")
                   for path in parallel_output_directory.iterdir())

    direct_source = project / "src/direct.c"
    direct_source.write_text("int c2fbDirectUnit(void) { return 17; }\n")
    direct_source_b = project / "src/direct_b.c"
    direct_source_b.write_text("int c2fbDirectUnitB(void) { return 19; }\n")
    direct_database = build_directory / "direct_compile_commands.json"
    direct_database.write_text(json.dumps([{
        "directory": directory,
        "file": "src/direct.c",
        "arguments": [
            *cc, "-std=c99", "-c", "src/direct.c", "-o", "build/direct.o",
        ],
    }, {
        "directory": directory,
        "file": "src/direct_b.c",
        "arguments": [
            *cc, "-std=c99", "-c", "src/direct_b.c", "-o", "build/direct_b.o",
        ],
    }]))
    direct_output = project / "direct candidate output"
    direct_command = [
        sys.executable, str(tool), str(direct_database),
        str(direct_output), "--converter", converter_path, "--jobs=2",
    ]
    direct_summary = run(direct_command)
    assert "published 2 candidates" in direct_summary, direct_summary
    assert "jobs 2" in direct_summary, direct_summary
    with (direct_output / "compile-command-map.csv").open(
        encoding="utf-8", newline=""
    ) as map_file:
        direct_rows = list(csv.DictReader(map_file))
    assert len(direct_rows) == 2, direct_rows
    assert all(row["SourceUnitContext"] == "0" for row in direct_rows), direct_rows
    assert all(row["TypeContextFile"] == "" for row in direct_rows), direct_rows
    direct_candidates = [
        direct_output / row["CandidateFile"] for row in direct_rows
    ]
    for candidate, procedure_name, expected_value in zip(
        direct_candidates,
        ("c2fbDirectUnit", "c2fbDirectUnitB"),
        (17, 19),
    ):
        direct_wrapper = direct_output / f"check_{procedure_name}.bas"
        direct_wrapper.write_text(
            f'#include once "{candidate.name}"\n'
            f"If {procedure_name}() <> {expected_value} Then End 1\n"
        )
        direct_executable = direct_wrapper.with_suffix("")
        run(fbc + ["-w", "all", str(direct_wrapper), "-x", str(direct_executable)],
            cwd=direct_output)
        run([str(direct_executable)], cwd=direct_output)


def check_source_unit_pair_publication_rollback(converter, cc, work):
    # A failed second rename must leave the old type context paired with no candidate.
    source_directory = work / "source-unit-pair-publication-rollback"
    source_directory.mkdir()
    source = source_directory / "publication.c"
    source.write_text("int c2fbPublicationProbe(void) { return 17; }\n")
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"

    for suffix, previous_context in (("existing", "previous type context\n"),
                                     ("new", None)):
        candidate = source_directory / f"candidate-{suffix}.bas"
        candidate.mkdir()
        type_context = source_directory / f"candidate-{suffix}_types.bi"
        if previous_context is not None:
            type_context.write_text(previous_context)
        command = [
            sys.executable, str(source_unit_tool), str(source), str(candidate),
            "--converter", converter, "--compiler", cc[0],
            "--type-context", str(type_context),
        ]
        failure = subprocess.run(command, capture_output=True, text=True)
        assert failure.returncode != 0, failure.stdout + failure.stderr
        assert "cannot stage C2FB source-unit outputs" in failure.stderr, failure.stderr
        assert candidate.is_dir(), "failed publication changed the candidate target"
        if previous_context is None:
            assert not type_context.exists() and not type_context.is_symlink(), (
                "failed publication left a new type context behind"
            )
        else:
            assert type_context.read_text() == previous_context, (
                "failed publication replaced the existing type context"
            )
        assert not any(
            path.name.startswith(".c2fb-source-unit-")
            for path in source_directory.iterdir()
        ), "failed publication left staging directories behind"
        candidate.rmdir()


def check_compile_commands_publication_rollback(work):
    # A failed staged rename restores every previous candidate, context, and map.
    tool = Path(__file__).resolve().parents[1] / "c2fb_compile_commands.py"
    spec = importlib.util.spec_from_file_location("c2fb_compile_commands", tool)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)

    for case_name, previous_outputs in (
        ("existing", True),
        ("new", False),
    ):
        case_directory = work / f"compile-command-publication-{case_name}"
        staged_directory = case_directory / "staged"
        backup_directory = staged_directory / "previous-output"
        case_directory.mkdir()
        staged_directory.mkdir()
        final_outputs = [
            case_directory / "candidate_types.bi",
            case_directory / "candidate.bas",
            case_directory / "compile-command-map.csv",
        ]
        staged_outputs = [
            (staged_directory / "new-types.bi", final_outputs[0]),
            (staged_directory / "new-candidate.bas", final_outputs[1]),
            (staged_directory / "new-map.csv", final_outputs[2]),
        ]
        new_contents = (
            "new type context\n",
            "new candidate\n",
            "new command map\n",
        )
        old_contents = (
            "old type context\n",
            "old candidate\n",
            "old command map\n",
        )
        for (staged_path, _), new_text in zip(staged_outputs, new_contents):
            staged_path.write_text(new_text)
        if previous_outputs:
            for final_path, old_text in zip(final_outputs, old_contents):
                final_path.write_text(old_text)

        original_replace = module.os.replace

        def fail_candidate_rename(source, destination):
            if Path(source) == staged_outputs[1][0]:
                raise OSError("injected candidate rename failure")
            return original_replace(source, destination)

        module.os.replace = fail_candidate_rename
        try:
            try:
                module.publish_staged_outputs(staged_outputs, backup_directory)
            except OSError as error:
                assert "injected candidate rename failure" in str(error), error
            else:
                raise AssertionError("injected compile-command rename failure was ignored")
        finally:
            module.os.replace = original_replace

        if previous_outputs:
            for final_path, old_text in zip(final_outputs, old_contents):
                assert final_path.read_text() == old_text, (
                    final_path.name,
                    final_path.read_text(),
                )
        else:
            assert not any(
                final_path.exists() or final_path.is_symlink()
                for final_path in final_outputs
            ), "failed compile-command publication left outputs behind"
        assert list(backup_directory.iterdir()) == [], (
            "failed compile-command publication left backups behind"
        )


def check_fbfrog_audit_name_scope():
    audit_path = Path(__file__).resolve().parents[1] / "audit_fbfrog.py"
    spec = importlib.util.spec_from_file_location("audit_fbfrog", audit_path)
    audit = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(audit)
    assert audit.noninteger_object_macro_kinds(
        '#define SINGLE_VALUE 0.1f\n'
        '#define DOUBLE_VALUE 1.25e-3\n'
        '#define STRING_VALUE "one" "two"\n'
    ) == {
        "SINGLE_VALUE": "single",
        "DOUBLE_VALUE": "double",
        "STRING_VALUE": "string",
    }
    assert audit.noninteger_object_macro_kinds(
        r'#define EMBEDDED_NUL "\x000"' + "\n"
    ) == {}
    assert audit.emitted_object_macro_names(
        "Const floatValue As Single = 0.1!\n"
        "Const doubleValue As Double = 1.25e-3#\n"
    ) == {"floatValue", "doubleValue"}
    assert audit.freebasic_noninteger_macro_probe_kind(
        '#define stringValue "text"\n', "stringValue", "string"
    ) == "string-value"
    assert audit.freebasic_noninteger_macro_probe_kind(
        '#define stringPointer StrPtr(!"text")\n',
        "stringPointer", "string",
    ) == "string"
    assert audit.translate_fbfrog_options(["-define", "EMPTY", ""]) == [
        "-DEMPTY="
    ]
    assert audit.translate_fbfrog_options(["-define", "VALUE", "17"]) == [
        "-DVALUE=17"
    ]
    assert audit.translate_fbfrog_options(["-define", "FLAG"]) == ["-DFLAG"]
    assert audit.split_compiler_options(["-DEMPTY=", "-Iinclude"]) == (
        [], ["-DEMPTY=", "-Iinclude"]
    )
    macro_mismatch = [("pragma-operator.h", "A", "linux", "2", "1")]
    fbfrog_divergence = [("pragma-operator.h", "A", "linux", 2, 1)]
    assert audit.macro_value_mismatches_not_explained_by_source(
        macro_mismatch, fbfrog_divergence, []) == []
    assert audit.macro_value_mismatches_not_explained_by_source(
        macro_mismatch, fbfrog_divergence,
        [("pragma-operator.h", "A", "linux", 3, 1)],
    ) == macro_mismatch
    assert audit.macro_value_mismatches_not_explained_by_source(
        macro_mismatch, [], []) == macro_mismatch
    missing_names = [
        ("good.h", 1, 2, ["A"]),
        ("bad-baseline.h", 0, 1, ["B"]),
        ("unchecked.h", 0, 1, ["C"]),
    ]
    assert audit.missing_names_with_comparable_baselines(
        missing_names,
        {"good.h": True, "bad-baseline.h": False},
    ) == [missing_names[0], missing_names[2]]
    generated = '''
' Dim Shared commentedLine As Long
/*
Type commentedBlock
End Type
Declare Sub commentedProcedure()
*/
Type Alias As Long
Type Record
    Declare Function memberProcedure() As Long
    Union
        Dim Shared unionMember As Long
    End Union
End Type
Dim Shared visibleObject As Long
Private Dim Shared privateObject As Long
Declare Sub visibleProcedure()
'''
    assert audit.emitted_binding_names(generated) == {
        "Alias", "Record", "visibleObject", "privateObject", "visibleProcedure",
    }
    assert audit.matched_emitted_names({"A_"}, {"A_"}, "c2fb_") == {"A_"}
    assert audit.matched_emitted_names({"A"}, {"c2fb_A"}, "c2fb_") == {"A"}
    assert audit.is_safe_integer_macro_expression(
        "((left) + (right * 2))", {"left", "right"})
    assert not audit.is_safe_integer_macro_expression("value+", {"value"})
    assert not audit.is_safe_integer_macro_expression(
        "int define defined", {"int", "define", "defined"})
    assert not audit.is_safe_integer_macro_expression(
        "(" * 600 + "value" + ")" * 600, {"value"})
    assert audit.integer_function_macro_definitions(
        "#define A(value) value+\n"
        "#define B(value) A(value)\n"
    ) == {}
    assert audit.integer_function_macro_definitions(
        "#define m1(int, define, defined) int define defined\n"
    ) == {}


def check_fbfrog_define_option_compatibility(converter, fbc, work):
    # FBFrog's per-header -define option maps to the same C preprocessor flags
    # C2FB receives from a compilation database.
    audit_path = Path(__file__).resolve().parents[1] / "audit_fbfrog.py"
    spec = importlib.util.spec_from_file_location("audit_fbfrog_define", audit_path)
    audit = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(audit)

    source_directory = work / "fbfrog-define-option"
    source_directory.mkdir()
    source = source_directory / "defines.h"
    source.write_text(
        "#ifdef C2FB_EMPTY_DEFINE\n"
        "extern int c2fbEmptyDefine;\n"
        "#endif\n"
        "#if C2FB_VALUE_DEFINE == 17\n"
        "extern int c2fbValueDefine;\n"
        "#endif\n"
        "#ifdef C2FB_UNSET_DEFINE\n"
        "extern int c2fbUnexpectedDefine;\n"
        "#endif\n"
    )
    fbfrog_options = [
        "-define", "C2FB_EMPTY_DEFINE", "",
        "-define", "C2FB_VALUE_DEFINE", "17",
    ]
    translated = audit.translate_fbfrog_options(fbfrog_options)
    assert translated == ["-DC2FB_EMPTY_DEFINE=", "-DC2FB_VALUE_DEFINE=17"]
    converter_options, compiler_options = audit.split_compiler_options(translated)
    binding = source_directory / "defines.bi"
    run([
        converter, "generic-header", str(source), str(binding),
        *converter_options, "cc", *compiler_options,
    ])
    generated = binding.read_text().casefold()
    assert "c2fbemptydefine" in generated, generated
    assert "c2fbvaluedefine" in generated, generated
    assert "c2fbunexpecteddefine" not in generated, generated
    wrapper = source_directory / "check_defines.bas"
    wrapper.write_text('#include once "defines.bi"\n')
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "defines.o")], cwd=source_directory)
    assert audit.missing_name_counts_by_baseline_status(
        [
            ("good.h", 1, 3, ["B", "C"]),
            ("bad.h", 0, 1, ["D"]),
            ("unchecked.h", 0, 1, ["E"]),
        ],
        {"good.h": True, "bad.h": False},
    ) == (2, 1, 1)
    assert audit.c2fb_compile_failures_by_baseline_status(
        [
            ("good.h", "C2FB binding", False, "compile error"),
            ("bad.h", "C2FB profile", False, "compile error"),
            ("unchecked.h", "C2FB binding", False, "compile error"),
            ("passed.h", "C2FB binding", True, ""),
            ("good.h", "fbfrog baseline", False, "baseline error"),
        ],
        {"good.h": True, "bad.h": False},
    ) == (
        [("good.h", "C2FB binding", False, "compile error")],
        [("bad.h", "C2FB profile", False, "compile error")],
        [("unchecked.h", "C2FB binding", False, "compile error")],
    )
    assert audit.body_options([
        "--replacement-file=rules.rpl", "--rename-proc=f=g",
        "--expand-type=T",
    ]) == ["--replacement-file=rules.rpl", "--rename-proc=f=g"]
    assert audit.fbfrog_fixture_uses_cpp(
        Path("tests/cpp/expand/example.h"), Path("tests"))
    assert audit.fbfrog_fixture_uses_cpp(
        Path("tests/include/example.hpp"), Path("tests"))
    assert not audit.fbfrog_fixture_uses_cpp(
        Path("tests/include/example.h"), Path("tests"))
    with tempfile.TemporaryDirectory(prefix="c2fb-cpp-fixture-detect-") as directory:
        header = Path(directory) / "default-argument.h"
        header.write_text("int f(int value = 1);\n")
        assert audit.fbfrog_fixture_uses_cpp(header, Path(directory))
        header.write_text("void f(void) { if (flag = 1); }\n")
        assert not audit.fbfrog_fixture_uses_cpp(header, Path(directory))
    with tempfile.TemporaryDirectory(prefix="c2fb-target-fixture-detect-") as directory:
        header = Path(directory) / "targets.h"
        header.write_text(
            "#if defined(_WIN32)\nint windows_value;\n"
            "#elif defined(DJGPP) || defined(__unix__)\nint dos_or_unix_value;\n"
            "#elif defined(__linux__)\nint linux_value;\n#endif\n"
        )
        assert audit.fbfrog_fixture_target_filters(
            header, Path(directory)
        ) == [
            "dos", "freebsd-x86_64", "linux-x86_64", "win32", "win64",
        ]
        header.write_text(
            "#define TOKENS(parameter) #parameter, #unknown\n"
            "// int commented(void) { return 0; }\n"
            "int declared(int value);\n"
        )
        assert not audit.source_contains_function_definition(header)
        header.write_text("int defined(int value) { return value; }\n")
        assert audit.source_contains_function_definition(header)
    with tempfile.TemporaryDirectory(prefix="c2fb-missing-include-detect-") as directory:
        root = Path(directory)
        header = root / "input.h"
        header.write_text("#include MISSING_HEADER\n")
        baseline = root / "input.bi"
        baseline.write_text('#include once "external/missing.bi"\n')
        assert audit.inferred_missing_include_options(
            header, baseline, root
        ) == [
            "--preserve-missing-includes",
            "--preserve-include=external/missing.h=external/missing.bi",
        ]
        (root / "external").mkdir()
        (root / "external" / "missing.h").write_text("/* present */\n")
        assert audit.inferred_missing_include_options(header, baseline, root) == []
    assert audit.translate_fbfrog_options(
        ["-renametag", "A", "TagA"]
    ) == ["--rename-tag=A=TagA"]
    assert audit.translate_fbfrog_options(
        ["-renametypedef", "A", "AliasA"]
    ) == ["--rename-typedef=A=AliasA"]
    assert audit.translate_fbfrog_options(
        ["-title", "Library 1.0", "/tmp/license.txt", "/tmp/translators.txt"]
    ) == [
        "--title=Library 1.0",
        "--license-file=/tmp/license.txt",
        "--translators-file=/tmp/translators.txt",
    ]
    assert audit.translate_fbfrog_options(
        ["-fbfroginclude", "/tmp/preinclude.h"]
    ) == ["--c-include=/tmp/preinclude.h",
          "--exclude-source=/tmp/preinclude.h"]
    assert audit.translate_fbfrog_options(
        ["-expandindefine", "SUFFIX*"]
    ) == ["--expand-in-define=SUFFIX*"]
    assert audit.translate_fbfrog_options(
        ["-emit", "*/main.h", "main.bi", "-emit", "*/one.h", "one.bi",
         "-addinclude", "added-one.bi", "one.bi", "-inclib", "audio",
         "-undef", "UNUSED", "one.bi"]
    ) == [
        "--emit-source=*/main.h", "--emit-source=*/one.h",
        "--fb-include=added-one.bi", "--fb-library=audio", "--undef=UNUSED",
    ]
    assert audit.translate_fbfrog_options(
        ["-renameproc", "A", "ProcA", "-renamedefine", "M", "MacroM",
         "-renamemacroparam", "x", "x_renamed"]
    ) == ["--rename-proc=A=ProcA", "--rename-define=M=MacroM",
          "--rename-macro-param=x=x_renamed"]
    assert audit.translate_fbfrog_options(
        ["-removeproc", "A", "-removevar", "B", "-removedefine", "M",
         "-remove", "*Private*"]
    ) == ["--exclude-proc=A", "--exclude-variable=B",
          "--exclude-define=M", "--exclude=*Private*"]
    assert audit.translate_fbfrog_options(
        ["-moveabove", "b", "a", "-setarraysize", "items", "12",
         "-setarraysize", "s4", 'len("foo")',
         "-emit", "*/api.h", "api.bi", "-dontemit", "*/private.h",
         "-ifndefdecl", "A*", "-undefbeforedecl", "B", "-convbodytokens", "M*",
         "-addinclude", "foo.bi", "-inclib", "foo", "-undef", "sleep",
         "-removeinclude", "child.h", "-replacements", "Rules.rpl",
         "-incdir", "include", "-include", "pre.h",
         "-removeEmptyReservedDefines", "-windowsms", "-fixunsizedarrays"]
    ) == [
        "--move-above=b=a", "--array-size=items=12", '--array-size=s4=len("foo")',
        "--emit-source=*/api.h", "--exclude-source=*/private.h",
        "--ifndef-decl=A*",
        "--undef-before-decl=B", "--convert-macro-tokens=M*",
        "--fb-include=foo.bi", "--fb-library=foo", "--undef=sleep",
        "--remove-include=child.h", "--replacement-file=Rules.rpl",
        "-Iinclude", "-include", "pre.h", "--remove-empty-reserved-defines",
        "--windows-ms", "--fix-unsized-arrays",
    ]
    assert audit.expected_declaration_names(
        {"A", "TagA", "AliasA", "ProcA", "MacroM"}, {"A"},
        ["--rename-tag=A=TagA", "--rename-typedef=A=AliasA",
         "--rename-proc=A=ProcA", "--rename-define=M=MacroM"],
    ) == {"A", "TagA", "AliasA", "ProcA", "MacroM"}
    assert audit.expected_macro_names(
        {"M", "MacroM"}, {"M"}, ["--rename-define=M=MacroM"]
    ) == {"M", "MacroM"}
    assert audit.expected_macro_names(
        {"x2", "MacroM"}, {"Macro"}, ["--rename=x1=x2", "--rename=Macro=MacroM"]
    ) == {"MacroM"}
    assert audit.body_options([
        "--rename-proc=A=ProcA", "--rename-define=M=MacroM",
    ]) == ["--rename-proc=A=ProcA"]
    assert audit.split_compiler_options([
        "--array-size=items=4", "-Iheaders", "-include", "config.h",
    ]) == (
        ["--array-size=items=4"],
        ["-Iheaders", "-include", "config.h"],
    )
    with tempfile.TemporaryDirectory(prefix="c2fb-fbfrog-version-script-") as directory:
        script = Path(directory) / "versions.fbfrog"
        script.write_text(
            "-declareversions VER 1 2\n"
            "-selectversion\n"
            "-case 1\n"
            "    -define VER 1\n"
            "-case 2 -define VER 2\n"
            "-endselect\n"
        )
        assert audit.parse_fbfrog_version_script(
            [str(script)], Path(directory)
        ) == {
            "macro": "VER",
            "values": ["1", "2"],
            "selected_cases": {
                "1": [("VER", "1")],
                "2": [("VER", "2")],
            },
        }


def check_fbfrog_body_candidate_compilation(converter, fbc, cc, work):
    source_directory = work / "fbfrog-body-audit"
    source_directory.mkdir()
    header = source_directory / "simple.h"
    header.write_text(
        "int c2fbAuditAddOne(int value) { return value + 1; }\n"
    )
    baseline = source_directory / "simple.bi"
    baseline.write_text(
        "#pragma once\n"
        "extern \"C\"\n"
        "declare function c2fbAuditAddOne(byval value as long) as long\n"
        "end extern\n"
    )
    audit_path = Path(__file__).resolve().parents[1] / "audit_fbfrog.py"
    result = subprocess.run([
        sys.executable, str(audit_path),
        "--converter", converter,
        "--fbfrog-tests", str(source_directory),
        "--scope", "declarations",
        "--compile-bindings", "--compile-body-candidates",
        "--cc", shlex.join(cc), "--fbc", shlex.join(fbc),
    ], capture_output=True, text=True, check=False)
    diagnostics = result.stdout + result.stderr
    assert result.returncode == 0, diagnostics
    assert "C2FB conversion failures: 0" in diagnostics, diagnostics
    assert "FBC-compilable C2FB binding+body outputs: 1/1" in diagnostics, diagnostics


def check_preprocessing(converter, repository, fb_directory, work, compiler, fbc):
    # Exercise relative paths, spaces, and shell quoting through the real
    # preprocessor. The tiny source tree uses SQLite's pragma generator only.
    root = work / "preprocess tree's"
    source = root / "src"
    source.mkdir(parents=True)
    (root / "tool").symlink_to(repository / "tool", target_is_directory=True)
    (root / "generated").mkdir()
    (source / "sqlite.h.in").write_text("#ifndef SQLITE3_H\n#define SQLITE3_H\n")
    (source / "sample.c").write_text(
        '#include "sqlite3.h"\n'
        '#if SQLITE_THREADSAFE\n'
        'int c2fbProfile(void){ return 1; }\n'
        '#else\n'
        'int c2fbProfile(void){ return 0; }\n'
        '#endif\n'
        'typedef struct sqlite3 {\n'
        '    union { volatile int isInterrupted; double notUsed1; } u1;\n'
        '} sqlite3;\n'
        'int c2fbAtomicInterrupt(sqlite3 *db) {\n'
        '    return __atomic_load_n(&db->u1.isInterrupted, 0);\n'
        '}\n'
        'void c2fbAtomicInterruptStore(sqlite3 *db, int value) {\n'
        '    __atomic_store_n(&db->u1.isInterrupted, value, 0);\n'
        '}\n'
        'typedef struct Fts5Sorter Fts5Sorter;\n'
        'struct Fts5Sorter {\n'
        '    void *pStmt;\n'
        '    long long iRowid;\n'
        '    int nIdx;\n'
        '    int aIdx[];\n'
        '};\n'
        'void c2fbSorterFields(Fts5Sorter *sorter) {\n'
        '    if (sorter->pStmt) sorter->iRowid++;\n'
        '}\n'
        'int c2fbSorterArrayRead(Fts5Sorter *sorter, int index) {\n'
        '    return sorter->aIdx[index];\n'
        '}\n'
        'typedef struct Fts5StructureSegment Fts5StructureSegment;\n'
        'typedef struct Fts5StructureLevel Fts5StructureLevel;\n'
        'typedef struct Fts5Structure Fts5Structure;\n'
        'struct Fts5StructureSegment { int iSegid; };\n'
        'struct Fts5StructureLevel {\n'
        '    int nMerge; int nSeg; Fts5StructureSegment *aSeg;\n'
        '};\n'
        'struct Fts5Structure { int nLevel; Fts5StructureLevel aLevel[]; };\n'
        'int c2fbNestedPostIncrement(Fts5Structure *structure) {\n'
        '    return structure->aLevel[0].aSeg[structure->aLevel[0].nSeg++].iSegid;\n'
        '}\n'
        'typedef struct RecordAlias { int value; int count; } RecordAlias;\n'
        'int c2fbMappedRecord(RecordAlias *record) {\n'
        '    if (record->count == 0) return 0;\n'
        '    record->count++;\n'
        '    return record->value;\n'
        '}\n'
        'int c2fbMappedRecordSize(void) { return sizeof(RecordAlias); }\n'
        'int c2fbMappedRecordLocal(void) {\n'
        '    RecordAlias local = { 19, 3 };\n'
        '    return local.value + local.count;\n'
        '}\n'
    )
    output = root / "candidates"
    prefix = [converter, "translate-preprocessed-tree", "./preprocess tree's/src",
              "./preprocess tree's/generated", "./preprocess tree's/candidates",
              str(fb_directory)]
    for profile in ("0", "1"):
        run(prefix + [compiler, profile], cwd=work)
        candidate = (output / "sample_preprocessed_candidates.bas").read_text()
        expected_names = {
            "c2fbProfile", "c2fbMappedRecord", "c2fbMappedRecordSize",
            "c2fbMappedRecordLocal",
        }
        if profile == "0":
            expected_names.update((
                "c2fbAtomicInterrupt", "c2fbAtomicInterruptStore"))
            assert "->isInterrupted" in candidate, candidate
            assert "->u1" not in candidate, candidate
            wrapper = work / "check_atomic.bas"
            wrapper.write_text(
                f'#include once "{(output / "sample_preprocessed_candidates.bas").resolve()}"\n'
                "Dim db As sqlite3\n"
                "db.isInterrupted = 1\n"
                "If c2fbAtomicInterrupt(@db) <> 1 Then End 1\n"
                "c2fbAtomicInterruptStore(@db, 0)\n"
                "If c2fbAtomicInterrupt(@db) <> 0 Then End 2\n"
            )
            for backend_flags in ([], ["-gen", "gcc"]):
                executable = work / (
                    "check_atomic" if not backend_flags else "check_atomic_gcc"
                )
                run(fbc + backend_flags + [
                    "-w", "all", "-d", "SQLITE_THREADSAFE=0", "-i",
                    str(fb_directory), str(wrapper), "-x", str(executable),
                ], cwd=work)
                run([str(executable)], cwd=work)
        else:
            assert "c2fb skipped c2fbAtomicInterrupt:" in candidate, candidate
            assert "c2fb skipped c2fbAtomicInterruptStore:" in candidate, candidate
        assert procedure_names(candidate) == expected_names
        body = candidate.split("Function c2fbProfile", 1)[1]
        assert f"&O{profile}ULL" in body or f"{profile}ULL" in body, "Wrong preprocessing branch"

    mapped_fb_directory = root / "mapped FB source"
    mapped_fb_directory.mkdir()
    for interface in fb_directory.glob("*.bi"):
        (mapped_fb_directory / interface.name).symlink_to(interface)
    (mapped_fb_directory / "c2fb_preprocessed_type_map.bi").write_text(
        '#include once "sqlite3_types.bi"\n'
        "Type PortRecord\n"
        "    value As Long\n"
        "    count As Long\n"
        "End Type\n"
        "Type c2fb_Fts5Sorter\n"
        "    pStmt As Any Ptr\n"
        "    iRowid As LongInt\n"
        "    nIdx As Long\n"
        "    _c2fb_aIdx_flex_storage As Long\n"
        "End Type\n"
        "#define c2fb_Fts5Sorter_aIdx_tail_ptr(recordPtr) CPtr(Long Ptr, @((recordPtr)->_c2fb_aIdx_flex_storage))\n"
        "Type c2fb_Fts5StructureSegment\n"
        "    iSegid As Long\n"
        "End Type\n"
        "Type c2fb_Fts5StructureLevel\n"
        "    nMerge As Long\n"
        "    nSeg As Long\n"
        "    aSeg As c2fb_Fts5StructureSegment Ptr\n"
        "End Type\n"
        "Type c2fb_Fts5Structure\n"
        "    nLevel As Long\n"
        "    _c2fb_aLevel_flex_storage As c2fb_Fts5StructureLevel\n"
        "End Type\n"
        "#define c2fb_Fts5Structure_aLevel_tail_ptr(recordPtr) Cast(c2fb_Fts5StructureLevel Ptr, Cast(UByte Ptr, @((recordPtr)->_c2fb_aLevel_flex_storage)))\n"
    )
    mapped_output = root / "mapped candidates"
    run([
        converter, "translate-preprocessed-tree", str(source),
        str(root / "generated"), str(mapped_output),
        str(mapped_fb_directory), compiler, "1", "0", "", "0",
        "--type-map=RecordAlias=PortRecord",
    ])
    mapped_candidate = mapped_output / "sample_preprocessed_candidates.bas"
    mapped_text = mapped_candidate.read_text()
    assert "Function c2fbMappedRecord" in mapped_text, mapped_text
    assert 'Alias "c2fbMappedRecord"' in mapped_text, mapped_text
    assert "c2fb skipped c2fbMappedRecord:" not in mapped_text, mapped_text
    assert "Sub c2fbSorterFields" in mapped_text, mapped_text
    assert "c2fb skipped c2fbSorterFields:" not in mapped_text, mapped_text
    assert "Function c2fbSorterArrayRead" in mapped_text, mapped_text
    assert "c2fb skipped c2fbSorterArrayRead:" not in mapped_text, mapped_text
    assert "Function c2fbNestedPostIncrement" in mapped_text, mapped_text
    assert "c2fb skipped c2fbNestedPostIncrement:" not in mapped_text, mapped_text
    for function_name in ("c2fbMappedRecordSize", "c2fbMappedRecordLocal"):
        assert f"Function {function_name}" in mapped_text, mapped_text
        assert f"c2fb skipped {function_name}:" not in mapped_text, mapped_text
    mapped_wrapper = root / "mapped_check.bas"
    mapped_wrapper.write_text(
        f'#include once "{mapped_candidate.resolve()}"\n'
        "Dim record As PortRecord\n"
        "record.value = 23 : record.count = 1\n"
        "If c2fbMappedRecord(@record) <> 23 Then End 1\n"
        "If record.count <> 2 Then End 2\n"
        "If c2fbMappedRecordSize() <> SizeOf(PortRecord) Then End 3\n"
        "If c2fbMappedRecordLocal() <> 22 Then End 4\n"
        "Dim sorter As c2fb_Fts5Sorter\n"
        "sorter.pStmt = CPtr(Any Ptr, 1)\n"
        "sorter.iRowid = 9\n"
        "c2fbSorterFields(@sorter)\n"
        "If sorter.iRowid <> 10 Then End 5\n"
        "c2fb_Fts5Sorter_aIdx_tail_ptr(@sorter)[0] = 17\n"
        "If c2fbSorterArrayRead(@sorter, 0) <> 17 Then End 6\n"
        "Dim nested As c2fb_Fts5Structure\n"
        "Dim nestedSegments(0 To 0) As c2fb_Fts5StructureSegment\n"
        "nested._c2fb_aLevel_flex_storage.nSeg = 0\n"
        "nested._c2fb_aLevel_flex_storage.aSeg = @nestedSegments(0)\n"
        "nestedSegments(0).iSegid = 23\n"
        "If c2fbNestedPostIncrement(@nested) <> 23 Then End 7\n"
        "If nested._c2fb_aLevel_flex_storage.nSeg <> 1 Then End 8\n"
    )
    for backend_name, backend_flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        mapped_executable = root / f"mapped_check_{backend_name}"
        run(fbc + backend_flags + [
            "-w", "all", "-d", "SQLITE_THREADSAFE=1", "-i",
            str(mapped_fb_directory), str(mapped_wrapper), "-x",
            str(mapped_executable),
        ], cwd=root)
        run([str(mapped_executable)], cwd=root)

    mapped_file_output = root / "mapped file candidates"
    run([
        converter, "translate-preprocessed-files", str(source),
        str(root / "generated"), str(mapped_file_output),
        str(mapped_fb_directory), compiler, "1", "0", "", "0",
        "sample.c", "--type-map=RecordAlias=PortRecord",
    ])
    mapped_file_candidate = (
        mapped_file_output / "sample_preprocessed_candidates.bas"
    ).read_text()
    assert "Function c2fbMappedRecord" in mapped_file_candidate, mapped_file_candidate
    assert "c2fb skipped c2fbMappedRecord:" not in mapped_file_candidate, mapped_file_candidate

    (mapped_fb_directory / "c2fb_bulk_options.bi").write_text(
        "Private Dim Shared _\n"
        "    sqlitePortCounter As Long\n"
    )
    body_options_source = source / "body_options.c"
    body_options_source.write_text(
        "static int privateCounter = 1;\n"
        "int c2fbBodyOptionsProbe(void) { return privateCounter + 2; }\n"
    )
    body_options_output = root / "body options candidates"
    run([
        converter, "translate-preprocessed-files", str(source),
        str(root / "generated"), str(body_options_output),
        str(mapped_fb_directory), compiler, "1", "0", "", "0",
        "body_options.c", "--rename-proc-prefix=ported_",
        "--reuse-static-object=privateCounter=sqlitePortCounter",
    ])
    body_options_candidate = (
        body_options_output / "body_options_preprocessed_candidates.bas"
    )
    body_options_text = body_options_candidate.read_text()
    assert "ported_c2fbBodyOptionsProbe" in body_options_text, body_options_text
    assert "sqlitePortCounter" in body_options_text, body_options_text
    assert '"c2fb_bulk_options.bi"' in body_options_text, body_options_text
    assert "Private Dim Shared c2fb_global_privateCounter" not in \
        body_options_text, body_options_text
    body_options_wrapper = root / "body_options_check.bas"
    body_options_wrapper.write_text(
        f'#include once "{body_options_candidate.resolve()}"\n'
        "sqlitePortCounter = 40\n"
        "If ported_c2fbBodyOptionsProbe() <> 42 Then End 1\n"
    )
    body_options_executable = root / "body_options_check"
    run(fbc + [
        "-w", "all", "-d", "SQLITE_THREADSAFE=1", "-i",
        str(mapped_fb_directory), str(body_options_wrapper), "-x",
        str(body_options_executable),
    ], cwd=root)
    run([str(body_options_executable)], cwd=root)

    explain_source = source / "explain.c"
    explain_source.write_text(
        "typedef struct Parse Parse;\n"
        "int sqlite3VdbeExplain(Parse *parse, int push, const char *format, ...);\n"
        "int c2fbExplainIntegerString(Parse *parse, int rowCount) {\n"
        '    sqlite3VdbeExplain(parse, 0, "SCAN %d CONSTANT ROW%s", rowCount,\n'
        '        rowCount == 1 ? "" : "S");\n'
        "    return rowCount;\n"
        "}\n"
    )
    explain_output = root / "explain candidates"
    run([
        converter, "translate-preprocessed-files", str(source),
        str(root / "generated"), str(explain_output),
        str(mapped_fb_directory), compiler, "1", "0", "", "0",
        "explain.c",
    ])
    explain_candidate = explain_output / "explain_preprocessed_candidates.bas"
    explain_text = explain_candidate.read_text()
    assert "sqlite3VdbeExplainIntegerString" in explain_text, explain_text
    assert "c2fb skipped c2fbExplainIntegerString:" not in explain_text, explain_text
    run(fbc + ["-w", "all", "-d", "SQLITE_THREADSAFE=1", "-i",
               str(mapped_fb_directory), "-c", str(explain_candidate), "-o",
               str(root / "explain_candidates.o")], cwd=root)

    assert_probe_source = source / "assert_probe.c"
    assert_probe_source.write_text(
        '#include <assert.h>\n'
        'int c2fbAssertProbe(int value) { assert(value++ > 0); return value; }\n'
        'int c2fbAssertPointerProbe(void *pointer) { assert(pointer); return pointer != 0; }\n'
    )
    assert_output = root / "assert candidates"
    run([
        converter, "translate-preprocessed-files", str(source),
        str(root / "generated"), str(assert_output), str(fb_directory),
        compiler, "1", "0", "SQLITE_DEBUG=1,C2FB_RESTORE_ASSERTS=1", "0",
        "assert_probe.c",
    ])
    assert_candidate = assert_output / "assert_probe_preprocessed_candidates.bas"
    assert_text = assert_candidate.read_text()
    assert "sqlite3DebugAssertCheck" in assert_text, assert_text
    assert 'StrPtr(!"value++ > 0")' in assert_text, assert_text
    assert 'StrPtr(!"pointer")' in assert_text, assert_text
    assert "assertions were suppressed" not in assert_text, assert_text

    assert_wrapper = root / "assert_check.bas"
    assert_wrapper.write_text(
        '#include once "sqlite3_types.bi"\n'
        '#include once "sqlite3_constants.bi"\n'
        '#include once "sqlite3_debug_assert.bi"\n'
        'Dim Shared assertionCount As Long\n'
        'Dim Shared assertionCondition As Long\n'
        'Dim Shared assertionExpression As String\n'
        'Sub sqlite3DebugAssertCheck CDecl Alias "sqlite3DebugAssertCheck" ( _\n'
        '    ByVal condition As SQLITE_C_INT, _\n'
        '    ByVal expression As Const ZString Ptr _\n'
        ')\n'
        '    assertionCount += 1\n'
        '    assertionCondition = condition\n'
        '    If expression <> 0 Then assertionExpression = *expression\n'
        'End Sub\n'
        f'#include once "{assert_candidate.resolve()}"\n'
        'If c2fbAssertProbe(5) <> 6 Then End 1\n'
        'If assertionCount <> 1 Then End 2\n'
        'If assertionCondition = 0 Then End 3\n'
        'If assertionExpression <> "value++ > 0" Then End 4\n'
        'If c2fbAssertPointerProbe(CPtr(Any Ptr, 1)) <> 1 Then End 5\n'
        'If assertionCount <> 2 Then End 6\n'
        'If assertionCondition = 0 Then End 7\n'
        'If assertionExpression <> "pointer" Then End 8\n'
    )
    for backend_name, backend_flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        assert_executable = root / f"assert_check_{backend_name}"
        run(fbc + backend_flags + [
            "-w", "all", "-d", "SQLITE_DEBUG=1", "-d", "SQLITE_THREADSAFE=1",
            "-i", str(fb_directory), str(assert_wrapper), "-x", str(assert_executable),
        ], cwd=root)
        run([str(assert_executable)], cwd=root)

    result = subprocess.run(prefix + ["false", "1"], cwd=work, capture_output=True, text=True)
    assert result.returncode != 0, "Preprocessing failure returned success"
    assert not (output / "sample_preprocessed_candidates.bas").exists(), "Stale candidate survived failure"


def check_abi_headers(converter, repository, fb_directory, work, compiler):
    # Declaration mode must compile without engine layouts. Body conversion
    # uses typed pointers separately, so regenerating API headers stays safe.
    for source, name in (("sqlite.h.in", "public-api"), ("sqliteInt.h", "internal-api")):
        output = work / f"{name}.bi"
        run([converter, str(repository / "src" / source), str(output)])
        assert " As sqlite3 Ptr" not in output.read_text(), "ABI header requires sqlite3 layout"
        user = work / f"{name}.bas"
        user.write_text(f'#include once "{name}.bi"\n')
        run(compiler + ["-w", "all", "-d", "SQLITE_THREADSAFE=1", "-i", str(fb_directory),
                        "-c", str(user), "-o", str(work / f"{name}.o")])


def check_generic_body_generated_record_alias(converter, fbc, work):
    # A generated generic-header binding uses C2FB's default prefix for C
    # records. Body conversion should reuse that layout without a duplicate map.
    source_directory = work / "generic-body-record-alias"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "typedef Unknown ProbeByte;\n"
        "typedef struct ProbeState {\n"
        "    ProbeByte value;\n"
        "} ProbeState;\n"
    )
    source = source_directory / "probe.c"
    source.write_text(
        '#include "probe.h"\n'
        "ProbeByte c2fbReadProbeState(ProbeState *state) {\n"
        "    return state->value;\n"
        "}\n"
    )
    binding = source_directory / "probe.bi"
    run([
        converter, "generic-header", str(header), str(binding), "cc",
        "--type-map=Unknown=UByte",
    ])
    candidate = source_directory / "probe_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), "cc",
        f"-I{source_directory}",
        f"--fb-source-directory={source_directory}",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "c2fb_ProbeState" in generated, "Generated record alias was not reused"
    assert "c2fb_ProbeByte" in generated, "Generated scalar alias was not reused"

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        '#include once "probe_candidates.bas"\n'
    )
    run(fbc + ["-w", "all", "-c", str(wrapper)], cwd=source_directory)


def check_sqlite_body_unix_syscall_array(
    converter, fbc, work, catalog_directory, fb_directory
):
    # Source-private record layouts and objects stay local to one candidate unit.
    source_directory = work / "sqlite-body-unix-syscall-array"
    source_directory.mkdir()
    source = source_directory / "unix_syscall.c"
    source.write_text(
        "static struct unix_syscall {\n"
        "    const char *zName;\n"
        "    void *pCurrent;\n"
        "    void *pDefault;\n"
        "} aSyscall[1];\n"
        "int c2fbUnixSyscallNameIsNull(void) {\n"
        "    return aSyscall[0].zName == 0;\n"
        "}\n"
        "void *c2fbUnixSyscallCurrent(void) {\n"
        "    return aSyscall[0].pCurrent;\n"
        "}\n"
    )
    candidate = source_directory / "unix_syscall_candidates.bas"
    summary = run([
        converter, "translate-simple", str(source), str(candidate),
        str(catalog_directory),
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "As UnixSystemCallEntry" in generated, generated
    run(fbc + [
        "-w", "all", "-d", "SQLITE_THREADSAFE=1", "-i",
        str(fb_directory), "-c", str(candidate), "-o",
        str(source_directory / "unix_syscall.o"),
    ])

    private_source = source_directory / "private_global.c"
    private_source.write_text(
        "static struct Mem0Global { int threshold; } mem0;\n"
        "int c2fbReadPrivateGlobal(void) { return mem0.threshold; }\n"
    )
    private_candidate = source_directory / "private_global_candidates.bas"
    private_summary = run([
        converter, "translate-simple", str(private_source),
        str(private_candidate), str(catalog_directory),
    ])
    assert "translated 1 simple functions; skipped 0" in private_summary, \
        private_summary
    private_output = private_candidate.read_text()
    assert "Private Type c2fb_source_record_0" in private_output, private_output
    assert "Private Dim Shared c2fb_global_mem0 As c2fb_source_record_0" in private_output, private_output
    assert "c2fbReadPrivateGlobal" in procedure_names(private_output)
    run(fbc + [
        "-w", "all", "-d", "SQLITE_THREADSAFE=1", "-i",
        str(fb_directory), "-c", str(private_candidate), "-o",
        str(source_directory / "private_global.o"),
    ])
    private_wrapper = source_directory / "private_global_check.bas"
    private_wrapper.write_text(
        f'#include once "{private_candidate.name}"\n'
        "If c2fbReadPrivateGlobal() <> 0 Then End 1\n"
    )
    private_executable = source_directory / "private_global_check"
    run(fbc + [
        "-w", "all", "-d", "SQLITE_THREADSAFE=1", "-i",
        str(fb_directory), str(private_wrapper), "-x", str(private_executable),
    ])
