def check_sqlite_body_packed_flag_storage(
    converter, fbc, cc, work, catalog_directory, fb_directory
):
    # The port stores two C anonymous bitfield groups in single flags words.
    source_directory = work / "sqlite-body-packed-flag-storage"
    source_directory.mkdir()
    source = source_directory / "packed_flags.c"
    source.write_text(
        "struct SrcItem {\n"
        "    char *zName; char *zAlias; void *pSTab;\n"
        "    struct {\n"
        "        unsigned char jointype;\n"
        "        unsigned notIndexed:1; unsigned isIndexedBy:1;\n"
        "        unsigned isSubquery:1; unsigned isTabFunc:1;\n"
        "        unsigned isCorrelated:1; unsigned isMaterialized:1;\n"
        "    } fg;\n"
        "    int iCursor; unsigned long long colUsed;\n"
        "};\n"
        "int c2fbGetSrcItemFlags(struct SrcItem *p) {\n"
        "    return p->fg.isSubquery | (p->fg.isTabFunc << 1);\n"
        "}\n"
        "void c2fbSetSrcItemFlags(struct SrcItem *p, int value) {\n"
        "    p->fg.isSubquery = value & 1;\n"
        "    p->fg.isTabFunc = (value >> 1) & 1;\n"
        "}\n"
        "int c2fbPostIncrementSrcSubquery(struct SrcItem *p) {\n"
        "    return p->fg.isSubquery++;\n"
        "}\n"
        "int c2fbGetSrcItemOtherFlags(struct SrcItem *p) {\n"
        "    return p->fg.notIndexed | (p->fg.isIndexedBy << 1) |\n"
        "        (p->fg.isCorrelated << 2) | (p->fg.isMaterialized << 3);\n"
        "}\n"
        "struct ExprList_item {\n"
        "    void *pExpr; char *zEName;\n"
        "    struct {\n"
        "        unsigned char sortFlags; unsigned eEName:2;\n"
        "        unsigned done:1; unsigned reusable:1;\n"
        "        unsigned bSorterRef:1; unsigned bNulls:1;\n"
        "        unsigned bUsed:1; unsigned bUsingTerm:1;\n"
        "        unsigned bNoExpand:1;\n"
        "    } fg;\n"
        "};\n"
        "int c2fbGetExprListFlags(struct ExprList_item *p) {\n"
        "    return p->fg.done | (p->fg.bNulls << 1);\n"
        "}\n"
        "void c2fbSetExprListFlags(struct ExprList_item *p, int value) {\n"
        "    p->fg.done = value & 1;\n"
        "    p->fg.bNulls = (value >> 1) & 1;\n"
        "}\n"
        "int c2fbGetExprListOtherFlags(struct ExprList_item *p) {\n"
        "    return p->fg.eEName | (p->fg.reusable << 2) |\n"
        "        (p->fg.bSorterRef << 3) | (p->fg.bUsed << 4) |\n"
        "        (p->fg.bNoExpand << 5);\n"
        "}\n"
        "struct Index {\n"
        "    unsigned idxType:2; unsigned bUnordered:1;\n"
        "    unsigned uniqNotNull:1;\n"
        "};\n"
        "int c2fbGetIndexFlags(struct Index *p) {\n"
        "    return p->idxType | (p->bUnordered << 2) |\n"
        "        (p->uniqNotNull << 3);\n"
        "}\n"
        "void c2fbSetIndexFlags(struct Index *p, int value) {\n"
        "    p->idxType = value & 3;\n"
        "    p->bUnordered = (value >> 2) & 1;\n"
        "    p->uniqNotNull = (value >> 3) & 1;\n"
        "}\n"
        "struct Column { unsigned notNull:4; unsigned eCType:4; };\n"
        "int c2fbGetColumnFlags(struct Column *p) {\n"
        "    return p->notNull | (p->eCType << 4);\n"
        "}\n"
        "void c2fbSetColumnFlags(struct Column *p, int value) {\n"
        "    p->notNull = value & 15;\n"
        "    p->eCType = (value >> 4) & 15;\n"
        "}\n"
        "struct WhereInfo {\n"
        "    unsigned bDeferredSeek:1; unsigned untestedTerms:1;\n"
        "    unsigned bOrderedInnerLoop:1; unsigned sorted:1;\n"
        "    unsigned bStarDone:1; unsigned bStarUsed:1;\n"
        "};\n"
        "int c2fbGetWhereInfoFlags(struct WhereInfo *p) {\n"
        "    return p->bDeferredSeek | (p->untestedTerms << 1) |\n"
        "        (p->bOrderedInnerLoop << 2) | (p->sorted << 3) |\n"
        "        (p->bStarDone << 4) | (p->bStarUsed << 5);\n"
        "}\n"
        "void c2fbSetWhereInfoFlags(struct WhereInfo *p, int value) {\n"
        "    p->bDeferredSeek = value & 1;\n"
        "    p->untestedTerms = (value >> 1) & 1;\n"
        "    p->bOrderedInnerLoop = (value >> 2) & 1;\n"
        "    p->sorted = (value >> 3) & 1;\n"
        "    p->bStarDone = (value >> 4) & 1;\n"
        "    p->bStarUsed = (value >> 5) & 1;\n"
        "}\n"
        "struct sqlite3InitInfo {\n"
        "    unsigned int newTnum;\n"
        "    unsigned char iDb;\n"
        "    unsigned char busy;\n"
        "    unsigned orphanTrigger:1;\n"
        "    unsigned imposterTable:2;\n"
        "    unsigned reopenMemdb:1;\n"
        "    const char **azInit;\n"
        "};\n"
        "int c2fbGetDbInitBits(struct sqlite3InitInfo *p) {\n"
        "    return p->orphanTrigger | (p->imposterTable << 1) |\n"
        "        (p->reopenMemdb << 3);\n"
        "}\n"
        "void c2fbSetDbInitBits(struct sqlite3InitInfo *p, int value) {\n"
        "    p->orphanTrigger = value & 1;\n"
        "    p->imposterTable = (value >> 1) & 3;\n"
        "    p->reopenMemdb = (value >> 3) & 1;\n"
        "}\n"
    )
    candidate = source_directory / "packed_flags_candidates.bas"
    summary = run([
        converter, "translate-simple", str(source), str(candidate),
        str(catalog_directory),
    ])
    assert "translated 15 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    generated_names = procedure_names(generated)
    for procedure_name in (
        "c2fbGetSrcItemFlags", "c2fbGetExprListFlags", "c2fbGetIndexFlags",
        "c2fbGetColumnFlags", "c2fbGetWhereInfoFlags",
        "c2fbGetDbInitBits",
    ):
        assert procedure_name in generated_names, generated_names
    assert generated.count(".flags") >= 16, generated
    assert generated.count("arg0->flags") >= 6, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "packed_flags.c"\n'
        "int c2fbReferenceSrcItemFlags(void) {\n"
        "    struct SrcItem item = {0};\n"
        "    item.fg.notIndexed = 1; item.fg.isIndexedBy = 1;\n"
        "    item.fg.isCorrelated = 1; item.fg.isMaterialized = 1;\n"
        "    c2fbSetSrcItemFlags(&item, 3);\n"
        "    return c2fbGetSrcItemFlags(&item) |\n"
        "        (c2fbGetSrcItemOtherFlags(&item) << 2);\n"
        "}\n"
        "int c2fbReferenceSrcItemPostIncrement(void) {\n"
        "    struct SrcItem item = {0};\n"
        "    item.fg.notIndexed = 1; item.fg.isIndexedBy = 1;\n"
        "    item.fg.isCorrelated = 1; item.fg.isMaterialized = 1;\n"
        "    c2fbSetSrcItemFlags(&item, 3);\n"
        "    int oldValue = c2fbPostIncrementSrcSubquery(&item);\n"
        "    return oldValue | (c2fbGetSrcItemFlags(&item) << 1) |\n"
        "        (c2fbGetSrcItemOtherFlags(&item) << 3);\n"
        "}\n"
        "int c2fbReferenceExprListFlags(void) {\n"
        "    struct ExprList_item item = {0};\n"
        "    item.fg.eEName = 2; item.fg.reusable = 1;\n"
        "    item.fg.bSorterRef = 1; item.fg.bUsed = 1;\n"
        "    item.fg.bNoExpand = 1;\n"
        "    c2fbSetExprListFlags(&item, 3);\n"
        "    return c2fbGetExprListFlags(&item) |\n"
        "        (c2fbGetExprListOtherFlags(&item) << 2);\n"
        "}\n"
        "int c2fbReferenceIndexFlags(void) {\n"
        "    struct Index item = {0};\n"
        "    c2fbSetIndexFlags(&item, 15);\n"
        "    return c2fbGetIndexFlags(&item);\n"
        "}\n"
        "int c2fbReferenceColumnFlags(void) {\n"
        "    struct Column item = {0};\n"
        "    c2fbSetColumnFlags(&item, 0xA5);\n"
        "    return c2fbGetColumnFlags(&item);\n"
        "}\n"
        "int c2fbReferenceWhereInfoFlags(void) {\n"
        "    struct WhereInfo item = {0};\n"
        "    c2fbSetWhereInfoFlags(&item, 0x2D);\n"
        "    return c2fbGetWhereInfoFlags(&item);\n"
        "}\n"
        "int c2fbReferenceDbInitBits(void) {\n"
        "    struct sqlite3InitInfo info = {0};\n"
        "    c2fbSetDbInitBits(&info, 0xF);\n"
        "    return c2fbGetDbInitBits(&info);\n"
        "}\n"
    )
    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-O2", "-shared", "-fPIC",
              str(reference_source), "-o", str(reference_path)],
        cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "sqlite3_walker.bi"\n'
        '#include once "sqlite3_expr_types.bi"\n'
        '#include once "sqlite3_schema_types.bi"\n'
        '#include once "sqlite3_where_types.bi"\n'
        '#include once "packed_flags_candidates.bas"\n'
        'Function c2fbFBProbeSrcItemFlags CDecl Alias '
        '"c2fbFBProbeSrcItemFlags"() As Long\n'
        '    Dim item As SqliteSrcItem\n'
        '    item.fg.flags = &H33\n'
        '    c2fbSetSrcItemFlags(@item, 3)\n'
        '    Return c2fbGetSrcItemFlags(@item) Or '
        '(c2fbGetSrcItemOtherFlags(@item) Shl 2)\n'
        'End Function\n'
        'Function c2fbFBProbeSrcItemPostIncrement CDecl Alias '
        '"c2fbFBProbeSrcItemPostIncrement"() As Long\n'
        '    Dim item As SqliteSrcItem\n'
        '    item.fg.flags = &H33\n'
        '    c2fbSetSrcItemFlags(@item, 3)\n'
        '    Dim oldValue As Long = c2fbPostIncrementSrcSubquery(@item)\n'
        '    Return oldValue Or (c2fbGetSrcItemFlags(@item) Shl 1) Or '
        '(c2fbGetSrcItemOtherFlags(@item) Shl 3)\n'
        'End Function\n'
        'Function c2fbFBProbeExprListFlags CDecl Alias '
        '"c2fbFBProbeExprListFlags"() As Long\n'
        '    Dim item As SqliteExprListItem\n'
        '    item.fg.flags = &H15A\n'
        '    c2fbSetExprListFlags(@item, 3)\n'
        '    Return c2fbGetExprListFlags(@item) Or '
        '(c2fbGetExprListOtherFlags(@item) Shl 2)\n'
        'End Function\n'
        'Function c2fbFBProbeIndexFlags CDecl Alias '
        '"c2fbFBProbeIndexFlags"() As Long\n'
        '    Dim item As SqliteIndex\n'
        '    item.flags = 0\n'
        '    c2fbSetIndexFlags(@item, 15)\n'
        '    Return c2fbGetIndexFlags(@item)\n'
        'End Function\n'
        'Function c2fbFBProbeColumnFlags CDecl Alias '
        '"c2fbFBProbeColumnFlags"() As Long\n'
        '    Dim item As SqliteColumn\n'
        '    item.flags = 0\n'
        '    c2fbSetColumnFlags(@item, &HA5)\n'
        '    Return c2fbGetColumnFlags(@item)\n'
        'End Function\n'
        'Function c2fbFBProbeWhereInfoFlags CDecl Alias '
        '"c2fbFBProbeWhereInfoFlags"() As Long\n'
        '    Dim item As SqliteWhereInfo\n'
        '    item.flags = 0\n'
        '    c2fbSetWhereInfoFlags(@item, &H2D)\n'
        '    Return c2fbGetWhereInfoFlags(@item)\n'
        'End Function\n'
        'Function c2fbFBProbeDbInitBits CDecl Alias '
        '"c2fbFBProbeDbInitBits"() As Long\n'
        '    Dim item As SqliteDbInitInfo\n'
        '    item.flags = 0\n'
        '    c2fbSetDbInitBits(@item, &HF)\n'
        '    Return c2fbGetDbInitBits(@item)\n'
        'End Function\n'
    )
    reference = ctypes.CDLL(str(reference_path))
    for function_name in (
        "c2fbReferenceSrcItemFlags", "c2fbReferenceSrcItemPostIncrement",
        "c2fbReferenceExprListFlags",
    ):
        reference_function = getattr(reference, function_name)
        reference_function.restype = ctypes.c_int32
    reference.c2fbReferenceDbInitBits.restype = ctypes.c_int32
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-d", "SQLITE_THREADSAFE=1", "-i",
                           str(fb_directory), "-dll", str(wrapper), "-x",
                           str(converted_path)], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        for function_name in (
            "c2fbFBProbeSrcItemFlags", "c2fbFBProbeSrcItemPostIncrement",
            "c2fbFBProbeExprListFlags", "c2fbFBProbeIndexFlags",
            "c2fbFBProbeColumnFlags", "c2fbFBProbeWhereInfoFlags",
            "c2fbFBProbeDbInitBits",
        ):
            getattr(converted, function_name).restype = ctypes.c_int32
        assert reference.c2fbReferenceSrcItemFlags() == \
            converted.c2fbFBProbeSrcItemFlags() == 63
        assert reference.c2fbReferenceSrcItemPostIncrement() == \
            converted.c2fbFBProbeSrcItemPostIncrement() == 125
        assert reference.c2fbReferenceExprListFlags() == \
            converted.c2fbFBProbeExprListFlags() == 251
        assert reference.c2fbReferenceIndexFlags() == \
            converted.c2fbFBProbeIndexFlags() == 15
        assert reference.c2fbReferenceColumnFlags() == \
            converted.c2fbFBProbeColumnFlags() == 0xA5
        assert reference.c2fbReferenceWhereInfoFlags() == \
            converted.c2fbFBProbeWhereInfoFlags() == 0x2D
        assert reference.c2fbReferenceDbInitBits() == \
            converted.c2fbFBProbeDbInitBits() == 0xF


def check_sqlite_body_flexible_pointer_array_offset(converter, fbc, cc, work, fb_directory):
    # SQLite stores a C flexible pointer array in a one-element BASIC placeholder.
    source_directory = work / "sqlite-body-flexible-pointer-array-offset"
    source_directory.mkdir()
    source = source_directory / "hidden_offset.c"
    source.write_text(
        "typedef struct sqlite3_value sqlite3_value;\n"
        "typedef struct CollSeq { int value; } CollSeq;\n"
        "typedef struct KeyInfo {\n"
        "    unsigned int nRef; unsigned char enc;\n"
        "    unsigned short nKeyField; unsigned short nAllField;\n"
        "    void *db; unsigned char *aSortFlags; CollSeq *aColl[];\n"
        "} KeyInfo;\n"
        "typedef struct sqlite3_index_constraint {\n"
        "    int iColumn; unsigned char op; unsigned char usable; int iTermOffset;\n"
        "} sqlite3_index_constraint;\n"
        "typedef struct sqlite3_index_orderby {\n"
        "    int iColumn; unsigned char desc;\n"
        "} sqlite3_index_orderby;\n"
        "typedef struct sqlite3_index_constraint_usage {\n"
        "    int argvIndex; unsigned char omit;\n"
        "} sqlite3_index_constraint_usage;\n"
        "typedef struct sqlite3_index_info {\n"
        "    int nConstraint; sqlite3_index_constraint *aConstraint;\n"
        "    int nOrderBy; sqlite3_index_orderby *aOrderBy;\n"
        "    sqlite3_index_constraint_usage *aConstraintUsage; int idxNum;\n"
        "    char *idxStr; int needToFreeIdxStr; int orderByConsumed;\n"
        "    double estimatedCost; long long estimatedRows; int idxFlags;\n"
        "    unsigned long long colUsed;\n"
        "} sqlite3_index_info;\n"
        "typedef struct HiddenIndexInfo {\n"
        "    void *pWC; void *pParse; int eDistinct;\n"
        "    unsigned int mIn; unsigned int mHandleIn;\n"
        "    sqlite3_value *aRhs[];\n"
        "} HiddenIndexInfo;\n"
        "long c2fbHiddenIndexOffset(void) {\n"
        "    return __builtin_offsetof(HiddenIndexInfo, aRhs);\n"
        "}\n"
        "long c2fbVtabAllocationSize(int nTerm, int nOrderBy) {\n"
        "    sqlite3_index_info *pIdxInfo;\n"
        "    sqlite3_index_constraint *pIdxCons;\n"
        "    sqlite3_index_constraint_usage *pUsage;\n"
        "    sqlite3_index_orderby *pIdxOrderBy;\n"
        "    return sizeof(*pIdxInfo)\n"
        "        + (sizeof(*pIdxCons) + sizeof(*pUsage))*nTerm\n"
        "        + sizeof(*pIdxOrderBy)*nOrderBy\n"
        "        + __builtin_offsetof(HiddenIndexInfo, aRhs)\n"
        "        + nTerm*sizeof(sqlite3_value*);\n"
        "}\n"
        "long c2fbKeyInfoAllocationOffset(int nExtra) {\n"
        "    return __builtin_offsetof(KeyInfo, aColl) + "
        "(0)*sizeof(CollSeq*) + nExtra;\n"
        "}\n"
        "void *c2fbKeyInfoAllocator(void *db, unsigned long size) {\n"
        "    if (size == 0) return 0;\n"
        "    return db;\n"
        "}\n"
        "int c2fbKeyInfoAllocationProbe(int nExtra) {\n"
        "    void *p;\n"
        "    p = c2fbKeyInfoAllocator((void*)1, "
        "(__builtin_offsetof(KeyInfo, aColl) + "
        "(0)*sizeof(CollSeq*)) + nExtra);\n"
        "    return p != 0;\n"
        "}\n"
        "KeyInfo *c2fbKeyInfoAllocationResult(int nExtra) {\n"
        "    KeyInfo *p;\n"
        "    p = (KeyInfo*)c2fbKeyInfoAllocator((void*)1, "
        "(__builtin_offsetof(KeyInfo, aColl) + "
        "(0)*sizeof(CollSeq*)) + nExtra);\n"
        "    return p;\n"
        "}\n"
    )
    (source_directory / "sqlite3_api_declarations.bi").write_text("")
    (source_directory / "sqlite3_internal_api_declarations.bi").write_text("")
    (source_directory / "sqlite3_types.bi").write_text(
        (fb_directory / "sqlite3_types.bi").read_text()
    )
    (source_directory / "sqlite3_vtab_types.bi").write_text(
        '#include once "sqlite3_types.bi"\n'
        "Type SqliteIndexConstraint\n"
        "    iColumn As SQLITE_C_INT\n"
        "    op As UByte\n"
        "    usable As UByte\n"
        "    iTermOffset As SQLITE_C_INT\n"
        "End Type\n"
        "Type SqliteIndexOrderBy\n"
        "    iColumn As SQLITE_C_INT\n"
        "    desc As UByte\n"
        "End Type\n"
        "Type SqliteIndexConstraintUsage\n"
        "    argvIndex As SQLITE_C_INT\n"
        "    omit As UByte\n"
        "    padding(0 To 2) As UByte\n"
        "End Type\n"
        "Type SqliteIndexInfo\n"
        "    nConstraint As SQLITE_C_INT\n"
        "    aConstraint As SqliteIndexConstraint Ptr\n"
        "    nOrderBy As SQLITE_C_INT\n"
        "    aOrderBy As SqliteIndexOrderBy Ptr\n"
        "    aConstraintUsage As SqliteIndexConstraintUsage Ptr\n"
        "    idxNum As SQLITE_C_INT\n"
        "    idxStr As ZString Ptr\n"
        "    needToFreeIdxStr As SQLITE_C_INT\n"
        "    orderByConsumed As SQLITE_C_INT\n"
        "    estimatedCost As Double\n"
        "    estimatedRows As sqlite3_int64\n"
        "    idxFlags As SQLITE_C_INT\n"
        "    colUsed As sqlite3_uint64\n"
        "End Type\n"
        "Type SqliteHiddenIndexInfo\n"
        "    pWC As Any Ptr\n"
        "    pParse As Any Ptr\n"
        "    eDistinct As SQLITE_C_INT\n"
        "    mIn As u32\n"
        "    mHandleIn As u32\n"
        "    aRhs(0 To 0) As Any Ptr\n"
        "End Type\n"
        "Type sqlite3CollSeq\n"
        "    value As SQLITE_C_INT\n"
        "End Type\n"
        "Type sqlite3VdbeKeyInfoPrefix\n"
        "    nRef As u32\n"
        "    enc As u8\n"
        "    nKeyField As UShort\n"
        "    nAllField As UShort\n"
        "    db As Any Ptr\n"
        "    aSortFlags As UByte Ptr\n"
        "    aColl(0 To 0) As sqlite3CollSeq Ptr\n"
        "End Type\n"
    )
    for include_name in (
        "sqlite3_constants.bi", "sqlite3_db_types.bi",
        "sqlite3_parser_types.bi", "sqlite3_expr_types.bi",
        "sqlite3_vdbe_mem_types.bi", "sqlite3_vdbe_core.bi",
        "sqlite3_hash_types.bi", "sqlite3_pager.bi", "sqlite3_btree.bi",
    ):
        (source_directory / include_name).write_text("")

    candidate = source_directory / "hidden_offset_candidates.bas"
    summary = run([
        converter, "translate-simple", str(source), str(candidate),
        str(source_directory), "1", "1",
    ])
    assert "translated 6 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "OffsetOf(SqliteHiddenIndexInfo, aRhs(0))" in generated, generated
    assert "SizeOf(SqliteIndexConstraintUsage)" in generated, generated
    assert "OffsetOf(sqlite3VdbeKeyInfoPrefix, aColl(0))" \
        in generated, generated
    assert "As sqlite3VdbeKeyInfoPrefix Ptr" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "sqlite3_vtab_types.bi"\n'
        '#include once "hidden_offset_candidates.bas"\n'
    )
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), "-x", str(converted_path)],
        cwd=source_directory)

    reference_path = source_directory / "reference.so"
    run(cc + ["-shared", "-fPIC", str(source), "-o", str(reference_path)],
        cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbHiddenIndexOffset.argtypes = []
        library.c2fbHiddenIndexOffset.restype = ctypes.c_long
        library.c2fbVtabAllocationSize.argtypes = [ctypes.c_int, ctypes.c_int]
        library.c2fbVtabAllocationSize.restype = ctypes.c_long
        library.c2fbKeyInfoAllocationOffset.argtypes = [ctypes.c_int]
        library.c2fbKeyInfoAllocationOffset.restype = ctypes.c_long
        library.c2fbKeyInfoAllocationProbe.argtypes = [ctypes.c_int]
        library.c2fbKeyInfoAllocationProbe.restype = ctypes.c_int
        library.c2fbKeyInfoAllocationResult.argtypes = [ctypes.c_int]
        library.c2fbKeyInfoAllocationResult.restype = ctypes.c_void_p
    assert reference.c2fbHiddenIndexOffset() == converted.c2fbHiddenIndexOffset()
    for term_count, order_count in ((0, 0), (1, 0), (3, 2), (17, 5)):
        assert reference.c2fbVtabAllocationSize(term_count, order_count) == \
            converted.c2fbVtabAllocationSize(term_count, order_count)
    for extra in (0, 1, 3, 19, 255):
        assert reference.c2fbKeyInfoAllocationOffset(extra) == \
            converted.c2fbKeyInfoAllocationOffset(extra)
        assert reference.c2fbKeyInfoAllocationProbe(extra) == \
            converted.c2fbKeyInfoAllocationProbe(extra)
        assert reference.c2fbKeyInfoAllocationResult(extra) == \
            converted.c2fbKeyInfoAllocationResult(extra)


def check_sqlite_fts5_index_pointer_subscripts(converter, fbc, cc, repository, work):
    # Unknown source-member type metadata must not produce an empty CPtr type.
    source_directory = work / "sqlite-fts5-index-pointer-subscripts"
    source_directory.mkdir()
    source = repository / "ext/fts5/fts5_index.c"
    candidate = source_directory / "fts5_index_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    include_directories = (
        repository,
        repository / "src",
        repository / "ext/fts5",
    )
    command = [
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        "--include-header-types",
        "--header-compiler-option=-DSQLITE_ENABLE_FTS5",
        "--body-compiler-option=-DSQLITE_ENABLE_FTS5",
        "--header-compiler-option=-DNDEBUG",
        "--body-compiler-option=-DNDEBUG",
        "--body-option=--keep-unresolved=1",
    ]
    for include_directory in include_directories:
        command.append(f"--header-compiler-option=-I{include_directory}")
        command.append(f"--body-compiler-option=-I{include_directory}")
    summary = run(command, cwd=source_directory)
    generated = candidate.read_text()
    assert "CPtr(," not in generated, generated
    assert "translated " in summary, summary

    candidate_object = source_directory / "fts5_index_candidates.o"
    run(fbc + [
        "-mt", "-c", "-d", "SQLITE_ENABLE_FTS5", "-i",
        str(source_directory), str(candidate), "-o", str(candidate_object),
    ], cwd=source_directory)


def check_sqlite_body_fallback_declaration_selection(converter, fbc, work):
    root = work / "sqlite-body-fallback-declaration-selection"
    source_directory = root / "c-source"
    fb_source_directory = root / "fb-source"
    output_directory = root / "candidate-output"
    for directory in (source_directory, fb_source_directory, output_directory):
        directory.mkdir(parents=True)

    (fb_source_directory / "sqlite3_types.bi").write_text(
        "Type SQLITE_C_INT As Long\n"
    )
    for file_name in (
        "sqlite3_constants.bi", "sqlite3_db_types.bi",
        "sqlite3_parser_token.bi", "sqlite3_parser_types.bi",
        "sqlite3_expr_types.bi", "sqlite3_vdbe_mem_types.bi",
        "sqlite3_vdbe_core.bi", "sqlite3_hash_types.bi",
        "sqlite3_pager.bi", "sqlite3_btree.bi",
        "sqlite3_api_declarations.bi",
    ):
        (fb_source_directory / file_name).write_text("")
    (fb_source_directory / "sqlite3_internal_api_declarations.bi").write_text(
        'Declare Function c2fb_internal_fallback CDecl '
        'Alias "c2fb_internal_fallback" '
        "(ByVal arg0 As SQLITE_C_INT) As SQLITE_C_INT\n"
        'Declare Function c2fb_included_helper CDecl '
        'Alias "c2fb_included_helper" '
        "(ByVal arg0 As SQLITE_C_INT) As SQLITE_C_INT\n"
        'Declare Function c2fb_unused_api CDecl Alias "c2fb_unused_api" '
        "(ByVal arg0 As SQLITE_C_INT) As SQLITE_C_INT\n"
    )
    (fb_source_directory / "sqlite3_helper.bi").write_text(
        'Declare Function c2fb_included_helper CDecl '
        'Alias "c2fb_included_helper" '
        "(ByVal arg0 As SQLITE_C_INT) As SQLITE_C_INT\n"
    )

    source = source_directory / "fallback.c"
    source.write_text(
        "int c2fb_internal_fallback(int value);\n"
        "int c2fb_included_helper(int value);\n"
        "int c2fb_unused_api(int value);\n"
        "int c2fb_api_fallback_probe(int value) {\n"
        "    return c2fb_internal_fallback(value) + "
        "c2fb_included_helper(value);\n"
        "}\n"
    )
    candidate = output_directory / "fallback_candidates.bas"
    summary = run([
        converter, "translate-simple", str(source), str(candidate),
        str(fb_source_directory),
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert '#include once "sqlite3_helper.bi"' in generated, generated
    assert generated.count(
        'Declare Function c2fb_internal_fallback CDecl '
        'Alias "c2fb_internal_fallback"'
    ) == 1, generated
    assert 'Declare Function c2fb_included_helper CDecl ' not in generated, generated
    assert 'Declare Function c2fb_unused_api CDecl ' not in generated, generated

    run(fbc + [
        "-w", "all", "-d", "SQLITE_THREADSAFE=1", "-i",
        str(fb_source_directory), "-c", str(candidate), "-o",
        str(output_directory / "fallback_candidates.o"),
    ], cwd=output_directory)


def check_generic_body_existing_pointer_call_signature(converter, fbc, cc, work):
    # Calls to an existing FreeBASIC API use its opaque pointer ABI signature.
    source_directory = work / "generic-body-existing-pointer-call-signature"
    source_directory.mkdir()
    header = source_directory / "opaque.h"
    header.write_text(
        "typedef struct Node { int value; } Node;\n"
        "int c2fbOpaqueConsume(Node *node);\n"
        "int c2fbCallOpaqueConsume(Node *node);\n"
    )
    source = source_directory / "caller.c"
    source.write_text(
        '#include "opaque.h"\n'
        "int c2fbCallOpaqueConsume(Node *node) {\n"
        "    return c2fbOpaqueConsume(node) + 1;\n"
        "}\n"
    )
    binding = source_directory / "opaque.bi"
    binding.write_text(
        "Type c2fb_Node\n"
        "    value As Long\n"
        "End Type\n"
        'Declare Function c2fbOpaqueConsume CDecl Alias "c2fbOpaqueConsume" '
        "(ByVal node As Any Ptr) As Long\n"
    )
    candidate = source_directory / "caller_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        "cc", f"-I{source_directory}",
        f"--fb-source-directory={source_directory}",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "c2fbOpaqueConsume(CPtr(Any Ptr, arg0))" in generated, generated

    support = source_directory / "support.c"
    support.write_text(
        '#include "opaque.h"\n'
        "int c2fbOpaqueConsume(Node *node) { return node->value * 2; }\n"
    )
    support_object = source_directory / "support.o"
    run(cc + ["-c", str(support), "-o", str(support_object)],
        cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "opaque.bi"\n'
        f'#include once "{candidate.name}"\n'
    )
    output = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), str(support_object),
               "-x", str(output)], cwd=source_directory)

    reference_path = source_directory / "reference.so"
    run(cc + ["-shared", "-fPIC", str(source), str(support),
              "-o", str(reference_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(output))
    class Node(ctypes.Structure):
        _fields_ = [("value", ctypes.c_int)]
    for library in (reference, converted):
        library.c2fbCallOpaqueConsume.argtypes = [ctypes.POINTER(Node)]
        library.c2fbCallOpaqueConsume.restype = ctypes.c_int
    for value in (-11, -1, 0, 8, 27):
        node = Node(value)
        assert reference.c2fbCallOpaqueConsume(ctypes.byref(node)) == \
            converted.c2fbCallOpaqueConsume(ctypes.byref(node)) == \
            (2 * value) + 1


def check_generic_body_object_pointer_conversion(converter, fbc, cc, work):
    # C permits converting an object pointer from void* to a record pointer.
    source_directory = work / "generic-body-object-pointer-conversion"
    source_directory.mkdir()
    source = source_directory / "pointer.c"
    source.write_text(
        "struct c2fbPointerNode { int value; };\n"
        "int c2fbReadPointer(const void *source) {\n"
        "    struct c2fbPointerNode const *node = source;\n"
        "    return node->value;\n"
        "}\n"
    )
    candidate = source_directory / "pointer_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        "cc", f"-I{source_directory}",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert re.search(r"CPtr\(Const c2fb_source_record_\d+ Ptr, arg0\)", generated), generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-shared", "-fPIC", str(source), "-o", str(reference_path)],
        cwd=source_directory)
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(candidate), "-x", str(converted_path)],
        cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbReadPointer.argtypes = [ctypes.c_void_p]
        library.c2fbReadPointer.restype = ctypes.c_int
    class Node(ctypes.Structure):
        _fields_ = [("value", ctypes.c_int)]
    for value in (-23, 0, 17):
        node = Node(value)
        pointer = ctypes.byref(node)
        assert reference.c2fbReadPointer(pointer) == \
            converted.c2fbReadPointer(pointer) == value


def check_generic_body_callback_pointer_record(converter, fbc, cc, work):
    # A supported function-pointer field must keep following record offsets.
    source_directory = work / "generic-body-callback-pointer-record"
    source_directory.mkdir()
    source = source_directory / "callback_record.c"
    source.write_text(
        "struct C2fbCallbackRecord { void (*callback)(void); int value; };\n"
        "int c2fbReadCallbackRecord(const struct C2fbCallbackRecord *record) {\n"
        "    if (record->callback) return record->value + 17;\n"
        "    return record->value;\n"
        "}\n"
    )
    candidate = source_directory / "callback_record_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        cc[0], *cc[1:],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    record = re.search(
        r"(?ms)^Private Type (c2fb_source_record_\d+)\s*\n(.*?)^End Type$",
        generated,
    )
    assert record is not None, generated
    assert re.search(
        r"^\s*callback As c2fb_callback_\d+\s*$", record.group(2), re.M
    ), generated
    assert re.search(
        r"^\s*value As c2fb_c_int\s*$", record.group(2), re.M
    ), generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-shared", "-fPIC", str(source), "-o", str(reference_path)],
        cwd=source_directory)
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(candidate), "-x", str(converted_path)],
        cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))

    class CallbackRecord(ctypes.Structure):
        _fields_ = [("callback", ctypes.c_void_p), ("value", ctypes.c_int)]

    for library in (reference, converted):
        library.c2fbReadCallbackRecord.argtypes = [ctypes.POINTER(CallbackRecord)]
        library.c2fbReadCallbackRecord.restype = ctypes.c_int

    callback = ctypes.CFUNCTYPE(None)(lambda: None)
    callback_address = ctypes.cast(callback, ctypes.c_void_p).value
    for callback_pointer, value, expected in (
        (None, 23, 23), (callback_address, -4, 13),
    ):
        record_value = CallbackRecord(callback_pointer, value)
        reference_value = reference.c2fbReadCallbackRecord(
            ctypes.byref(record_value))
        converted_value = converted.c2fbReadCallbackRecord(
            ctypes.byref(record_value))
        assert reference_value == converted_value == expected, (
            callback_pointer, value, reference_value, converted_value
        )


