    source.write_text(
        "#include <string.h>\n"
        "int c2fbLengthPlusOne(const char *text) {\n"
        "    return (int)strlen(text) + 1;\n"
        "}\n"
    )
    (fb_source_directory / "sqlite3_runtime.bi").write_text(
        'Declare Function sqlite3SystemStrlen CDecl Alias "strlen" '
        "(ByVal z As Const ZString Ptr) As CULong\n"
    )

    candidate = source_directory / "caller_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        *cc, "--fb-source-directory=" + str(fb_source_directory),
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert '#include once "sqlite3_runtime.bi"' in generated, generated
    assert "sqlite3SystemStrlen(arg0)" in generated, generated
    assert "c2fb_crt_strlen" not in generated, generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-shared", "-fPIC", str(source), "-o", str(reference_path)])
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", "-i", str(fb_source_directory),
               str(candidate), "-x", str(converted_path)])
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbLengthPlusOne.argtypes = [ctypes.c_char_p]
        library.c2fbLengthPlusOne.restype = ctypes.c_int
    for value in (b"", b"abc", b"FreeBasic", bytes((0xC2, 0xA3))):
        assert reference.c2fbLengthPlusOne(value) == \
            converted.c2fbLengthPlusOne(value), value


