def check_generic_body_prefers_prototype_header(converter, fbc, work):
    # A public prototype keeps platform implementation code out of consumers.
    source_directory = work / "generic-body-prototype-header"
    source_directory.mkdir()
    fb_source_directory = source_directory / "fb-source"
    fb_source_directory.mkdir()
    source = source_directory / "caller.c"
    source.write_text(
        "extern int c2fbPlatformValue(void);\n"
        "int c2fbCallPlatform(void) { return c2fbPlatformValue(); }\n"
    )
    (fb_source_directory / "runtime_api.bi").write_text(
        'Declare Function c2fbPlatformValue CDecl Alias "c2fbPlatformValue" '
        '() As Long\n'
    )
    (fb_source_directory / "platform_windows.bi").write_text(
        'Function c2fbPlatformValue CDecl Alias "c2fbPlatformValue" '
        '() As Long\n'
        '    Return 7\n'
        'End Function\n'
    )

    candidate = source_directory / "caller_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        "cc", "--fb-source-directory=" + str(fb_source_directory),
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert '#include once "runtime_api.bi"' in generated, generated
    assert '#include once "platform_windows.bi"' not in generated, generated
    run(fbc + ["-w", "all", "-c", str(candidate), "-i",
               str(fb_source_directory), "-o",
               str(source_directory / "caller_candidates.o")],
        cwd=source_directory)


def check_generic_body_emits_callback_types_used_by_records(converter, fbc, cc, work):
    # A generated record can use a callback type without mentioning its alias in code.
    source_directory = work / "generic-body-record-callback-type"
    source_directory.mkdir()
    source = source_directory / "resource.c"
    source.write_text(
        "typedef void (*C2fbDestroyCallback)(void *resource);\n"
        "typedef struct C2fbResource {\n"
        "    void *resource;\n"
        "    C2fbDestroyCallback destroy;\n"
        "    int alive;\n"
        "} C2fbResource;\n"
        "int c2fbResourceAlive(C2fbResource *resource) {\n"
        "    return resource != 0 && resource->alive;\n"
        "}\n"
    )

    candidate = source_directory / "resource_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        *cc,
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    callback_line = next(
        (line for line in generated.splitlines()
         if line.startswith("Type c2fb_callback_") and " As Sub CDecl(" in line),
        "",
    )
    assert callback_line, generated
    callback_name = callback_line.split()[1]
    assert f"destroy As {callback_name}" in generated, generated
    run(fbc + ["-w", "all", "-c", str(candidate), "-o",
               str(source_directory / "resource_candidates.o")],
        cwd=source_directory)


def check_generic_body_private_cross_module_dependency(converter, fbc, cc, work):
    # A private port helper cannot satisfy a call from a separate candidate module.
    source_directory = work / "generic-body-private-cross-module-dependency"
    source_directory.mkdir()
    bindings = source_directory / "bindings"
    bindings.mkdir()
    (bindings / "private_helper.bas").write_text(
        'Private Function c2fbExistingPrivate CDecl Alias "c2fbExistingPrivate" '
        "(ByVal value As Long) As Long\n"
        "    Return value + 1\n"
        "End Function\n"
    )
    source = source_directory / "caller.c"
    source.write_text(
        "int c2fbExistingPrivate(int value);\n"
        "int c2fbNewCaller(int value) {\n"
        "    return c2fbExistingPrivate(value) * 2;\n"
        "}\n"
    )
    candidate = source_directory / "private_helper_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        "cc", f"--fb-source-directory={bindings}",
    ])
    assert "translated 0 simple functions; skipped 1" in summary, summary
    generated = candidate.read_text()
    assert "c2fb skipped c2fbNewCaller: requires private FreeBASIC helper " \
        "c2fbExistingPrivate from another module" in generated, generated
    run(fbc + ["-w", "all", "-c", str(candidate), "-o",
               str(source_directory / "private-helper.o")], cwd=source_directory)

    local_candidate = source_directory / "local_helper_candidates.bas"
    local_summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(local_candidate), "cc",
    ])
    assert "translated 1 simple functions; skipped 0" in local_summary, local_summary
    support = source_directory / "support.c"
    support.write_text(
        "int c2fbExistingPrivate(int value) { return value + 1; }\n"
    )
    support_object = source_directory / "support.o"
    run(cc + ["-c", str(support), "-o", str(support_object)],
        cwd=source_directory)
    local_wrapper = source_directory / "check.bas"
    local_wrapper.write_text('#include once "local_helper_candidates.bas"\n')
    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source), str(support),
              "-o", str(reference_path)], cwd=source_directory)
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(local_wrapper), str(support_object), "-x",
               str(converted_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbNewCaller.argtypes = [ctypes.c_int]
        library.c2fbNewCaller.restype = ctypes.c_int
    for value in (-5, 0, 7, 31):
        assert reference.c2fbNewCaller(value) == \
            converted.c2fbNewCaller(value) == (value + 1) * 2

    string_source = source_directory / "private_helper_in_string.c"
    string_source.write_text(
        "int c2fbPrivateHelperInString(int value) {\n"
        '    const char *message = "c2fbExistingPrivate( ProcPtr(c2fbExistingPrivate)";\n'
        "    return value + 1;\n"
        "}\n"
    )
    string_candidate = source_directory / "private_helper_in_string_candidates.bas"
    string_summary = run([
        converter, "translate-simple-generic-c", str(string_source),
        str(string_candidate), "cc",
        f"--fb-source-directory={bindings}",
    ])
    assert "translated 1 simple functions; skipped 0" in string_summary, string_summary
    assert "Function c2fbPrivateHelperInString" in string_candidate.read_text()
    assert "requires private FreeBASIC helper c2fbExistingPrivate " \
        "from another module" not in string_candidate.read_text()

    # C identifiers remain case-sensitive even when the FreeBASIC aliases are not.
    case_source = source_directory / "private_helper_case_difference.c"
    case_source.write_text(
        "int C2fbExistingPrivate(int value);\n"
        "int c2fbPrivateHelperCaseDifference(int value) {\n"
        "    return C2fbExistingPrivate(value) + 1;\n"
        "}\n"
    )
    case_candidate = source_directory / "private_helper_case_difference_candidates.bas"
    case_summary = run([
        converter, "translate-simple-generic-c", str(case_source),
        str(case_candidate), "cc",
        f"--fb-source-directory={bindings}",
    ])
    assert "translated 1 simple functions; skipped 0" in case_summary, case_summary
    case_generated = case_candidate.read_text()
    assert "Function c2fbPrivateHelperCaseDifference" in case_generated
    assert "requires private FreeBASIC helper c2fbExistingPrivate " \
        "from another module" not in case_generated
    run(fbc + ["-w", "all", "-c", str(case_candidate), "-o",
               str(source_directory / "private-helper-case-difference.o")],
        cwd=source_directory)

    local_dependency_source = source_directory / "unconverted_local_dependency.c"
    local_dependency_source.write_text(
        "static int c2fbUnsupportedLocal(int value) {\n"
        '    __asm__("nop");\n'
        "    return value;\n"
        "}\n"
        "int c2fbCallsUnsupportedLocal(int value) {\n"
        "    return c2fbUnsupportedLocal(value);\n"
        "}\n"
    )
    local_dependency_candidate = source_directory / "unconverted_local_candidates.bas"
    local_dependency_summary = run([
        converter, "translate-simple-generic-c", str(local_dependency_source),
        str(local_dependency_candidate), "cc",
    ])
    assert "translated 0 simple functions; skipped 2" \
        in local_dependency_summary, local_dependency_summary
    local_dependency_generated = local_dependency_candidate.read_text()
    assert "c2fb skipped c2fbCallsUnsupportedLocal: requires unconverted C function " \
        "c2fbUnsupportedLocal" in local_dependency_generated, local_dependency_generated
    assert "c2fb body diagnostic [unsupported-assignment-expression]" \
        in local_dependency_generated, local_dependency_generated
    run(fbc + ["-w", "all", "-c", str(local_dependency_candidate), "-o",
               str(source_directory / "unconverted-local.o")], cwd=source_directory)


def check_generic_body_specific_signature_overrides_sqlite_fallback(
    converter, fbc, work
):
    # The generated SQLite API table uses Any Ptr where a module has a typed signature.
    source_directory = work / "generic-body-specific-signature-overrides-fallback"
    source_directory.mkdir()
    bindings = source_directory / "bindings"
    bindings.mkdir()
    (bindings / "sqlite3_walker.bi").write_text(
        '#include once "zz_expr_types.bi"\n'
        "Type SqliteWalker\n"
        "    value As Long\n"
        "End Type\n"
        'Declare Function sqlite3WalkExprList CDecl Alias "sqlite3WalkExprList" '\
        "(ByVal pWalker As SqliteWalker Ptr, "
        "ByVal pList As SqliteExprList Ptr) As Long\n"
    )
    (bindings / "sqlite3_internal_api_declarations.bi").write_text(
        'Declare Function sqlite3ExprIdToTrueFalse CDecl '
        'Alias "sqlite3ExprIdToTrueFalse" '
        '(ByVal arg0 As Any Ptr) As CLong\n'
        'Declare Function sqlite3WalkExprList CDecl Alias "sqlite3WalkExprList" '
        "(ByVal arg0 As Any Ptr, ByVal arg1 As Any Ptr) As Long\n"
    )
    (bindings / "zz_expr_types.bi").write_text(
        "Type SqliteExprListRecord\n"
        "    count As Long\n"
        "End Type\n"
        "Type SqliteExprList As SqliteExprListRecord\n"
        'Declare Function sqlite3ExprIdToTrueFalse CDecl '
        'Alias "sqlite3ExprIdToTrueFalse" '
        '(ByVal pExpr As CLong Ptr) As CLong\n'
    )
    (bindings / "sqlite3_walker.bas").write_text(
        '#include once "sqlite3_walker.bi"\n'
        'Function sqlite3WalkExprList CDecl Alias "sqlite3WalkExprList" '\
        "(ByVal pWalker As SqliteWalker Ptr, "
        "ByVal pList As SqliteExprListRecord Ptr) As Long Export\n"
        "    Return 0\n"
        "End Function\n"
    )
    source = source_directory / "expr.c"
    source.write_text(
        "long sqlite3ExprIdToTrueFalse(long *pExpr);\n"
        "long c2fbExprCaller(long *pExpr) {\n"
        "    return sqlite3ExprIdToTrueFalse(pExpr);\n"
        "}\n"
        "typedef struct Walker { int value; } Walker;\n"
        "typedef struct ExprList { int count; } ExprList;\n"
        "int sqlite3WalkExprList(Walker *walker, ExprList *list);\n"
        "int c2fbListCaller(Walker *walker, ExprList *list) {\n"
        "    return sqlite3WalkExprList(walker, list);\n"
        "}\n"
    )
    candidate = source_directory / "expr_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate),
        "cc", f"--fb-source-directory={bindings}",
        "--type-map=Walker=SqliteWalker", "--type-map=ExprList=SqliteExprList",
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert '#include once "sqlite3_walker.bi"' in generated, generated
    assert "requires private FreeBASIC helper sqlite3ExprIdToTrueFalse" \
        not in generated, generated
    assert "requires private FreeBASIC helper sqlite3WalkExprList" \
        not in generated, generated
    run(fbc + ["-w", "all", "-i", str(bindings), "-c", str(candidate),
               "-o", str(source_directory / "expr-candidate.o")],
        cwd=source_directory)


