def check_generic_body_source_unit_rejects_incomplete_record_layout(
    converter, fbc, cc, work
):
    # Header and body passes must agree when field attributes hide a layout.
    source_directory = work / "generic-body-source-unit-incomplete-record"
    source_directory.mkdir()
    source = source_directory / "packed_field.c"
    source.write_text(
        "typedef struct PackedField {\n"
        "    unsigned char tag;\n"
        "    unsigned int value __attribute__((packed, aligned(1)));\n"
        "} PackedField;\n"
        "typedef union C2fbIncompleteUnion {\n"
        "    long double wide;\n"
        "    unsigned char bytes[64];\n"
        "} C2fbIncompleteUnion;\n"
        "static const PackedField *packed_field_cursor;\n"
        "unsigned int read_packed_field(const PackedField *record) {\n"
        "    return record->value;\n"
        "}\n"
        "void restore_packed_field(void *record) {\n"
        "    packed_field_cursor = (const PackedField *)record;\n"
        "}\n"
        "int c2fbUseIncompleteUnion(void) {\n"
        "    C2fbIncompleteUnion value;\n"
        "    return value.bytes[0];\n"
        "}\n"
        "int c2fbUseIncompleteUnionPointer(C2fbIncompleteUnion *value) {\n"
        "    return value != 0;\n"
        "}\n"
    )
    candidate = source_directory / "packed_field_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    generated = candidate.read_text()
    assert "translated 2 simple functions; skipped 2" in summary, summary
    assert "unmapped-record-field" in generated, generated
    assert "incomplete-local-record-layout" in generated, generated
    assert "c2fb_source_record_" not in generated, generated
    assert not re.search(r"^Function read_packed_field\b", generated, re.M), \
        generated
    assert not re.search(r"^Function c2fbUseIncompleteUnion\b", generated, re.M), \
        generated
    assert "Sub restore_packed_field" in generated, generated
    assert "Function c2fbUseIncompleteUnionPointer" in generated, generated
    assert "CPtr(Const _c2fb_record_c2fb_PackedField Ptr" not in generated, \
        generated
    run(fbc + ["-w", "all", "-c", str(candidate), "-o",
               str(source_directory / "packed-field.o")], cwd=source_directory)


