def check_fbfrog_boolean_redeclared_in_exclusive_paths(converter, fbc, work):
    source_directory = work / "fbfrog-branch-boolean-declarations"
    source_directory.mkdir()
    (source_directory / "branch.h").write_text(
        "#if C2FB_API_VERSION == 1\n"
        "#ifdef C2FB_OPTIONAL\n"
        "extern int versionOneOptional;\n"
        "#else\n"
        "extern int versionOneDefault;\n"
        "#endif\n"
        "#else\n"
        "#ifdef C2FB_OPTIONAL\n"
        "extern int versionTwoOptional;\n"
        "#else\n"
        "extern int versionTwoDefault;\n"
        "#endif\n"
        "#endif\n"
    )
    script = source_directory / "branches.fbfrog"
    script.write_text(
        "-declareversions C2FB_API_VERSION 1 2\n"
        "-selectversion\n"
        "-case 1\n"
        "-declarebool C2FB_OPTIONAL\n"
        "-case 2\n"
        "-declarebool C2FB_OPTIONAL\n"
        "-endselect\n"
    )
    manifest = source_directory / "branches.json"
    manifest.write_text(json.dumps({
        "input": "branch.h",
        "output_directory": "bindings",
        "combined_binding": "api.bi",
        "converter": converter,
        "fbfrog_version_script": {
            "path": "branches.fbfrog",
            "name_prefix": "branch-api",
            "compiler": "cc",
            "targets": [],
        },
    }))
    matrix_tool = Path(__file__).resolve().parents[1] / "c2fb_target_matrix.py"
    run([sys.executable, str(matrix_tool), str(manifest)], cwd=source_directory)
    binding_directory = source_directory / "bindings"
    assert len(list(binding_directory.glob("branch-api-*.bi"))) == 4
    expected_profiles = {
        (1, True): "versionOneOptional",
        (1, False): "versionOneDefault",
        (2, True): "versionTwoOptional",
        (2, False): "versionTwoDefault",
    }
    for (version, optional), expected_name in expected_profiles.items():
        suffix = "c2fb_optional-on" if optional else "c2fb_optional-off"
        profile = binding_directory / f"branch-api-{version}-{suffix}.bi"
        generated = profile.read_text()
        assert f"c2fb_{expected_name}" in generated, (profile, generated)
        for other_name in set(expected_profiles.values()) - {expected_name}:
            assert f"c2fb_{other_name}" not in generated, (profile, generated)
        wrapper = source_directory / f"check-{version}-{int(optional)}.bas"
        wrapper.write_text('#include once "bindings/api.bi"\n')
        defines = ["-d", f"C2FB_API_VERSION={version}"]
        if optional:
            defines.extend(["-d", "C2FB_OPTIONAL=1"])
        run(fbc + ["-w", "all", *defines, "-c", str(wrapper), "-o",
                   str(source_directory / f"check-{version}-{int(optional)}.o")],
            cwd=source_directory)


def check_generic_header_module_static_objects(converter, fbc, work):
    # File-scope C statics become module-local shared storage, not C externs.
    source_directory = work / "generic-header-module-static-objects"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    large_values = ", ".join(
        str(3 + index * 2) for index in range(128)
    )
    header.write_text(
        "static int counter;\n"
        "static const int initial = 123;\n"
        "static void *opaque = 0;\n"
        "static int values[3] = {1, 2, 3};\n"
        "static int inferred[] = {4, 5};\n"
        "static int largeValues[128] = {" + large_values + "};\n"
        "typedef struct StaticPoint { int x; int y; } StaticPoint;\n"
        "static StaticPoint points[2] = {{0, 0}, {1, 2}};\n"
        "static StaticPoint partialPoint = {7};\n"
        "typedef struct StaticArray { int coord[2]; } StaticArray;\n"
        "static StaticArray arrays[2] = {{0, 0}, {1, 2}};\n"
        "typedef struct StaticPointerRecord {\n"
        "    int value; const int *pointer; const char *text;\n"
        "} StaticPointerRecord;\n"
        "static StaticPointerRecord pointerRecord = {7, &initial, \"record\"};\n"
        "static StaticPointerRecord zeroPointerRecord = {0};\n"
        "typedef struct StaticCallbackRecord {\n"
        "    const char *name; int (*probe)(void); void (*notify)(void);\n"
        "} StaticCallbackRecord;\n"
        "static const StaticCallbackRecord callbackRecord = {\n"
        "    \"unavailable\", 0, 0\n"
        "};\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "12 module-static objects" in summary, summary
    assert "Dim Shared c2fb_counter As Long" in generated, generated
    assert "Dim Shared c2fb_initial As Const Long = 123" in generated, generated
    assert "Dim Shared c2fb_opaque As Any Ptr = CPtr(Any Ptr, 0)" in generated, generated
    assert "Dim Shared c2fb_values(0 To 2) As Long = {1, 2, 3}" in generated, generated
    assert "Dim Shared c2fb_inferred(0 To 1) As Long = {4, 5}" in generated, generated
    large_array_line = next(
        line for line in generated.splitlines()
        if line.startswith("Dim Shared c2fb_largeValues")
    )
    assert large_array_line.startswith(
        "Dim Shared c2fb_largeValues(0 To 127) As Long = {"
    ), large_array_line
    assert large_array_line.endswith("257}"), large_array_line[-80:]
    assert "Dim Shared c2fb_points(0 To 1) As c2fb_StaticPoint = " \
        "{(0, 0), (1, 2)}" in generated, generated
    assert "Dim Shared c2fb_partialPoint As c2fb_StaticPoint = (7, 0)" \
        in generated, generated
    assert "Dim Shared c2fb_arrays(0 To 1) As c2fb_StaticArray = " \
        "{({0, 0}), ({1, 2})}" in generated, generated
    assert "Dim Shared c2fb_pointerRecord As c2fb_StaticPointerRecord = " \
        "(7, @c2fb_initial, " \
        "CPtr(Const ZString Ptr, StrPtr(!\"record\")))" in generated, generated
    assert "Dim Shared c2fb_zeroPointerRecord As c2fb_StaticPointerRecord\n" \
        in generated, generated
    assert "Dim Shared c2fb_callbackRecord_storage As " \
        "c2fb_StaticCallbackRecord = " \
        '(CPtr(Const ZString Ptr, StrPtr(!"unavailable")), 0, 0)' \
        in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "If c2fb_counter <> 0 Then End 1\n"
        "If c2fb_initial <> 123 Then End 2\n"
        "If c2fb_opaque <> 0 Then End 3\n"
        "If c2fb_values(0) <> 1 OrElse c2fb_values(2) <> 3 Then End 4\n"
        "If c2fb_inferred(1) <> 5 Then End 5\n"
        "If c2fb_largeValues(0) <> 3 OrElse "
        "c2fb_largeValues(73) <> 149 OrElse "
        "c2fb_largeValues(127) <> 257 Then End 9\n"
        "If c2fb_points(1).x <> 1 OrElse c2fb_points(1).y <> 2 Then End 6\n"
        "If c2fb_partialPoint.x <> 7 OrElse c2fb_partialPoint.y <> 0 Then End 7\n"
        "If c2fb_arrays(1).coord(0) <> 1 OrElse "
        "c2fb_arrays(1).coord(1) <> 2 Then End 8\n"
        "If c2fb_pointerRecord.value <> 7 OrElse "
        "c2fb_pointerRecord.pointer <> @c2fb_initial OrElse "
        "c2fb_pointerRecord.text = 0 Then End 10\n"
        "If CPtr(Const Byte Ptr, c2fb_pointerRecord.text)[0] <> Asc(\"r\") Then End 12\n"
        "If c2fb_zeroPointerRecord.value <> 0 OrElse "
        "c2fb_zeroPointerRecord.pointer <> 0 OrElse "
        "c2fb_zeroPointerRecord.text <> 0 Then End 11\n"
        "If c2fb_callbackRecord.probe <> 0 OrElse "
        "c2fb_callbackRecord.notify <> 0 Then End 13\n"
        "If CPtr(Const Byte Ptr, c2fb_callbackRecord.name)[0] <> Asc(\"u\") "
        "Then End 14\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


    callback_header = source_directory / "callback.h"
    callback_header.write_text(
        "extern int callbackTarget(void);\n"
        "static int (*callback)(void) = &callbackTarget;\n"
        "static int (*callbackTable[2])(void) = {&callbackTarget, 0};\n"
    )
    callback_binding = source_directory / "callback.bi"
    run([converter, "generic-header", str(callback_header),
         str(callback_binding), "cc"])
    callback_generated = callback_binding.read_text()
    assert "Dim Shared c2fb_callback As Function CDecl() As Long = " \
        "ProcPtr(c2fb_callbackTarget)" in callback_generated, callback_generated
    assert "Dim Shared c2fb_callbackTable(0 To 1) As Function CDecl() As Long = " \
        "{ProcPtr(c2fb_callbackTarget), CPtr(Function CDecl() As Long, 0)}" \
        in callback_generated, callback_generated
    callback_wrapper = source_directory / "callback-check.bas"
    callback_wrapper.write_text(
        '#include once "callback.bi"\n'
        "Sub checkCallback()\n"
        "    Dim result As Long = c2fb_callback()\n"
        "End Sub\n"
    )
    run(fbc + ["-w", "all", "-c", str(callback_wrapper), "-o",
               str(source_directory / "callback-check.o")],
        cwd=source_directory)


def check_generic_header_supports_thread_local_objects(converter, fbc, work):
    source_directory = work / "generic-header-thread-local-objects"
    source_directory.mkdir()
    header = source_directory / "thread-local.h"
    header.write_text(
        "_Thread_local unsigned int standardTlsCounter;\n"
        "_Thread_local unsigned int standardTlsValues[2];\n"
        "static __thread unsigned int compilerTlsCounter;\n"
        "static unsigned int ordinaryCounter;\n"
        "unsigned int thread_local;\n"
    )
    binding = source_directory / "thread-local.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), "cc",
        "--include-static-objects", "--private-static-objects",
    ])
    generated = binding.read_text()
    assert 'Extern "C"' in generated, generated
    assert 'Thread Local Extern c2fb_standardTlsCounter Alias "standardTlsCounter" As ULong' \
        in generated, generated
    assert 'Thread Local Extern c2fb_standardTlsValues(0 To 1) Alias "standardTlsValues" As ULong' \
        in generated, generated
    assert "Private Thread Local Dim Shared c2fb_compilerTlsCounter As ULong" \
        in generated, generated
    assert "c2fb_ordinaryCounter" in generated, generated
    assert "c2fb_thread_local" in generated, generated
    assert "skipped 0 unsupported declarations" in summary, summary
    header_wrapper = source_directory / "thread-local-check.bas"
    header_wrapper.write_text('#include once "thread-local.bi"\n')
    run(fbc + ["-w", "all", "-c", str(header_wrapper), "-o",
               str(source_directory / "thread-local-check.o")], cwd=source_directory)
    c_definition = source_directory / "thread-local-definition.c"
    c_definition.write_text(
        "_Thread_local unsigned int standardTlsCounter = 7;\n"
        "_Thread_local unsigned int standardTlsValues[2] = {3, 4};\n"
    )
    c_object = source_directory / "thread-local-definition.o"
    c_build = subprocess.run(
        shlex.split("cc") + ["-c", str(c_definition), "-o", str(c_object)],
        cwd=source_directory, capture_output=True, text=True,
    )
    assert c_build.returncode == 0, c_build.stdout + c_build.stderr
    external_wrapper = source_directory / "thread-local-external-check.bas"
    external_wrapper.write_text(
        '#include once "thread-local.bi"\n'
        "If c2fb_standardTlsCounter <> 7 Then End 1\n"
        "c2fb_standardTlsCounter = 11\n"
        "If c2fb_standardTlsValues(0) <> 3 OrElse _\n"
        "   c2fb_standardTlsValues(1) <> 4 Then End 2\n"
        "c2fb_standardTlsValues(1) = 12\n"
        'Print "C2FB external thread-local passed"\n'
    )
    external_executable = source_directory / "thread-local-external-check"
    run(fbc + ["-gen", "gas64", "-mt", str(external_wrapper),
               str(c_object), "-x", str(external_executable)], cwd=source_directory)
    external_result = subprocess.run(
        [str(external_executable)], cwd=source_directory,
        capture_output=True, text=True, timeout=30, check=False,
    )
    assert external_result.returncode == 0 and external_result.stdout.strip() == \
        "C2FB external thread-local passed", external_result.stdout + external_result.stderr

    cpp_header = source_directory / "thread-local.hpp"
    cpp_header.write_text(
        "static thread_local unsigned int cppTlsCounter;\n"
        "thread_local unsigned int externalCppTlsCounter;\n"
        "static unsigned int ordinaryCppCounter;\n"
    )
    cpp_binding = source_directory / "thread-local-cpp.bi"
    cpp_summary = run([
        converter, "generic-header", str(cpp_header), str(cpp_binding), "cc",
        "-x", "c++", "--include-static-objects", "--private-static-objects",
    ])
    cpp_generated = cpp_binding.read_text()
    assert "Private Thread Local Dim Shared c2fb_cppTlsCounter As ULong" \
        in cpp_generated, cpp_generated
    assert "c2fb_ordinaryCppCounter" in cpp_generated, cpp_generated
    assert "external C++ thread-local object needs a C++ linker name" \
        in cpp_generated, cpp_generated
    assert "skipped 1 unsupported declaration" in cpp_summary, cpp_summary

    source = source_directory / "source-unit.c"
    source.write_text(
        "static _Thread_local unsigned int sourceUnitTlsCounter = 7;\n"
        "unsigned int c2fbReadSourceUnitTls(void) {\n"
        "    return sourceUnitTlsCounter;\n"
        "}\n"
    )
    candidate = source_directory / "source-unit-candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    result = subprocess.run(
        [
            sys.executable, str(source_unit_tool), str(source), str(candidate),
            "--converter", str(converter), "--compiler", "cc",
        ],
        cwd=source_directory, capture_output=True, text=True,
    )
    assert result.returncode == 0, result.stdout + result.stderr
    assert "unsupported thread-local C objects" not in result.stdout, result.stdout
    type_context = candidate.with_name("source-unit-candidates_types.bi")
    assert "Private Thread Local Dim Shared c2fb_sourceUnitTlsCounter As ULong = 7" \
        in type_context.read_text(), type_context.read_text()
    run(fbc + ["-mt", "-w", "all", "-c", str(candidate), "-o",
               str(source_directory / "source-unit-candidates.o")], cwd=source_directory)
    procedure = re.search(
        r"^Function\s+([A-Za-z_][A-Za-z_0-9]*)\b",
        candidate.read_text(), re.MULTILINE,
    )
    assert procedure is not None, candidate.read_text()
    wrapper = source_directory / "source-unit-thread-local-check.bas"
    wrapper.write_text(
        '#include once "source-unit-candidates.bas"\n'
        f"If {procedure.group(1)}() <> 7 Then End 1\n"
        'Print "C2FB thread-local source unit passed"\n'
    )
    executable = source_directory / "source-unit-thread-local-check"
    run(fbc + ["-gen", "gas64", "-mt", "-w", "all", str(wrapper),
               "-x", str(executable)], cwd=source_directory)
    executed = subprocess.run(
        [str(executable)], cwd=source_directory, capture_output=True,
        text=True, timeout=30, check=False,
    )
    assert executed.returncode == 0 and executed.stdout.strip() == \
        "C2FB thread-local source unit passed", executed.stdout + executed.stderr

    tree_source_directory = source_directory / "tree-source"
    tree_source_directory.mkdir()
    (tree_source_directory / "source-unit.c").write_text(source.read_text())
    tree_candidates = source_directory / "tree-candidates"
    tree_result = subprocess.run(
        [
            sys.executable, str(source_unit_tool), str(tree_source_directory),
            str(tree_candidates), "--tree", "--jobs=2",
            "--converter", str(converter), "--compiler", "cc",
        ],
        cwd=source_directory, capture_output=True, text=True,
    )
    assert tree_result.returncode == 0, tree_result.stdout + tree_result.stderr
    assert "unsupported thread-local C objects" not in tree_result.stdout, tree_result.stdout
    tree_candidate = tree_candidates / "source-unit_candidates.bas"
    assert tree_candidate.is_file()
    run(fbc + ["-mt", "-w", "all", "-c", str(tree_candidate), "-o",
               str(tree_candidates / "source-unit_candidates.o")], cwd=tree_candidates)


def check_generic_header_forward_static_record_initializers(converter, fbc, work):
    # Forward aliases may resolve through the backing UDT name, so static
    # aggregate initializers must find the validated record plan by that name.
    source_directory = work / "generic-header-forward-static-record-initializers"
    source_directory.mkdir()
    header = source_directory / "float_static.h"
    header.write_text(
        "typedef struct FloatPair { float first; float second; } FloatPair;\n"
        "static const FloatPair values[2] = "
        "{{1.25f, 0.5f}, {2.75f, 1.0f}};\n"
    )
    binding = source_directory / "float_static.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding),
        "--exclude=*", "--preserve-type-dependencies",
        "--include-static-objects", "--private-static-objects",
        "--forward-decl=*", "cc",
    ])
    generated = binding.read_text()
    assert "1 module-static objects" in summary, summary
    assert "c2fb_values(0 To 1) As Const c2fb_FloatPair_ = " \
        "{(1.25!, 0.5!), (2.75!, 1.0!)}" in generated, generated
    assert "unsupported module-static initializer" not in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "float_static.bi"\n'
        "If c2fb_values(0).first <> 1.25! OrElse "
        "c2fb_values(0).second <> 0.5! Then End 1\n"
        "If c2fb_values(1).first <> 2.75! OrElse "
        "c2fb_values(1).second <> 1.0! Then End 2\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_sqlite_expr_generic_type_context(converter, fbc, cc, repository, work):
    source = repository / "src/expr.c"
