def check_generic_header_dependent_integer_macros(converter, fbc, work):
    # Keep identifier-dependent expressions as macros so forward references
    # and names supplied by a caller do not become invalid header constants.
    source_directory = work / "generic-header-dependent-integer-macros"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "enum ProbeEnum { PROBE_ZERO = 0 };\n"
        "#define BASE_UNSIGNED (0u - 100u)\n"
        "#define NEXT_UNSIGNED (BASE_UNSIGNED - 1u)\n"
        "#define ENUM_UNSIGNED (PROBE_ZERO - 1u)\n"
        "#define UNKNOWN_UNSIGNED (externalValue - 1u)\n"
        "#define UNKNOWN_SIGNED (externalValue - 1)\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    assert "Const c2fb_BASE_UNSIGNED = CULng(0- 100)" in generated, generated
    assert "#define c2fb_NEXT_UNSIGNED (c2fb_BASE_UNSIGNED - 1)" in generated, generated
    assert "#define c2fb_ENUM_UNSIGNED (c2fb_PROBE_ZERO - 1)" in generated, generated
    assert "#define c2fb_UNKNOWN_UNSIGNED (externalValue - 1)" in generated, generated
    assert "#define c2fb_UNKNOWN_SIGNED (externalValue - 1)" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "If CULng(c2fb_NEXT_UNSIGNED) <> CULng(-101) Then End 1\n"
        "If CULng(c2fb_ENUM_UNSIGNED) <> CULng(-1) Then End 2\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


