def check_generic_header_float_to_integer_cast_macros(converter, fbc, cc, work):
    # Known floating literal casts use C's truncation toward zero.
    source_directory = work / "generic-header-float-to-integer-cast-macros"
    source_directory.mkdir()
    header = source_directory / "float-casts.h"
    header.write_text(
        "#define C2FB_NEGATIVE_FLOAT_TO_INT ((int)-5.8)\n"
        "#define C2FB_POSITIVE_FLOAT_TO_INT ((int)5.8)\n"
        "#define C2FB_FLOAT_TO_UNSIGNED ((unsigned int)7.8)\n"
    )
    binding = source_directory / "float-casts.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    for name in (
        "C2FB_NEGATIVE_FLOAT_TO_INT", "C2FB_POSITIVE_FLOAT_TO_INT",
        "C2FB_FLOAT_TO_UNSIGNED",
    ):
        assert f"c2fb_{name}" in generated, generated
    assert "Fix(- 5.8)" in generated, generated
    assert "Fix(5.8)" in generated, generated
    assert "Fix(7.8)" in generated, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "float-casts.h"\n'
        "int c2fbReferenceNegative(void) { return C2FB_NEGATIVE_FLOAT_TO_INT; }\n"
        "int c2fbReferencePositive(void) { return C2FB_POSITIVE_FLOAT_TO_INT; }\n"
        "unsigned int c2fbReferenceUnsigned(void) {\n"
        "    return C2FB_FLOAT_TO_UNSIGNED;\n"
        "}\n"
    )
    reference_object = source_directory / "reference.o"
    run(cc + ["-std=c99", "-O2", "-c", str(reference_source),
              "-o", str(reference_object)])

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        'Declare Function c2fbReferenceNegative CDecl Alias '
        '"c2fbReferenceNegative" () As Long\n'
        'Declare Function c2fbReferencePositive CDecl Alias '
        '"c2fbReferencePositive" () As Long\n'
        'Declare Function c2fbReferenceUnsigned CDecl Alias '
        '"c2fbReferenceUnsigned" () As ULong\n'
        "If c2fb_C2FB_NEGATIVE_FLOAT_TO_INT <> c2fbReferenceNegative() Then End 1\n"
        "If c2fb_C2FB_POSITIVE_FLOAT_TO_INT <> c2fbReferencePositive() Then End 2\n"
        "If c2fb_C2FB_FLOAT_TO_UNSIGNED <> c2fbReferenceUnsigned() Then End 3\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), str(reference_object), "-x",
               str(executable)], cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_header_dynamic_integer_cast_macros(converter, fbc, cc, work):
    # Function-like C macros must retain C casts for the call-site argument type.
    source_directory = work / "generic-header-dynamic-integer-cast-macros"
    source_directory.mkdir()
    header = source_directory / "dynamic-casts.h"
    header.write_text(
        "typedef long C2FB_TEST_LONG;\n"
        "#define C2FB_TO_INT(value) ((int)(value))\n"
        "#define C2FB_TO_UINT(value) ((unsigned int)(value))\n"
        "#define C2FB_TO_TEST_LONG(value) ((C2FB_TEST_LONG)(value))\n"
    )
    binding = source_directory / "dynamic-casts.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "dynamic-casts.h"\n'
        "static int referenceCallCount;\n"
        "static double referenceNextValue(void) {\n"
        "    referenceCallCount++;\n"
        "    return -5.8;\n"
        "}\n"
        "int c2fbReferenceDouble(double value) { return C2FB_TO_INT(value); }\n"
        "int c2fbReferenceFloat(float value) { return C2FB_TO_INT(value); }\n"
        "long c2fbReferenceAlias(double value) {\n"
        "    return C2FB_TO_TEST_LONG(value);\n"
        "}\n"
        "unsigned int c2fbReferenceUnsigned(int value) {\n"
        "    return C2FB_TO_UINT(value);\n"
        "}\n"
        "int c2fbReferenceLongLong(long long value) {\n"
        "    return C2FB_TO_INT(value);\n"
        "}\n"
        "int c2fbReferencePointer(void *value) { return C2FB_TO_INT(value); }\n"
        "int c2fbReferenceSideEffect(int *calls) {\n"
        "    referenceCallCount = 0;\n"
        "    int value = C2FB_TO_INT(referenceNextValue());\n"
        "    *calls = referenceCallCount;\n"
        "    return value;\n"
        "}\n"
    )
    reference_object = source_directory / "reference.o"
    run(cc + ["-std=c99", "-c", str(reference_source), "-o", str(reference_object)])

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        f'#include once "{binding.resolve()}"\n'
        'Declare Function c2fbReferenceDouble CDecl Alias "c2fbReferenceDouble" '
        '(ByVal value As Double) As Long\n'
        'Declare Function c2fbReferenceFloat CDecl Alias "c2fbReferenceFloat" '
        '(ByVal value As Single) As Long\n'
        'Declare Function c2fbReferenceAlias CDecl Alias "c2fbReferenceAlias" '
        '(ByVal value As Double) As CLong\n'
        'Declare Function c2fbReferenceUnsigned CDecl Alias '
        '"c2fbReferenceUnsigned" (ByVal value As Long) As ULong\n'
        'Declare Function c2fbReferenceLongLong CDecl Alias '
        '"c2fbReferenceLongLong" (ByVal value As LongInt) As Long\n'
        'Declare Function c2fbReferencePointer CDecl Alias '
        '"c2fbReferencePointer" (ByVal value As Any Ptr) As Long\n'
        'Declare Function c2fbReferenceSideEffect CDecl Alias '
        '"c2fbReferenceSideEffect" (ByVal calls As Long Ptr) As Long\n'
        "Dim negativeValue As Double = -5.8\n"
        "Dim positiveValue As Double = 5.8\n"
        "Dim singleValue As Single = -5.8\n"
        "Dim longLongValue As LongInt = 12345\n"
        "Dim negativeInteger As Long = -5\n"
        "If c2fb_C2FB_TO_INT(negativeValue) <> "
        "c2fbReferenceDouble(negativeValue) Then End 1\n"
        "If c2fb_C2FB_TO_INT(positiveValue) <> "
        "c2fbReferenceDouble(positiveValue) Then End 2\n"
        "If c2fb_C2FB_TO_TEST_LONG(negativeValue) <> "
        "c2fbReferenceAlias(negativeValue) Then End 9\n"
        "If c2fb_C2FB_TO_INT(singleValue) <> "
        "c2fbReferenceFloat(singleValue) Then End 3\n"
        "If c2fb_C2FB_TO_UINT(negativeInteger) <> "
        "c2fbReferenceUnsigned(negativeInteger) Then End 8\n"
        "If c2fb_C2FB_TO_INT(longLongValue) <> "
        "c2fbReferenceLongLong(longLongValue) Then End 4\n"
        "Dim pointedValue As Long = 42\n"
        "If c2fb_C2FB_TO_INT(@pointedValue) <> "
        "c2fbReferencePointer(@pointedValue) Then End 5\n"
        "Dim Shared SharedCalls As Long\n"
        "Dim cCalls As Long\n"
        "Function nextValue() As Double\n"
        "    SharedCalls += 1\n"
        "    Return -5.8\n"
        "End Function\n"
        "SharedCalls = 0\n"
        "Dim fbValue As Long = c2fb_C2FB_TO_INT(nextValue())\n"
        "Dim cValue As Long = c2fbReferenceSideEffect(@cCalls)\n"
        "If fbValue <> cValue Then End 6\n"
        "If SharedCalls <> 1 OrElse cCalls <> 1 Then End 7\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), str(reference_object), "-x",
               str(executable)], cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_header_typedef_hint_casts(converter, fbc, work):
    source_directory = work / "generic-header-typedef-hint-casts"
    source_directory.mkdir()

    external_header = source_directory / "external.h"
    external_header.write_text("#define VALUE ((T)0)\n")
    external_binding = source_directory / "external.bi"
    run([
        converter, "generic-header", str(external_header),
        str(external_binding), "cc", "--typedef-hint=T",
    ])
    external_generated = external_binding.read_text()
    assert "#define c2fb_VALUE Cast(T, 0)" in external_generated
    assert "Const c2fb_VALUE" not in external_generated
    external_wrapper = source_directory / "check-external.bas"
    external_wrapper.write_text('#include once "external.bi"\n')
    run(fbc + ["-w", "all", "-c", str(external_wrapper), "-o",
               str(source_directory / "check-external.o")], cwd=source_directory)

    declared_header = source_directory / "declared.h"
    declared_header.write_text(
        "#define VALUE ((T)0)\n"
        "typedef double T;\n"
    )
    declared_binding = source_directory / "declared.bi"
    run([
        converter, "generic-header", str(declared_header),
        str(declared_binding), "cc", "--typedef-hint=T",
    ])
    declared_generated = declared_binding.read_text()
    assert "Type c2fb_T As Double" in declared_generated, declared_generated
    assert "Const c2fb_VALUE = Cast(c2fb_T, 0)" in declared_generated, declared_generated
    declared_wrapper = source_directory / "check-declared.bas"
    declared_wrapper.write_text('#include once "declared.bi"\n')
    run(fbc + ["-w", "all", "-c", str(declared_wrapper), "-o",
               str(source_directory / "check-declared.o")], cwd=source_directory)


def check_generic_header_address_and_index_macros(converter, fbc, work):
    # Preserve C address-of and subscript semantics in pointer/member macros.
    source_directory = work / "generic-header-address-index-macros"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "typedef struct ProbeNode { int a[4]; int b; } ProbeNode;\n"
        "#define A90(x) &(x)->a[(x)->b]\n"
        "#define BITWISE_AND(a, b) ((a) & (b))\n"
        "#define SUM(a, b) ((a) + (b))\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    assert (
        "#define c2fb_A90(c2fb_macro_arg_0) "
        "@(c2fb_macro_arg_0)->a((c2fb_macro_arg_0)->b)"
    ) in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "Sub check()\n"
        "    Dim node As c2fb_ProbeNode\n"
        "    Dim nodePointer As c2fb_ProbeNode Ptr = @node\n"
        "    node.a(2) = 42\n"
        "    node.b = 2\n"
        "    Dim selected As Long Ptr = c2fb_A90(nodePointer)\n"
        "    If *selected <> 42 Then End 1\n"
        "    If c2fb_BITWISE_AND(6, 3) <> 2 Then End 2\n"
        "    If c2fb_SUM(1, 2) * 3 <> 9 Then End 3\n"
        "End Sub\n"
        "check()\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


