    header.write_text(
        "#define CDECL_CALLBACK ((__attribute__((cdecl)) void (*)(void))0)\n"
        "#define STDCALL_CALLBACK ((__attribute__((stdcall)) void (*)(void))0)\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    assert "#define c2fb_CDECL_CALLBACK CPtr(Sub CDecl(), 0)" in generated, generated
    assert "#define c2fb_STDCALL_CALLBACK CPtr(Sub StdCall(), 0)" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "Dim cdeclCallback As Any Ptr = c2fb_CDECL_CALLBACK\n"
        "Dim stdcallCallback As Any Ptr = c2fb_STDCALL_CALLBACK\n"
        "If cdeclCallback <> 0 Then End 1\n"
        "If stdcallCallback <> 0 Then End 2\n"
    )
