def check_generic_header_sizeof_function_type_macros(converter, fbc, work):
    # sizeof(T1*) must use FreeBASIC's callback typedef, whose type is itself
    # the callable pointer representation.
    source_directory = work / "generic-header-sizeof-function-type-macros"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "typedef int T1(int i);\n"
        "struct UDT1 { int field; };\n"
        "#define P13 sizeof(T1*)\n"
        "#define D2 sizeof(struct UDT1)\n"
        "#define SIZE_OF_ARGUMENT(value) sizeof(value)\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    assert "#define c2fb_P13 SizeOf(c2fb_T1)" in generated, generated
    assert "#define c2fb_D2 SizeOf(c2fb_UDT1)" in generated, generated
    assert "#define c2fb_SIZE_OF_ARGUMENT(c2fb_macro_arg_0)" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "Const callbackSize = c2fb_P13\n"
        "If callbackSize <> SizeOf(c2fb_T1) Then End 1\n"
        "Const recordSize = c2fb_D2\n"
        "If recordSize <> SizeOf(c2fb_UDT1) Then End 3\n"
        "Dim value As LongInt\n"
        "If c2fb_SIZE_OF_ARGUMENT(value) <> SizeOf(value) Then End 2\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_header_direct_call_macros(converter, fbc, work):
    # Match fbfrog's direct-call macro translation, including unresolved names
    # that are expected to come from a caller-supplied FreeBASIC binding.
    source_directory = work / "generic-header-direct-call-macros"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "int c2fbKnownFunction(int left, int right);\n"
        "#define NORMAL_CALL c2fbKnownFunction(1, 2)\n"
        "#define UNKNOWN_CALL unresolvedFunction(0)\n"
        "#define PAREN_CALL (c2fbKnownFunction)(3, 4)\n"
        "#define PARAM_CALL(fn) (fn)(5, 6)\n"
        "#define B2() x\n"
        "#define FEATURE_FLAG 1\n"
        "#define FLAG_IS_DEFINED defined(FEATURE_FLAG)\n"
        "#define MISSING_FLAG_IS_DEFINED defined(MISSING_FLAG)\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([
        converter, "generic-header", str(header), str(binding), "cc",
    ])
    generated = binding.read_text()
    assert "direct-call," in summary, summary

    normal = re.search(r"^#define (c2fb_NORMAL_CALL\w*) ", generated, re.M)
    unknown = re.search(r"^#define (c2fb_UNKNOWN_CALL\w*) ", generated, re.M)
    parenthesized = re.search(r"^#define (c2fb_PAREN_CALL\w*) ", generated, re.M)
    zero_argument = re.search(r"^#define (c2fb_B2\w*)\(\) x$", generated, re.M)
    assert normal and parenthesized and unknown and zero_argument, generated
    assert f"{normal.group(1)} c2fb_c2fbKnownFunction(1, 2)" in generated
    assert f"{unknown.group(1)} unresolvedFunction(0)" in generated
    assert f"{parenthesized.group(1)} c2fb_c2fbKnownFunction(3, 4)" in generated
    assert re.search(
        r"^#define c2fb_FLAG_IS_DEFINED_? defined\(c2fb_FEATURE_FLAG\)$",
        generated, re.M)
    assert re.search(
        r"^#define c2fb_MISSING_FLAG_IS_DEFINED_? defined\(MISSING_FLAG\)$",
        generated, re.M)
    assert re.search(
        r"^#define c2fb_PARAM_CALL\([^\n]*\) "
        r"c2fb_macro_arg_0\(5, 6\)$", generated, re.M)

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        f"Dim normalResult As Long = {normal.group(1)}\n"
        f"Dim parenthesizedResult As Long = {parenthesized.group(1)}\n"
        "Dim parameterResult As Long = c2fb_PARAM_CALL(c2fb_c2fbKnownFunction)\n"
    )
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "check.o")], cwd=source_directory)


def check_generic_header_object_token_sequences(converter, fbc, work):
    # Preserve simple adjacent token sequences that fbfrog emits unchanged.
    source_directory = work / "generic-header-object-token-sequences"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "#define SEQUENCE_A a b c\n"
        '#define SEQUENCE_B a "b" c\n'
        '#define SEQUENCE_C "a" b "c"\n'
        "#define SEQUENCE_PASTE left##right\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "4 token-sequence," in summary, summary
    assert re.search(r"^#define c2fb_SEQUENCE_A_? a b c$", generated, re.M)
    assert 'a !"b" c' in generated, generated
    assert '!"a" b !"c"' in generated, generated
    assert "#define c2fb_SEQUENCE_PASTE leftright" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        "#define leftright 73\n"
        '#include once "probe.bi"\n'
        "If c2fb_SEQUENCE_PASTE <> 73 Then End 1\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_header_function_token_pastes(converter, fbc, cc, work):
    # Function-like ## macros must paste in the C2FB symbol namespace while
    # preserving arguments that the C preprocessor would not expand first.
    source_directory = work / "generic-header-function-token-pastes"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        "extern int x1;\n"
        "extern int x2;\n"
        "extern int x3;\n"
        "extern int n1n2;\n"
        "#define m1(x) m##x\n"
        "#define m2 x2\n"
        "#define m3 x3\n"
        "#define n1 x1\n"
        "#define n2 x2\n"
        "#define JOIN_BEFORE(x) n1##x\n"
    )
    binding = source_directory / "probe.bi"
    summary = run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "skipped 0 unsupported declarations or macro expressions" in summary, summary
    assert re.search(r"^#define c2fb_m1\([^\n]*\) c2fb_##m##", generated, re.M), generated
    assert re.search(r"^#define c2fb_JOIN_BEFORE\([^\n]*\) c2fb_##n1##", generated, re.M), generated

    support = source_directory / "support.c"
    support.write_text(
        "int x1 = 11;\n"
        "int x2 = 22;\n"
        "int x3 = 33;\n"
        "int n1n2 = 44;\n"
    )
    support_object = source_directory / "support.o"
    run(cc + ["-std=c99", "-c", str(support), "-o", str(support_object)],
        cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "probe.bi"\n'
        "If c2fb_m1(2) <> c2fb_x2 Then End 1\n"
        "If c2fb_m1(3) <> c2fb_x3 Then End 2\n"
        "If c2fb_JOIN_BEFORE(n2) <> c2fb_n1n2 Then End 3\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), str(support_object), "-x",
               str(executable)], cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_header_transient_macros(converter, fbc, work):
    # Preserve fbfrog's define-then-undef API macro history without leaking
    # those temporary names after the generated binding has been included.
    source_directory = work / "generic-header-transient-macros"
    source_directory.mkdir()
    header = source_directory / "probe.h"
    header.write_text(
        '#pragma push_macro("TEMPORARY")\n'
        "#define TEMPORARY\n"
        '#pragma pop_macro("TEMPORARY")\n'
        "#define RETURNED 5\n"
        "#undef RETURNED\n"
        "#define APPLY(x) x\n"
        "#undef APPLY\n"
    )
    binding = source_directory / "probe.bi"
    run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "#define c2fb_TEMPORARY" in generated, generated
    assert "#undef c2fb_TEMPORARY" in generated, generated
    assert "#define c2fb_RETURNED 5" in generated, generated
    assert "#undef c2fb_RETURNED" in generated, generated
    assert "#define c2fb_APPLY(c2fb_macro_arg_0) c2fb_macro_arg_0" in generated, generated
    assert "#undef c2fb_APPLY" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "probe.bi"\n')
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "check.o")], cwd=source_directory)


def check_generic_header_pragma_macro_state_recovery(converter, fbc, cc, work):
    # GCC's -dM can retain a temporary macro after _Pragma(pop_macro), even
    # though ordinary preprocessing restores the earlier definition.
    source_directory = work / "generic-header-pragma-macro-state"
    source_directory.mkdir()
    header = source_directory / "pragma-state.h"
    header.write_text(
        "#define C2FB_TEST_PRAGMA_RESTORED 1\n"
        '_Pragma("push_macro(\\"C2FB_TEST_PRAGMA_RESTORED\\")")\n'
        "#undef C2FB_TEST_PRAGMA_RESTORED\n"
        "#define C2FB_TEST_PRAGMA_RESTORED 2\n"
        '_Pragma("pop_macro(\\"C2FB_TEST_PRAGMA_RESTORED\\")")\n'
    )
    binding = source_directory / "pragma-state.bi"
    run([converter, "generic-header", str(header), str(binding), "cc"])
    generated = binding.read_text()
    assert "Const c2fb_C2FB_TEST_PRAGMA_RESTORED = 1" in generated, generated
    assert "' c2fb automatic macro-state recovery: " \
        "expanded 1, unsupported 0, excluded 0" in generated, generated

    reference = source_directory / "reference.c"
    reference.write_text(
        '#include "pragma-state.h"\n'
        "int c2fb_pragma_state_reference(void) {\n"
        "    return C2FB_TEST_PRAGMA_RESTORED;\n"
        "}\n"
    )
    reference_object = source_directory / "reference.o"
    run(cc + ["-std=c99", "-c", str(reference), "-o", str(reference_object)],
        cwd=source_directory)

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "pragma-state.bi"\n'
        'Extern "C"\n'
        '    Declare Function c2fb_pragma_state_reference CDecl Alias '
        '"c2fb_pragma_state_reference" () As Integer\n'
        'End Extern\n'
        "If c2fb_C2FB_TEST_PRAGMA_RESTORED <> 1 Then End 1\n"
        "If c2fb_pragma_state_reference() <> "
        "c2fb_C2FB_TEST_PRAGMA_RESTORED Then End 2\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), str(reference_object), "-x",
               str(executable)], cwd=source_directory)
    run([str(executable)], cwd=source_directory)


