    assert 'Extern c2fb_values(0 To 3) Alias "values" As Long' \
        in generated, generated
    assert "i2(0 To 24) As Long" in generated, generated
    assert "C flexible array member size is expanded by --array-size: i2=25" \
        in generated, generated
    assert 'Extern c2fb_grid(0 To 9, 0 To 2) Alias "grid" As Long' \
        in generated, generated

    wrapper = source_directory / "check.bas"
