def check_generic_body_sizeof_array_bounds_and_void_assignments(
    converter, fbc, cc, work
):
    # fd_set-style declarations use sizeof in an array bound, and FD_SET-style
    # macros discard a compound-assignment value through a void cast.
    source_directory = work / "generic-body-sizeof-array-bound-void-assignment"
    source_directory.mkdir()
    source = source_directory / "fd_set.c"
    source.write_text(
        "typedef long __fd_mask;\n"
        "typedef struct {\n"
        "    __fd_mask __fds_bits[1024 / (8 * (int) sizeof(__fd_mask))];\n"
        "} fd_set;\n"
        "#define C2FB_FD_ZERO(set) do { \\\n"
        "    for (int i = 0; i < sizeof(fd_set) / sizeof(__fd_mask); i++) \\\n"
        "        (set)->__fds_bits[i] = 0; \\\n"
        "} while (0)\n"
        "#define C2FB_FD_SET(fd, set) ((void) (((set)->__fds_bits[ \\\n"
        "    (fd) / (8 * (int) sizeof(__fd_mask))] |= \\\n"
        "    ((__fd_mask) (1UL << ((fd) % (8 * (int) sizeof(__fd_mask))))))))\n"
        "int c2fbTestFdSet(int descriptor) {\n"
        "    fd_set set;\n"
        "    C2FB_FD_ZERO(&set);\n"
        "    C2FB_FD_SET(descriptor, &set);\n"
        "    return set.__fds_bits[descriptor / (8 * sizeof(__fd_mask))] != 0;\n"
        "}\n"
    )
    candidate = source_directory / "fd_set_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated_types = candidate.with_name(candidate.stem + "_types.bi").read_text()
    assert "__fds_bits(0 To" in generated_types, generated_types

    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(candidate), "-x",
               str(converted_path)], cwd=source_directory)
    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbTestFdSet.argtypes = [ctypes.c_int]
        library.c2fbTestFdSet.restype = ctypes.c_int
    for descriptor in (0, 1, 31, 32, 63, 64, 1023):
        expected = reference.c2fbTestFdSet(descriptor)
        actual = converted.c2fbTestFdSet(descriptor)
        assert actual == expected, (
            f"fd_set bit {descriptor} differs: C={expected}, FB={actual}"
        )


def check_generic_body_callback_dependencies(converter, fbc, work):
    # A source-local VLA helper must stay available through callback lowering.
    source_directory = work / "generic-body-callback-dependencies"
    source_directory.mkdir()
    source = source_directory / "callbacks.c"
    source.write_text(
        "int c2fbCallbackApply(int (*callback)(int), int value) {\n"
        "    return callback(value);\n"
        "}\n"
        "static int c2fbUntranslatedHelper(int value) {\n"
        "    int items[value];\n"
        "    return sizeof(items);\n"
        "}\n"
        "int c2fbCallbackDependency(int value) {\n"
        "    return c2fbCallbackApply(c2fbUntranslatedHelper, value);\n"
        "}\n"
    )
    candidate = source_directory / "callbacks_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), "cc",
    ])
    assert "translated 3 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "Function c2fbCallbackApply" in generated
    assert "Function c2fbUntranslatedHelper" in generated
    assert "Function c2fbCallbackDependency" in generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "callbacks_candidates.bas"\n'
        "For value As Long = 1 To 16\n"
        "    If c2fbCallbackDependency(value) <> value * 4 Then End 1\n"
        "Next\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)


def check_generic_body_external_callback_declaration(converter, fbc, cc, work):
    # A callback used by an emitted external prototype needs its alias first.
    source_directory = work / "generic-body-external-callback-declaration"
    source_directory.mkdir()
    source = source_directory / "external_callback.c"
    source.write_text(
        "extern int c2fbExternalApply(int (*callback)(int), int value);\n"
        "static int c2fbTwice(int value) { return value * 2; }\n"
        "int c2fbUseExternalCallback(int value) {\n"
        "    return c2fbExternalApply(c2fbTwice, value);\n"
        "}\n"
    )
    candidate = source_directory / "external_callback_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), *cc,
    ])
    assert "translated 2 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    callback_match = re.search(
        r"(?m)^Type (c2fb_callback_\d+) As Function CDecl\(ByVal arg0 As c2fb_c_int\) As c2fb_c_int$",
        generated,
    )
    assert callback_match is not None, generated
    callback_type = callback_match.group(1)
    declaration = re.search(
        r"(?m)^Declare Function c2fb_external_c2fbExternalApply .*\n", generated,
    )
    assert declaration is not None and f"As {callback_type}" in declaration.group(0), generated
    assert callback_match.start() < declaration.start(), generated

    wrapper = source_directory / "external_callback_check.bas"
    wrapper.write_text('#include once "external_callback_candidates.bas"\n')
    run(fbc + ["-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "external_callback.o")],
        cwd=source_directory)


def check_generic_body_function_returning_callback(converter, fbc, cc, work):
    # A direct function's arguments use its signature even when it returns a callback.
    source_directory = work / "generic-body-function-returning-callback"
    source_directory.mkdir()
    source = source_directory / "callback_return.c"
    source.write_text(
        "typedef int CALLBACK(int value);\n"
        "static int c2fbTwice(int value) { return value * 2; }\n"
        "static int c2fbAddThree(int value) { return value + 3; }\n"
        "CALLBACK *c2fbGetCallback(int selector, int context) {\n"
        "    (void)context;\n"
        "    if (selector) return c2fbTwice;\n"
        "    return c2fbAddThree;\n"
        "}\n"
        "int c2fbInvokeReturned(int selector, int context, int value) {\n"
        "    CALLBACK *callback = c2fbGetCallback(selector, context);\n"
        "    return (*callback)(value);\n"
        "}\n"
    )
    candidate = source_directory / "callback_return_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), cc[0],
    ])
    assert "translated 4 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "callback_return_candidates.bas"\n')
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), "-x",
               str(converted_path)], cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbInvokeReturned.argtypes = [
            ctypes.c_int, ctypes.c_int, ctypes.c_int,
        ]
        library.c2fbInvokeReturned.restype = ctypes.c_int
    for selector, context, value in ((1, 91, 7), (0, 17, 7), (1, -3, 12)):
        expected = reference.c2fbInvokeReturned(selector, context, value)
        assert converted.c2fbInvokeReturned(selector, context, value) == expected


def check_generic_body_static_callback_tables(converter, fbc, cc, work):
    # Function typedefs become callback types for automatic and static tables.
    source_directory = work / "generic-body-static-callback-tables"
    source_directory.mkdir()
    source = source_directory / "callback_tables.c"
    source.write_text(
        "typedef int PUTTER(int value);\n"
        "static int c2fbPutOne(int value) { return value + 1; }\n"
        "static int c2fbPutTwo(int value) { return value + 2; }\n"
        "int c2fbCallbackScalar(int value) {\n"
        "    PUTTER *putter = c2fbPutOne;\n"
        "    return putter(value);\n"
        "}\n"
        "int c2fbCallbackArray(int index, int value) {\n"
        "    PUTTER *putters[2] = { c2fbPutOne, c2fbPutTwo };\n"
        "    return putters[index](value);\n"
        "}\n"
        "int c2fbCallbackStaticArray(int index, int value) {\n"
        "    static PUTTER *putters[3] = { c2fbPutOne, c2fbPutTwo, 0 };\n"
        "    return putters[index](value);\n"
        "}\n"
    )
    candidate = source_directory / "callback_table_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), "cc",
    ])
    assert "translated 5 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "Type c2fb_callback_0 As Function CDecl" in generated, generated
    assert "Static local" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "callback_table_candidates.bas"\n'
        "If c2fbCallbackScalar(4) <> 5 Then End 1\n"
        "If c2fbCallbackArray(0, 4) <> 5 Then End 2\n"
        "If c2fbCallbackArray(1, 4) <> 6 Then End 3\n"
        "If c2fbCallbackStaticArray(0, 4) <> 5 Then End 4\n"
        "If c2fbCallbackStaticArray(1, 4) <> 6 Then End 5\n"
    )
    executable = source_directory / "check"
    run(fbc + ["-w", "all", str(wrapper), "-x", str(executable)],
        cwd=source_directory)
    run([str(executable)], cwd=source_directory)

    file_source = source_directory / "file_callback_tables.c"
    file_source.write_text(
        "#define NULL ((void *)0)\n"
        "static int c2fbBuiltinOne(int value) { return value * 3 + 1; }\n"
        "static int c2fbBuiltinTwo(int value) { return value * 5 + 2; }\n"
        "static int (*const c2fbBuiltinCallbacks[])(int) = {\n"
        "    c2fbBuiltinOne, &c2fbBuiltinTwo\n"
        "};\n"
        "static int (*const c2fbPartialCallbacks[3])(int) = {\n"
        "    c2fbBuiltinOne, NULL\n"
        "};\n"
        "int c2fbInvokeBuiltin(int selector, int value) {\n"
        "    return c2fbBuiltinCallbacks[selector](value);\n"
        "}\n"
        "int c2fbInvokePartial(int selector, int value) {\n"
        "    return c2fbPartialCallbacks[selector](value);\n"
        "}\n"
    )
    file_candidate = source_directory / "file_callback_candidates.bas"
    file_summary = run([
        converter, "translate-simple-generic-c", str(file_source),
        str(file_candidate), "cc",
    ])
    assert "translated 4 simple functions; skipped 0" in file_summary, file_summary
    file_generated = file_candidate.read_text()
    assert re.search(
        r"Private Dim Shared \w*c2fbBuiltinCallbacks\(0 To 1\) As Const ",
        file_generated,
    ), file_generated
    assert "{ProcPtr(c2fbBuiltinOne), ProcPtr(c2fbBuiltinTwo)}" in \
        file_generated, file_generated
    assert "CPtr(c2fb_callback_0, 0)" in file_generated, file_generated

    reference_path = source_directory / "file_callback_reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(file_source),
              "-o", str(reference_path)], cwd=source_directory)
    file_wrapper = source_directory / "file_callback_check.bas"
    file_wrapper.write_text(
        '#include once "file_callback_candidates.bas"\n'
    )
    converted_path = source_directory / "file_callback_converted.so"
    run(fbc + ["-w", "all", "-dll", str(file_wrapper), "-x",
               str(converted_path)], cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        for name in ("c2fbInvokeBuiltin", "c2fbInvokePartial"):
            procedure = getattr(library, name)
            procedure.argtypes = [ctypes.c_int, ctypes.c_int]
            procedure.restype = ctypes.c_int
    for selector, value in ((0, 0), (0, 17), (1, -4), (1, 29)):
        expected = reference.c2fbInvokeBuiltin(selector, value)
        assert converted.c2fbInvokeBuiltin(selector, value) == expected
    for value in (0, 17, -4, 29):
        expected = reference.c2fbInvokePartial(0, value)
        assert converted.c2fbInvokePartial(0, value) == expected

    mismatch_source = source_directory / "mismatched_callback_table.c"
    mismatch_source.write_text(
        "static long c2fbWrongCallback(int value) { return value; }\n"
        "static int (*const c2fbWrongCallbacks[])(int) = { c2fbWrongCallback };\n"
        "int c2fbInvokeWrongCallback(int value) {\n"
        "    return c2fbWrongCallbacks[0](value);\n"
        "}\n"
    )
    mismatch_candidate = source_directory / "mismatched_callback_candidates.bas"
    mismatch_summary = run([
        converter, "translate-simple-generic-c", str(mismatch_source),
        str(mismatch_candidate), "cc",
    ])
    assert "translated 1 simple functions; skipped 1" in mismatch_summary, \
        mismatch_summary
    assert "c2fbInvokeWrongCallback" not in procedure_names(
        mismatch_candidate.read_text()
    )

    unresolved_source = source_directory / "unresolved_callback_target.c"
    unresolved_source.write_text(
        "static int c2fbUntranslatedCallback(int value) {\n"
        "    return c2fbUnknownHelper(value);\n"
        "}\n"
        "static int (*const c2fbUntranslatedCallbacks[])(int) = {\n"
        "    c2fbUntranslatedCallback\n"
        "};\n"
        "int c2fbInvokeUntranslatedCallback(int value) {\n"
        "    return c2fbUntranslatedCallbacks[0](value);\n"
        "}\n"
    )
    unresolved_candidate = source_directory / "unresolved_callback_candidates.bas"
    unresolved_summary = run([
        converter, "translate-simple-generic-c", str(unresolved_source),
        str(unresolved_candidate), "cc",
    ])
    assert "translated 0 simple functions; skipped 2" in unresolved_summary, \
        unresolved_summary
    unresolved_generated = unresolved_candidate.read_text()
    assert "c2fbInvokeUntranslatedCallback" not in procedure_names(
        unresolved_generated
    )
    assert "requires unconverted C function c2fbUntranslatedCallback" in \
        unresolved_generated, unresolved_generated
    unresolved_wrapper = source_directory / "unresolved_callback_check.bas"
    unresolved_wrapper.write_text(
        '#include once "unresolved_callback_candidates.bas"\n'
    )
    run(fbc + ["-w", "all", "-c", str(unresolved_wrapper)],
        cwd=source_directory)


def check_generic_body_parenthesized_callback_member(converter, fbc, cc, work):
    # C's (*image->f.callback)(...) dereference keeps the callback signature.
    source_directory = work / "generic-body-parenthesized-callback-member"
    source_directory.mkdir()
    source = source_directory / "callback_member.c"
    source.write_text(
        "typedef struct Image Image;\n"
        "struct Image {\n"
        "    struct { int (*destroy_image)(Image *); } f;\n"
        "    int value;\n"
        "};\n"
        "int c2fbDestroyImage(Image *image) {\n"
        "    return (*image->f.destroy_image)(image);\n"
        "}\n"
    )
    candidate = source_directory / "callback_member_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    wrapper = source_directory / "check.bas"
    wrapper.write_text('#include once "callback_member_candidates.bas"\n')
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), "-x",
               str(converted_path)], cwd=source_directory)

    class Image(ctypes.Structure):
        pass

    ImageCallback = ctypes.CFUNCTYPE(ctypes.c_int, ctypes.POINTER(Image))

    class ImageFunctions(ctypes.Structure):
        _fields_ = [("destroy_image", ImageCallback)]

    Image._fields_ = [("f", ImageFunctions), ("value", ctypes.c_int)]
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    for library in (reference, converted):
        library.c2fbDestroyImage.argtypes = [ctypes.POINTER(Image)]
        library.c2fbDestroyImage.restype = ctypes.c_int
    callback = ImageCallback(lambda image: image.contents.value * 3 + 2)
    reference_image = Image(ImageFunctions(callback), 17)
    converted_image = Image(ImageFunctions(callback), 17)
    assert reference.c2fbDestroyImage(ctypes.byref(reference_image)) == \
        converted.c2fbDestroyImage(ctypes.byref(converted_image)) == 53


