def check_sqlite_body_pcache_config_snapshot(converter, fbc, cc, work):
    # C's global PCACHE2 table is read through the port's copied-table accessor.
    source_directory = work / "sqlite-body-pcache-config-snapshot"
    source_directory.mkdir()
    body_catalog = source_directory / "body-catalog"
    fb_source_directory = Path(__file__).resolve().parents[3] / "fb_src"
    link_freebasic_standalone_interfaces(fb_source_directory, body_catalog)

    source = source_directory / "pcache_config.c"
    source.write_text(
        "typedef struct sqlite3_pcache_page { void *pBuf; void *pExtra; } "
        "sqlite3_pcache_page;\n"
        "typedef struct sqlite3_pcache_methods2 {\n"
        "    sqlite3_pcache_page *(*xFetch)(void *, unsigned int, int);\n"
        "} sqlite3_pcache_methods2;\n"
        "typedef struct C2fbConfigFixture {\n"
        "    sqlite3_pcache_methods2 pcache2;\n"
        "} C2fbConfigFixture;\n"
        "extern C2fbConfigFixture sqlite3Config;\n"
        "sqlite3_pcache_page *c2fbCallPcache2Fetch("
        "void *cache, unsigned int page, int createFlag) {\n"
        "    return sqlite3Config.pcache2.xFetch(cache, page, createFlag);\n"
        "}\n"
    )
    candidate = source_directory / "pcache_config_candidates.bas"
    summary = run([
        converter, "translate-simple", str(source), str(candidate),
        str(body_catalog),
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "c2fbSqlitePcacheMethodsSnapshot().xFetch" in generated, generated

    reference_source = source_directory / "reference.c"
    reference_source.write_text(
        '#include "pcache_config.c"\n'
        "C2fbConfigFixture sqlite3Config;\n"
        "void c2fbSetPcache2Fetch(sqlite3_pcache_page *(*xFetch)("
        "void *, unsigned int, int)) {\n"
        "    sqlite3Config.pcache2.xFetch = xFetch;\n"
        "}\n"
    )
    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(reference_source),
              "-o", str(reference_path)], cwd=source_directory)

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "pcache_config_candidates.bas"\n'
        "Private Dim Shared c2fbTestMethods As SqlitePcacheMethods2\n"
        "Function c2fbSqlitePcacheMethodsSnapshot CDecl "
        'Alias "c2fbSqlitePcacheMethodsSnapshot" () As SqlitePcacheMethods2\n'
        "    Return c2fbTestMethods\n"
        "End Function\n"
        "Sub c2fbSetPcache2Fetch CDecl Alias "
        '"c2fbSetPcache2Fetch" (ByVal xFetch As SqlitePcacheXFetchProc) Export\n'
        "    c2fbTestMethods.xFetch = xFetch\n"
        "End Sub\n"
        "Function c2fbRunPcache2Fetch CDecl Alias "
        '"c2fbRunPcache2Fetch" (ByVal cache As Any Ptr, ByVal page As u32, '
        'ByVal createFlag As SQLITE_C_INT) As sqlite3_pcache_page Ptr Export\n'
        "    Return c2fbCallPcache2Fetch(cache, page, createFlag)\n"
        "End Function\n"
    )
    converted_path = source_directory / "converted.so"
    run(fbc + [
        "-mt", "-w", "all", "-d", "SQLITE_THREADSAFE=1", "-dll", "-i",
        str(body_catalog), str(wrapper), "-x", str(converted_path),
    ], cwd=source_directory)

    class PcachePage(ctypes.Structure):
        _fields_ = [("pBuf", ctypes.c_void_p), ("pExtra", ctypes.c_void_p)]

    fetch_type = ctypes.CFUNCTYPE(
        ctypes.c_void_p, ctypes.c_void_p, ctypes.c_uint, ctypes.c_int)
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    reference.c2fbSetPcache2Fetch.argtypes = [fetch_type]
    converted.c2fbSetPcache2Fetch.argtypes = [fetch_type]
    reference.c2fbCallPcache2Fetch.argtypes = [
        ctypes.c_void_p, ctypes.c_uint, ctypes.c_int,
    ]
    reference.c2fbCallPcache2Fetch.restype = ctypes.c_void_p
    converted.c2fbRunPcache2Fetch.argtypes = [
        ctypes.c_void_p, ctypes.c_uint, ctypes.c_int,
    ]
    converted.c2fbRunPcache2Fetch.restype = ctypes.c_void_p
    pages = (PcachePage * 8)()

    @fetch_type
    def callback(cache, page, create_flag):
        result = pages[page % len(pages)]
        result.pBuf = cache
        result.pExtra = page * 16 + create_flag
        return ctypes.addressof(result)

    reference.c2fbSetPcache2Fetch(callback)
    converted.c2fbSetPcache2Fetch(callback)
    for cache, page, create_flag in (
        (0x12340, 0, 0), (0x22220, 3, 2), (0x7ABC0, 7, 1),
    ):
        expected = reference.c2fbCallPcache2Fetch(cache, page, create_flag)
        actual = converted.c2fbRunPcache2Fetch(cache, page, create_flag)
        assert actual == expected
        expected_page = ctypes.cast(
            expected, ctypes.POINTER(PcachePage)).contents
        actual_page = ctypes.cast(
            actual, ctypes.POINTER(PcachePage)).contents
        assert expected_page.pBuf == actual_page.pBuf == cache
        assert (expected_page.pExtra or 0) == (actual_page.pExtra or 0) == (
            page * 16 + create_flag
        )


def check_generic_body_static_unsigned_callback_objects(converter, fbc, cc, work):
    # A type keyword inside the callback parameters must not make its object
    # declaration look like a function prototype during source scanning.
    source_directory = work / "generic-body-static-unsigned-callback-objects"
    source_directory.mkdir()
    source = source_directory / "unsigned_callback_objects.c"
    source.write_text(
        "static unsigned int (*c2fbFirstCallback)(int);\n"
        "static unsigned int (*c2fbSecondCallback)(int);\n"
        "static unsigned int c2fbAddThree(int value) {\n"
        "    return (unsigned int)(value + 3);\n"
        "}\n"
        "void c2fbInstallUnsignedCallbacks(void) {\n"
        "    c2fbFirstCallback = c2fbSecondCallback = c2fbAddThree;\n"
        "}\n"
        "unsigned int c2fbCallUnsignedCallback(int value) {\n"
        "    if (c2fbFirstCallback == 0) c2fbInstallUnsignedCallbacks();\n"
        "    return c2fbFirstCallback(value);\n"
        "}\n"
        "int class(int value) { return value + 9; }\n"
        "int c2fbCallClass(int value) { return class(value) + 1; }\n"
    )
    candidate = source_directory / "unsigned_callback_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), "cc",
    ])
    assert "translated 5 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert generated.count("Private Dim Shared c2fb_global_c2fb") == 2, generated
    assert re.search(
        r'^Function class_+ CDecl Alias "class"', generated, re.M,
    ), generated

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source),
              "-o", str(reference_path)], cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    reference.c2fbCallUnsignedCallback.argtypes = [ctypes.c_int]
    reference.c2fbCallUnsignedCallback.restype = ctypes.c_uint
    reference_class = getattr(reference, "class")
    reference_class.argtypes = [ctypes.c_int]
    reference_class.restype = ctypes.c_int
    reference.c2fbCallClass.argtypes = [ctypes.c_int]
    reference.c2fbCallClass.restype = ctypes.c_int
    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        converted_path = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(candidate), "-x",
                           str(converted_path)], cwd=source_directory)
        converted = ctypes.CDLL(str(converted_path))
        converted.c2fbCallUnsignedCallback.argtypes = [ctypes.c_int]
        converted.c2fbCallUnsignedCallback.restype = ctypes.c_uint
        converted_class = getattr(converted, "class")
        converted_class.argtypes = [ctypes.c_int]
        converted_class.restype = ctypes.c_int
        converted.c2fbCallClass.argtypes = [ctypes.c_int]
        converted.c2fbCallClass.restype = ctypes.c_int
        for value in (-5, 0, 1, 42):
            assert reference.c2fbCallUnsignedCallback(value) == \
                converted.c2fbCallUnsignedCallback(value)
            assert reference_class(value) == converted_class(value)
            assert reference.c2fbCallClass(value) == converted.c2fbCallClass(value)


def check_generic_body_callback_type_name_collisions(converter, fbc, work):
    # Generated callback types must avoid FreeBASIC aliases already in scope.
    source_directory = work / "generic-body-callback-type-name-collisions"
    source_directory.mkdir()
    bindings = source_directory / "bindings"
    bindings.mkdir()
    callback_aliases = []
    for callback_index in range(1, 9):
        parameters = ", ".join(
            f"ByVal arg{parameter_index} As Long"
            for parameter_index in range(callback_index)
        )
        callback_aliases.append(
            f"Type c2fb_callback_{callback_index} As "
            f"Function CDecl({parameters}) As Long"
        )
    callback_binding = bindings / "callbacks.bi"
    callback_binding.write_text("\n".join(callback_aliases) + "\n")
    source = source_directory / "callback.c"
    source.write_text(
        "int c2fbUseCallback(int (*callback)(int left, int right), int value) {\n"
        "    return value;\n"
        "}\n"
    )
    candidate = source_directory / "callback_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source),
        str(candidate), "cc", f"--fb-source-directory={bindings}",
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert "Type c2fb_callback_9 As Function CDecl" in generated, generated

    wrapper = source_directory / "check.bas"
    wrapper.write_text(
        '#include once "callbacks.bi"\n'
        '#include once "callback_candidates.bas"\n'
    )
    run(fbc + ["-w", "all", "-i", str(bindings), "-c", str(wrapper),
               "-o", str(source_directory / "check.o")],
        cwd=source_directory)

    scalar_bindings = source_directory / "scalar-bindings"
    scalar_bindings.mkdir()
    (scalar_bindings / "callback_name.bi").write_text(
        "Type c2fb_callback_0 As Long\n"
    )
    scalar_source = source_directory / "scalar_callback.c"
    scalar_source.write_text(
        "int c2fbUseCallbackWithScalarAlias("
        "int (*callback)(int left, int right), int value) {\n"
        "    return value;\n"
        "}\n"
    )
    scalar_candidate = source_directory / "scalar_callback_candidates.bas"
    scalar_summary = run([
        converter, "translate-simple-generic-c", str(scalar_source),
        str(scalar_candidate), "cc",
        f"--fb-source-directory={scalar_bindings}",
    ])
    assert "translated 1 simple functions; skipped 0" in scalar_summary, scalar_summary
    assert "Type c2fb_callback_1 As Function CDecl" \
        in scalar_candidate.read_text(), scalar_candidate.read_text()
    scalar_wrapper = source_directory / "scalar_check.bas"
    scalar_wrapper.write_text(
        '#include once "callback_name.bi"\n'
        '#include once "scalar_callback_candidates.bas"\n'
    )
    run(fbc + ["-w", "all", "-i", str(scalar_bindings), "-c",
               str(scalar_wrapper), "-o",
               str(source_directory / "scalar_check.o")],
        cwd=source_directory)


