def check_generic_body_static_local_pointers(converter, fbc, cc, work):
    # Local static object pointers preserve their C storage and initializer lifetime.
    source_directory = work / "generic-body-static-local-pointers"
    source_directory.mkdir()
    source = source_directory / "static_pointers.c"
    source.write_text(
        "typedef int C2fbUnaryCallback(int value);\n"
        "static int c2fbStaticPointerTarget = 31;\n"
        "static int c2fbStaticCallbackPlus(int value) { return value + 3; }\n"
        "static int c2fbStaticCallbackTimes(int value) { return value * 2; }\n"
        "int c2fbStaticPointerState(int delta) {\n"
        "    static int *pointer = 0U;\n"
        "    if (pointer == 0) pointer = &c2fbStaticPointerTarget;\n"
        "    *pointer += delta;\n"
        "    return *pointer;\n"
        "}\n"
        "int c2fbStaticPointerAddress(void) {\n"
        "    static const int *pointer = &c2fbStaticPointerTarget;\n"
        "    return *pointer;\n"
        "}\n"
        "int c2fbStaticPointerString(void) {\n"
        "    static const char *pointer = \"C2FB\";\n"
        "    return pointer[1];\n"
        "}\n"
        "int c2fbStaticCallbackTypedef(int value) {\n"
        "    static C2fbUnaryCallback *callback = c2fbStaticCallbackPlus;\n"
        "    return callback(value);\n"
        "}\n"
        "int c2fbStaticCallbackInline(int value) {\n"
        "    static int (*callback)(int) = &c2fbStaticCallbackTimes;\n"
        "    return callback(value);\n"
        "}\n"
        "int c2fbStaticCallbackZeroIsNull(void) {\n"
        "    static int (*callback)(int);\n"
        "    return callback == 0;\n"
        "}\n"
    )
    candidate = source_directory / "static_pointer_candidates.bas"
    summary = run([
        converter, "translate-simple-generic-c", str(source), str(candidate), "cc",
    ])
    assert "translated 8 simple functions; skipped 0" in summary, summary
    generated = candidate.read_text()
    assert generated.count("C static scalar storage") >= 4, generated
    assert generated.count("C static callback storage") == 2, generated

    for backend, flags in (("native", []), ("gcc", ["-gen", "gcc"])):
        reference_path = source_directory / f"reference-{backend}.so"
        run(cc + ["-std=c99", "-O2", "-shared", "-fPIC", str(source),
                  "-o", str(reference_path)])
        reference = ctypes.CDLL(str(reference_path))
        output = source_directory / f"converted-{backend}.so"
        run(fbc + flags + ["-w", "all", "-dll", str(candidate), "-x", str(output)])
        converted = ctypes.CDLL(str(output))
        for library in (reference, converted):
            library.c2fbStaticPointerState.argtypes = [ctypes.c_int]
            library.c2fbStaticPointerState.restype = ctypes.c_int
            library.c2fbStaticPointerAddress.argtypes = []
            library.c2fbStaticPointerAddress.restype = ctypes.c_int
            library.c2fbStaticPointerString.argtypes = []
            library.c2fbStaticPointerString.restype = ctypes.c_int
            library.c2fbStaticCallbackTypedef.argtypes = [ctypes.c_int]
            library.c2fbStaticCallbackTypedef.restype = ctypes.c_int
            library.c2fbStaticCallbackInline.argtypes = [ctypes.c_int]
            library.c2fbStaticCallbackInline.restype = ctypes.c_int
            library.c2fbStaticCallbackZeroIsNull.argtypes = []
            library.c2fbStaticCallbackZeroIsNull.restype = ctypes.c_int
        assert reference.c2fbStaticPointerAddress() == \
            converted.c2fbStaticPointerAddress() == 31
        for delta in (5, -2, 19, -37, 0):
            assert reference.c2fbStaticPointerState(delta) == \
                converted.c2fbStaticPointerState(delta)
            assert reference.c2fbStaticPointerAddress() == \
                converted.c2fbStaticPointerAddress()
        assert reference.c2fbStaticPointerString() == \
            converted.c2fbStaticPointerString() == ord("2")
        for value in (-5, 0, 1, 42):
            assert reference.c2fbStaticCallbackTypedef(value) == \
                converted.c2fbStaticCallbackTypedef(value) == value + 3
            assert reference.c2fbStaticCallbackInline(value) == \
                converted.c2fbStaticCallbackInline(value) == value * 2
        assert reference.c2fbStaticCallbackZeroIsNull() == \
            converted.c2fbStaticCallbackZeroIsNull() == 1


def check_generic_body_automatic_callback_initializer(converter, fbc, cc, work):
    # An automatic callback initializer reads a typed field at its C declaration site.
    source_directory = work / "generic-body-automatic-callback-initializer"
    source_directory.mkdir()
    source = source_directory / "callback_initializer.c"
    source.write_text(
        "typedef struct C2fbFile C2fbFile;\n"
        "typedef struct C2fbFileMethods {\n"
        "    int (*xSectorSize)(C2fbFile *);\n"
        "} C2fbFileMethods;\n"
        "struct C2fbFile {\n"
        "    const C2fbFileMethods *pMethods;\n"
        "    int value;\n"
        "};\n"
        "int c2fbAutomaticCallbackInitializer("
        "C2fbFile *file, int useCallback) {\n"
        "    if (!useCallback) return -1;\n"
        "    int (*xSectorSize)(C2fbFile *) = file->pMethods->xSectorSize;\n"
        "    return xSectorSize(file);\n"
        "}\n"
    )
    candidate = source_directory / "callback_initializer_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
    ])
    assert "translated 1 simple functions; skipped 0" in summary, summary

    reference_path = source_directory / "reference.so"
    run(cc + ["-std=c99", "-shared", "-fPIC", str(source), "-o", str(reference_path)])
    converted_path = source_directory / "converted.so"
    run(fbc + ["-w", "all", "-dll", str(candidate), "-x", str(converted_path)],
        cwd=source_directory)
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))

    class C2fbFile(ctypes.Structure):
        pass

    callback_type = ctypes.CFUNCTYPE(ctypes.c_int, ctypes.POINTER(C2fbFile))

    class C2fbFileMethods(ctypes.Structure):
        _fields_ = [("xSectorSize", callback_type)]

    C2fbFile._fields_ = [
        ("pMethods", ctypes.POINTER(C2fbFileMethods)),
        ("value", ctypes.c_int),
    ]
    for library in (reference, converted):
        function = library.c2fbAutomaticCallbackInitializer
        function.argtypes = [ctypes.POINTER(C2fbFile), ctypes.c_int]
        function.restype = ctypes.c_int

    callback = callback_type(lambda file_pointer: file_pointer.contents.value * 3 + 5)
    methods = C2fbFileMethods(callback)
    for value in (-9, 0, 17, 1024):
        file = C2fbFile(ctypes.pointer(methods), value)
        expected = reference.c2fbAutomaticCallbackInitializer(
            ctypes.byref(file), 1)
        actual = converted.c2fbAutomaticCallbackInitializer(
            ctypes.byref(file), 1)
        assert expected == actual == value * 3 + 5, (
            f"callback initializer for {value}: C={expected}, FreeBASIC={actual}"
        )

    absent_methods = C2fbFile(None, 0)
    assert reference.c2fbAutomaticCallbackInitializer(
        ctypes.byref(absent_methods), 0) == -1
    assert converted.c2fbAutomaticCallbackInitializer(
        ctypes.byref(absent_methods), 0) == -1


def check_generic_body_callback_conditional_initializer(converter, fbc, cc, work):
    # C's conditional operator can initialize a callback from a function address or NULL.
    source_directory = work / "generic-body-callback-conditional-initializer"
    source_directory.mkdir()
    source = source_directory / "callback_conditional.c"
    source.write_text(
        "#include <stddef.h>\n"
        "static void c2fbDefaultDtor(void *object) { (void)object; }\n"
        "int c2fbConditionalCallbackInitializer(int useDefault) {\n"
        "    void (*dtorMult)(void *) = "
        "(useDefault ? &c2fbDefaultDtor : NULL);\n"
        "    return dtorMult != NULL;\n"
        "}\n"
    )
    candidate = source_directory / "callback_conditional_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
