def check_freebasic_rtlib_string_tree(converter, fbc, cc, source_root,
                                      profile_directory, work):
    # Use the RTLIB's intended ctype declarations instead of glibc's private
    # __ctype_b_loc expansion when sweeping the shared string implementations.
    source_directory = source_root / "rtlib"
    sources = sorted(
        path for path in source_directory.rglob("str_*.c")
        if "drivers" not in path.relative_to(source_directory).parts
    )
    assert sources, f"FreeBASIC RTLIB string sources are missing: {source_directory}"
    source_patterns = sorted({
        (path.parent.relative_to(source_directory).as_posix() + "/str_*.c")
        if path.parent != source_directory else "str_*.c"
        for path in sources
    })

    output_directory = work / "fbc-source-rtlib-string-tree"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    header_profile = profile_directory / "freebasic-linux-glibc-x86_64.rsp"
    body_profile = profile_directory / "freebasic-linux-glibc-x86_64-body.rsp"
    command = [
        sys.executable, str(source_unit_tool), str(source_directory),
        str(output_directory), "--tree", "--jobs=4",
        "--converter", converter, "--compiler", cc[0],
        "--header-option=@" + str(header_profile),
        "--body-option=@" + str(body_profile),
        "--header-option=--emit-source=*fb.h",
        "--header-option=--emit-source=*fb_*.h",
        "--body-option=--rename-proc-prefix=c2fbRtl_",
        "--header-compiler-option=" + f"-I{source_directory}",
        "--body-compiler-option=" + f"-I{source_directory}",
        "--body-compiler-option=-D__NO_CTYPE",
    ]
    command.extend("--source-pattern=" + pattern for pattern in source_patterns)
    summary = run(command)
    assert f"processed {len(sources)} C files; failed 0" in summary, summary
    counts = re.findall(
        r"translated (\d+) simple functions; skipped (\d+)", summary
    )
    assert len(counts) == len(sources), summary
    translated_count = sum(int(translated) for translated, _ in counts)
    skipped_count = sum(int(skipped) for _, skipped in counts)
    assert translated_count >= 100 and skipped_count == 0, summary

    candidates = sorted(output_directory.rglob("*_candidates.bas"))
    assert len(candidates) == len(sources), summary
    for candidate in candidates:
        run(fbc + [
            "-w", "all", "-c", str(candidate),
            "-o", str(candidate.with_suffix(".o")),
            "-i", str(output_directory), "-i", str(source_directory),
        ], cwd=output_directory)


def check_freebasic_rtlib_threadsafe_core(converter, fbc, cc, source_root,
                                          profile_directory, work):
    # ENABLE_MT changes FB_STRLOCK from an empty macro into runtime calls.
    source = freebasic_source_file(source_root, "rtlib/str_core.c")
    source_directory = work / "fbc-source-rtlib-threadsafe-core"
    source_directory.mkdir()
    candidate = source_directory / "str_core_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    header_profile = profile_directory / "freebasic-linux-glibc-x86_64.rsp"
    body_profile = profile_directory / "freebasic-linux-glibc-x86_64-body.rsp"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        "--header-option=@" + str(header_profile),
        "--body-option=@" + str(body_profile),
        "--header-option=--emit-source=*fb.h",
        "--header-option=--emit-source=*fb_*.h",
        "--body-option=--rename-proc-prefix=c2fbMt_",
        "--header-compiler-option=" + f"-I{source_root / 'rtlib'}",
        "--body-compiler-option=" + f"-I{source_root / 'rtlib'}",
        "--header-compiler-option=-DENABLE_MT",
        "--body-compiler-option=-DENABLE_MT",
        "--body-compiler-option=-D__NO_CTYPE",
    ])
    match = re.search(r"translated (\d+) simple functions; skipped 0", summary)
    assert match is not None and int(match.group(1)) >= 10, summary
    generated = candidate.read_text()
    assert 'Alias "fb_StrLock"' in generated, generated
    assert 'Alias "fb_StrUnlock"' in generated, generated
    assert "c2fbMt_fb_StrLock()" in generated, generated
    assert "c2fbMt_fb_StrUnlock()" in generated, generated

    wrapper = source_directory / "str_core_check.bas"
    wrapper.write_text(f'#include once "{candidate.name}"\n')
    run(fbc + ["-mt", "-w", "all", "-c", str(wrapper), "-o",
               str(source_directory / "str_core.o"), "-i",
               str(source_directory), "-i", str(source_root / "rtlib")],
        cwd=source_directory)


def check_freebasic_gfx3_data(converter, fbc, cc, source_root, work):
    # The LZW decoder combines an enum-bounded record array with C11 atomics.
    source_directory = work / "fbc-source-gfxlib3-data"
    source_directory.mkdir()
    source = freebasic_source_file(source_root, "gfxlib3/compat/gfx3_data.c")
    candidate = source_directory / "gfx3_data_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        "--include-header-types",
        "--body-option=--atomic-mutex",
        "--header-compiler-option=" + f"-I{source_root / 'rtlib'}",
        "--body-compiler-option=" + f"-I{source_root / 'rtlib'}",
        "--header-compiler-option=" + f"-I{source_root / 'gfxlib3'}",
        "--body-compiler-option=" + f"-I{source_root / 'gfxlib3'}",
        "--header-compiler-option=" + f"-I{source_root / 'gfxlib2'}",
        "--body-compiler-option=" + f"-I{source_root / 'gfxlib2'}",
    ])
    assert "translated 8 simple functions; skipped 0" in summary, summary
    assert "Function data_decode" in candidate.read_text(), candidate.read_text()

    converted_path = source_directory / "gfx3_data_converted.so"
    run(fbc + ["-mt", "-w", "all", "-dll", str(candidate), "-x",
               str(converted_path)], cwd=source_directory)
    reference_path = source_directory / "gfx3_data_reference.so"
    run(cc + [
        "-std=c11", "-shared", "-fPIC", "-pthread", "-include", "sys/types.h",
        f"-I{source_root / 'rtlib'}", f"-I{source_root / 'gfxlib3'}",
        f"-I{source_root / 'gfxlib2'}", str(source), "-o", str(reference_path),
    ], cwd=source_directory)

    inline_data = freebasic_source_file(
        source_root, "gfxlib2/gfxdata_inline.h").read_text()

    def data_offset(name):
        match = re.search(
            rf"(?m)^#define\s+{re.escape(name)}\s+(0x[0-9A-Fa-f]+|[0-9]+)\s*$",
            inline_data,
        )
        assert match is not None, f"missing {name} in gfxdata_inline.h"
        return int(match.group(1), 0)

    data_ranges = (
        ("fb_gfx3_data_font_8x8", data_offset("DATA_FONT_8"),
         data_offset("DATA_FONT_14")),
        ("fb_gfx3_data_font_8x14", data_offset("DATA_FONT_14"),
         data_offset("DATA_FONT_16")),
        ("fb_gfx3_data_font_8x16", data_offset("DATA_FONT_16"),
         data_offset("DATA_PAL_2")),
        ("fb_gfx3_data_palette_256", data_offset("DATA_PAL_256"),
         data_offset("DATA_SIZE")),
    )
    reference = ctypes.CDLL(str(reference_path))
    converted = ctypes.CDLL(str(converted_path))
    functions = {}
    for name, _, _ in data_ranges:
        reference_function = getattr(reference, name)
        converted_function = getattr(converted, name)
        reference_function.restype = ctypes.c_void_p
        converted_function.restype = ctypes.c_void_p
        functions[name] = converted_function

    # Concurrent first calls exercise the generated compare-exchange path.
    with ThreadPoolExecutor(max_workers=8) as executor:
        initialized_pointers = list(executor.map(
            lambda _: functions["fb_gfx3_data_font_8x8"](), range(32)
        ))
    assert initialized_pointers[0] and all(
        pointer == initialized_pointers[0] for pointer in initialized_pointers
    ), "concurrent gfx3 initialization returned inconsistent font pointers"

    for name, start, end in data_ranges:
        size = end - start
        assert size > 0, f"invalid gfx3 data range for {name}"
        expected_pointer = getattr(reference, name)()
        actual_pointer = functions[name]()
        assert expected_pointer and actual_pointer, f"{name} returned NULL"
        expected = ctypes.string_at(expected_pointer, size)
        actual = ctypes.string_at(actual_pointer, size)
        assert actual == expected, f"translated {name} bytes differ from C"


def check_freebasic_rtlib_array_core(converter, fbc, cc, source_root,
                                     profile_directory, work):
    # Compare the array runtime's bound arithmetic and descriptor queries to C.
    source_directory = work / "fbc-source-rtlib-array-core"
    source_directory.mkdir()
    source = freebasic_source_file(source_root, "rtlib/array_core.c")
    candidate = source_directory / "array_core_candidates.bas"
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    header_profile = profile_directory / "freebasic-linux-glibc-x86_64.rsp"
    body_profile = profile_directory / "freebasic-linux-glibc-x86_64-body.rsp"
    summary = run([
        sys.executable, str(source_unit_tool), str(source), str(candidate),
        "--converter", converter, "--compiler", cc[0],
        "--include-header-types",
        "--header-option=@" + str(header_profile),
        "--body-option=@" + str(body_profile),
        "--header-compiler-option=" + f"-I{source_root / 'rtlib'}",
        "--body-compiler-option=" + f"-I{source_root / 'rtlib'}",
    ])
    assert "translated 4 simple functions; skipped 0" in summary, summary
    type_context = candidate.with_name(candidate.stem + "_types.bi")
    generated_types = type_context.read_text()
    assert "Type c2fb__FBARRAY As" in generated_types, generated_types
    assert "Type c2fb_size_t As UInteger" in generated_types, generated_types
    run(fbc + [
        "-w", "all", "-c", str(candidate), "-o",
        str(source_directory / "array_core_candidates.o"),
        "-i", str(source_directory), "-i", str(source_root / "rtlib"),
    ], cwd=source_directory)

    reference_path = source_directory / "array_core_reference.so"
    run(cc + [
        "-std=c99", "-shared", "-fPIC", "-include", "sys/types.h",
        str(source),
        "-I" + str(source_root / "rtlib"), "-o", str(reference_path),
    ], cwd=source_directory)

    wrapper = source_directory / "array_core_check.bas"
    wrapper.write_text(
        '#include once "array_core_candidates.bas"\n'
        "Function c2fbRunArrayCalcElements CDecl "
        'Alias "c2fbRunArrayCalcElements" (ByVal dimensions As c2fb_size_t, '
        "ByVal lowerBounds As Const ssize_t Ptr, "
        "ByVal upperBounds As Const ssize_t Ptr) As c2fb_size_t Export\n"
        "    Return fb_hArrayCalcElements(dimensions, lowerBounds, upperBounds)\n"
        "End Function\n"
        "Function c2fbRunArrayCalcDiff CDecl "
        'Alias "c2fbRunArrayCalcDiff" (ByVal dimensions As c2fb_size_t, '
        "ByVal lowerBounds As Const ssize_t Ptr, "
        "ByVal upperBounds As Const ssize_t Ptr) As ssize_t Export\n"
        "    Return fb_hArrayCalcDiff(dimensions, lowerBounds, upperBounds)\n"
        "End Function\n"
        "Function c2fbRunArrayLen CDecl "
        'Alias "c2fbRunArrayLen" (ByVal array As c2fb__FBARRAY Ptr) '
        "As c2fb_size_t Export\n"
        "    Return fb_ArrayLen(array)\n"
        "End Function\n"
        "Function c2fbRunArraySize CDecl "
        'Alias "c2fbRunArraySize" (ByVal array As c2fb__FBARRAY Ptr) '
        "As c2fb_size_t Export\n"
        "    Return fb_ArraySize(array)\n"
        "End Function\n"
    )
    translated_path = source_directory / "array_core_translated.so"
    run(fbc + ["-w", "all", "-dll", str(wrapper), "-x",
               str(translated_path)], cwd=source_directory)

    reference = ctypes.CDLL(str(reference_path))
    translated = ctypes.CDLL(str(translated_path))
    ssize_pointer = ctypes.POINTER(ctypes.c_ssize_t)
    for library, elements_name, diff_name in (
        (reference, "fb_hArrayCalcElements", "fb_hArrayCalcDiff"),
        (translated, "c2fbRunArrayCalcElements", "c2fbRunArrayCalcDiff"),
    ):
        elements = getattr(library, elements_name)
        elements.argtypes = [ctypes.c_size_t, ssize_pointer, ssize_pointer]
        elements.restype = ctypes.c_size_t
        diff = getattr(library, diff_name)
        diff.argtypes = [ctypes.c_size_t, ssize_pointer, ssize_pointer]
        diff.restype = ctypes.c_ssize_t

    for lower_values, upper_values in (
        ([-2], [3]),
        ([-2, 0], [3, 4]),
        ([1, -3, 5], [2, 1, 7]),
    ):
        lower_bounds = (ctypes.c_ssize_t * len(lower_values))(*lower_values)
        upper_bounds = (ctypes.c_ssize_t * len(upper_values))(*upper_values)
        dimensions = len(lower_values)
        assert translated.c2fbRunArrayCalcElements(
            dimensions, lower_bounds, upper_bounds
        ) == reference.fb_hArrayCalcElements(
            dimensions, lower_bounds, upper_bounds
        )
        assert translated.c2fbRunArrayCalcDiff(
            dimensions, lower_bounds, upper_bounds
        ) == reference.fb_hArrayCalcDiff(
            dimensions, lower_bounds, upper_bounds
        )

    assert translated.c2fbRunArrayCalcDiff(0, None, None) == \
        reference.fb_hArrayCalcDiff(0, None, None) == 0

    class ArrayDimension(ctypes.Structure):
        _fields_ = [
            ("elements", ctypes.c_size_t),
            ("lbound", ctypes.c_ssize_t),
            ("ubound", ctypes.c_ssize_t),
        ]

    class ArrayDescriptor(ctypes.Structure):
        _fields_ = [
            ("data", ctypes.c_void_p),
            ("ptr", ctypes.c_void_p),
            ("size", ctypes.c_size_t),
            ("element_len", ctypes.c_size_t),
            ("dimensions", ctypes.c_size_t),
            ("flags", ctypes.c_size_t),
            ("dimTB", ArrayDimension * 1),
        ]

    for library, length_name, size_name in (
        (reference, "fb_ArrayLen", "fb_ArraySize"),
        (translated, "c2fbRunArrayLen", "c2fbRunArraySize"),
    ):
        length = getattr(library, length_name)
        length.argtypes = [ctypes.c_void_p]
        length.restype = ctypes.c_size_t
        size = getattr(library, size_name)
        size.argtypes = [ctypes.c_void_p]
        size.restype = ctypes.c_size_t

    descriptor = ArrayDescriptor()
    descriptor.data = ctypes.c_void_p(0x12340)
    descriptor.ptr = ctypes.c_void_p(0x12340)
    descriptor.size = 84
    descriptor.element_len = 7
    descriptor.dimensions = 1
    assert reference.fb_ArrayLen(ctypes.byref(descriptor)) == \
        translated.c2fbRunArrayLen(ctypes.byref(descriptor)) == 12
    assert reference.fb_ArraySize(ctypes.byref(descriptor)) == \
        translated.c2fbRunArraySize(ctypes.byref(descriptor)) == 84
    assert reference.fb_ArrayLen(None) == translated.c2fbRunArrayLen(None) == 0
    descriptor.ptr = None
    assert reference.fb_ArrayLen(ctypes.byref(descriptor)) == \
        translated.c2fbRunArrayLen(ctypes.byref(descriptor)) == 0
    assert reference.fb_ArraySize(None) == translated.c2fbRunArraySize(None) == 0


def check_freebasic_rtlib_array_bounds(converter, fbc, cc, source_root,
                                       profile_directory, work):
    # These exported names overlap FBC's own runtime helpers, so the ported
    # implementations keep the C linker alias behind a private procedure name.
    source_directory = work / "fbc-source-rtlib-array-bounds"
    source_directory.mkdir()
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
    header_profile = profile_directory / "freebasic-linux-glibc-x86_64.rsp"
    body_profile = profile_directory / "freebasic-linux-glibc-x86_64-body.rsp"
    candidates = {}
    translated_libraries = {}

    for suffix in ("LBound", "UBound"):
        source_name = "array_" + suffix.lower() + ".c"
        candidate = source_directory / f"array_{suffix.lower()}_candidates.bas"
        summary = run([
            sys.executable, str(source_unit_tool),
            str(freebasic_source_file(
                source_root, Path("rtlib") / source_name)), str(candidate),
            "--converter", converter, "--compiler", cc[0],
            "--include-header-types",
            "--header-option=@" + str(header_profile),
            "--body-option=@" + str(body_profile),
            "--body-option=--rename-proc-prefix=c2fbPorted_",
            "--header-compiler-option=" + f"-I{source_root / 'rtlib'}",
            "--body-compiler-option=" + f"-I{source_root / 'rtlib'}",
        ])
        assert "translated 1 simple functions; skipped 0" in summary, summary
        generated = candidate.read_text()
        assert f"Function c2fbPorted_fb_Array{suffix} " in generated, generated
        run(fbc + [
            "-w", "all", "-c", str(candidate), "-o",
            str(source_directory / f"array_{suffix.lower()}_candidates.o"),
            "-i", str(source_directory), "-i", str(source_root / "rtlib"),
        ], cwd=source_directory)

        wrapper = source_directory / f"array_{suffix.lower()}_check.bas"
        wrapper.write_text(
            f'#include once "{candidate.name}"\n'
            f"Function c2fbRunArray{suffix} CDecl "
            f'Alias "c2fbRunArray{suffix}" '
            "(ByVal array As c2fb__FBARRAY Ptr, "
            "ByVal dimension As ssize_t) As ssize_t Export\n"
            f"    Return c2fbPorted_fb_Array{suffix}(array, dimension)\n"
            "End Function\n"
        )
        translated_library = source_directory / f"array_{suffix.lower()}.so"
        run(fbc + [
            "-w", "all", "-dll", str(wrapper), "-x", str(translated_library),
            "-i", str(source_directory), "-i", str(source_root / "rtlib"),
        ], cwd=source_directory)
        candidates[suffix] = candidate
        translated_libraries[suffix] = translated_library

    reference_path = source_directory / "array_bounds_reference.so"
    run(cc + [
        "-std=c99", "-shared", "-fPIC", "-include", "sys/types.h",
        str(freebasic_source_file(source_root, "rtlib/array_lbound.c")),
        str(freebasic_source_file(source_root, "rtlib/array_ubound.c")),
        "-I" + str(source_root / "rtlib"), "-o", str(reference_path),
    ], cwd=source_directory)

    class ArrayDimension(ctypes.Structure):
        _fields_ = [
            ("elements", ctypes.c_size_t),
            ("lbound", ctypes.c_ssize_t),
            ("ubound", ctypes.c_ssize_t),
        ]

    class ArrayDescriptor(ctypes.Structure):
        _fields_ = [
            ("data", ctypes.c_void_p),
            ("ptr", ctypes.c_void_p),
            ("size", ctypes.c_size_t),
            ("element_len", ctypes.c_size_t),
            ("dimensions", ctypes.c_size_t),
            ("flags", ctypes.c_size_t),
            ("dimTB", ArrayDimension * 2),
        ]

    reference = ctypes.CDLL(str(reference_path))
    translated = {
        suffix: ctypes.CDLL(str(library_path))
        for suffix, library_path in translated_libraries.items()
    }
    for suffix in ("LBound", "UBound"):
        reference_function = getattr(reference, "fb_Array" + suffix)
        reference_function.argtypes = [
            ctypes.POINTER(ArrayDescriptor), ctypes.c_ssize_t,
        ]
        reference_function.restype = ctypes.c_ssize_t
        translated_function = getattr(translated[suffix], "c2fbRunArray" + suffix)
        translated_function.argtypes = [ctypes.c_void_p, ctypes.c_ssize_t]
        translated_function.restype = ctypes.c_ssize_t

    for is_allocated in (False, True):
        descriptor = ArrayDescriptor()
        descriptor.data = ctypes.c_void_p(0x12340) if is_allocated else None
        descriptor.ptr = ctypes.c_void_p(0x22340) if is_allocated else None
        descriptor.dimensions = 2
        descriptor.dimTB[0].elements = 8
        descriptor.dimTB[0].lbound = -3
        descriptor.dimTB[0].ubound = 4
        descriptor.dimTB[1].elements = 10
        descriptor.dimTB[1].lbound = 0
        descriptor.dimTB[1].ubound = 9
        for dimension in (0, 1, 2, 3, -1):
            for suffix in ("LBound", "UBound"):
                expected = getattr(reference, "fb_Array" + suffix)(
                    ctypes.byref(descriptor), dimension
                )
                actual = getattr(translated[suffix], "c2fbRunArray" + suffix)(
                    ctypes.byref(descriptor), dimension
                )
                assert actual == expected, (
                    is_allocated, dimension, suffix, expected, actual
                )


def check_freebasic_source_libraries(converter, fbc, cc, source_root,
                                     profile_directory, work):
    # Exercise real GFXLIB, RTLIB, and SFXLIB modules without writing into the
    # compiler checkout. The generated bindings and objects stay under work.
    assert platform.system() == "Linux" and platform.machine().lower() in (
        "x86_64", "amd64",
    ), "the current FreeBASIC source probe uses the Linux x86-64 ABI profile"
    check_freebasic_pthread_profile_layout(fbc, cc, work)
    source_root = freebasic_source_root(source_root)
    source_unit_tool = Path(__file__).resolve().parents[1] / "c2fb_source_unit.py"
