            "--header-compiler-option=" + f"-I{source_root / 'sfxlib'}",
            "--header-compiler-option=" + f"-I{source_root / 'sfxlib/linux'}",
            "--header-compiler-option=" + f"-I{source_root / 'sfxlib/unix'}",
